import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-f-001","clusterId":"F","werkstueckRef":"F.0","stufe":1,"question":"Ein Forschungsteam testet eine kühne, noch unbewiesene Hypothese. Der entscheidende Versuch fällt negativ aus. Woran erkennst du, dass das Team trotz der gewagten Idee ehrlich wissenschaftlich arbeitet und nicht nur den Anschein davon erzeugt?","options":["Es beschreibt den negativen Versuch in sorgfältiger Fachsprache mit Formeln, Messwerten und Fachbegriffen.","Es besteht aus Fachleuten anerkannter Universitäten, die akademische Titel tragen und den Versuch betreuten.","Es erkennt das Scheitern des entscheidenden Tests an und passt die Hypothese an oder gibt sie ganz auf.","Es hält trotz des negativen Tests an der kühnen Hypothese fest, denn große Entdeckungen standen oft gegen die Lehrmeinung."],"correctIndex":2,"explanation":"Eine kühne Hypothese ist noch kein Warnsignal: Spekulation ist legitim, solange sie prüfbar bleibt. Entscheidend ist der Umgang mit dem Scheitern: In ehrlicher Forschung an der Grenze des Wissens wird ein gescheiterter Test anerkannt und führt dazu, dass die Hypothese angepasst oder aufgegeben wird. In der Pseudowissenschaft werden widersprechende Befunde dagegen oft ignoriert, wegerklärt oder umgedeutet. Wer ein negatives Ergebnis ernst nimmt, zeigt, dass die Idee an der Wirklichkeit scheitern kann, und genau das unterscheidet ehrliche Forschung von bloßer Imitation. Die anderen Merkmale klingen nach Wissenschaft, lassen sich aber nachahmen: Fachsprache, Formeln und Messwerte sagen nichts darüber, ob ein Team eine Widerlegung akzeptiert. Titel und Universitäten schützen nicht vor Selbsttäuschung. Und am kühnen Festhalten trotz Scheiterns zeigt sich keine Ehrlichkeit, denn Kühnheit allein belegt nichts.","coreRule":"⚡ Eine Idee darf kühn sein und scheitern; verdächtig wird sie, wenn jedes Scheitern wegerklärt wird.","beleg":"Werkstück F.0 (Kontext & Tiefe, Abschnitte II und III)","status":"entwurf","kurz":"Ehrlich ist ein Team, das einen gescheiterten Test gelten lässt und die Hypothese anpasst oder aufgibt. So zeigt sich, dass die Idee an der Wirklichkeit scheitern kann. Kühnheit, Fachsprache und Titel lassen sich dagegen auch bloß vorführen.","prueffrage":"Welches Ergebnis hätte das Team vorab als Scheitern seiner Hypothese gelten lassen, und gilt das jetzt noch?","rueckmeldung":[{"option":0,"text":"Sorgfältige Beschreibung mit Formeln und Messwerten wirkt seriös und ist für sich genommen nichts Schlechtes. Sie lässt sich aber auch ohne ehrliche Absicht nachahmen und zeigt nicht, ob das Team das Scheitern wirklich gelten lässt."},{"option":1,"text":"Titel und angesehene Universitäten stehen meist für echte Fachkenntnis, und diese ist wertvoll. Vor Selbsttäuschung schützt sie aber nicht, und sie zeigt nicht, wie das Team mit der Widerlegung umgeht."},{"option":3,"text":"Es stimmt, dass manche große Entdeckung zunächst gegen die Lehrmeinung stand. Durchgesetzt haben sich solche Ideen aber, weil sie Prüfungen bestanden, nicht weil man negative Tests übergangen hat. Festhalten allein belegt weder Mut noch Ehrlichkeit."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1","abruf":"2026-10-12"},{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"5bd227544941908b"}},{"id":"qx-f-002","clusterId":"F","werkstueckRef":"F.0","stufe":2,"question":"Was ist an dieser Reaktion auf die Pressemitteilung der Denkfehler?","scenario":"Eine Pressemitteilung meldet ein unerwartetes Signal im Detektor: „Es könnte auf neue Physik hindeuten. Messfehler können wir noch nicht ausschließen, deshalb planen wir unabhängige Wiederholungen.“ Ein Kollege winkt ab: „Unbewiesen heißt unwissenschaftlich. Das ist doch genauso Quatsch wie Astrologie.“","options":["Er setzt „noch nicht bewiesen“ mit „unwissenschaftlich“ gleich, obwohl die Mitteilung Unsicherheiten benennt und Wiederholungen ankündigt.","Er beruft sich auf die Mehrheit der Fachwelt: Weil die meisten Physiker keine neue Physik erwarten, gilt ihm das Signal schon als widerlegt.","Er kehrt die Beweislast um: Nicht die Forschenden, sondern die Skeptiker müssten zeigen, dass das Signal im Detektor kein Messfehler ist.","Er lässt sich von seiner Erwartung leiten: Er sucht nur Gründe gegen neue Physik und übersieht die Belege, die dafür bereits vorliegen."],"correctIndex":0,"explanation":"„Nicht bewiesen“ und „widerlegt“ sind verschiedene Zustände. Eine spekulative, aber prüfbare Hypothese, deren Urheber ihre Unsicherheit offen benennen und weitere Tests planen, verhält sich methodisch wie seriöse Forschung am Rand des Wissens, nicht wie Pseudowissenschaft. Was Pseudowissenschaft (etwa Astrologie) auszeichnet, ist nicht, dass sie unbewiesen wäre, sondern dass sie widersprüchliche Beweise ignoriert oder wegerklärt und die Beweislast systematisch umkehrt. Entscheidend ist die Methode, nicht die Seltsamkeit oder der noch ausstehende Beweis. Wer jede unbestätigte Idee pauschal als Pseudowissenschaft ablehnt, riskiert, potenziell revolutionäre, aber noch unbewiesene Konzepte zu verpassen. Umgekehrt gibt es auch die Falle des Naiven, der jede als „alternativ“ dargestellte Idee für legitime Grenzwissenschaft hält.","coreRule":"⚡ Maßstab ist die Methode, nicht die Seltsamkeit: „noch nicht bewiesen“ ist nicht „widerlegt“.","beleg":"Werkstück F.0 (Anwendung & Relevanz; Red Flags; Werkbank-Frage)","status":"entwurf","kurz":"„Noch nicht bewiesen“ heißt nicht „unwissenschaftlich“. Wer Unsicherheiten offen benennt und unabhängige Wiederholungen plant, arbeitet methodisch seriös; entscheidend ist die Methode, nicht der ausstehende Beweis.","prueffrage":"Was haben das Signal im Detektor und die Astrologie gemeinsam, und worin unterscheiden sie sich?","rueckmeldung":[{"option":1,"text":"Die Skepsis der Fachwelt gegenüber neuer Physik ist ein gewohnter Hintergrund. Der Kollege beruft sich darauf aber nicht, sondern auf den fehlenden Beweis. Und „nicht bewiesen“ heißt nicht „widerlegt“."},{"option":2,"text":"Eine Beweislastumkehr wäre ein echter Fehler, sie trifft hier aber nicht zu. Der Kollege verlangt nichts von Skeptikern, er lehnt das Signal einfach ab, obwohl die Mitteilung Messfehler offen als Möglichkeit nennt und Wiederholungen ankündigt."},{"option":3,"text":"Erwartungen können tatsächlich den Blick verengen. Hier liegen aber noch gar keine Belege vor, die er übersehen könnte: Das Signal gilt selbst als ungeklärt. Sein Fehler ist die pauschale Ablehnung, nicht eine einseitige Beweissuche."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.5, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"d8bd42993a26a903"}},{"id":"qx-f-003","clusterId":"F","werkstueckRef":"F.0","stufe":3,"question":"Eine Anbieterin wirbt für ihre Lehre als „mutige Grenzwissenschaft, die von der dogmatischen Schulwissenschaft unterdrückt wird“. Du willst herausfinden, ob die Lehre ernsthafte Forschung am Rand des Wissens oder Pseudowissenschaft ist. Welche Prüfung bringt dich am sichersten weiter?","options":["Du fragst, wie viele Menschen berichten, dass ihnen die Lehre geholfen hat, denn viele übereinstimmende Erfahrungen sprechen für ihre Wirksamkeit.","Du fragst, welchen Test die Anbieterin vorschlägt und was für sie als Scheitern der Idee gälte, denn daran zeigt sich, ob sie sich überprüfen lässt.","Du prüfst, welche Ausbildung und welche Titel die Anbieterin hat, denn wer fachlich ausgewiesen ist, vertritt eher ernsthafte Forschung.","Du fragst, wie die etablierte Fachwelt auf die Lehre reagiert hat, denn eine einhellige Ablehnung zeigt, dass sie sich nicht bewährt hat."],"correctIndex":1,"explanation":"Ob eine Idee ernsthafte Erkundung oder Pseudowissenschaft ist, entscheidet sich an der Methode, nicht am Etikett und nicht an der Reaktion der anderen. Wer ehrlich am Rand des Wissens forscht, legt offen, wie man seine Idee testen kann, und akzeptiert, dass ein Scheitern des Tests die Idee widerlegt. Die Kombination aus Selbstlob als „mutig“ und dem Vorwurf, unterdrückt zu werden, ist dagegen ein Warnsignal: Sie erklärt Kritik im Voraus zum Beweis für die eigene Richtigkeit und macht die Lehre damit unangreifbar. Die anderen Prüfungen klingen vernünftig, entscheiden aber nichts: Erfolgsberichte Einzelner sind keine kontrollierten Belege und lassen sich für fast jede Lehre finden. Titel und Ausbildung sagen nichts über die Methode, denn auch Ausgewiesene können Unprüfbares vertreten. Und die Ablehnung durch die Fachwelt entscheidet nichts, denn auch ernsthafte Außenseiterideen stoßen zunächst auf Ablehnung; erst der Test zeigt, ob eine Lehre taugt.","coreRule":"⚡ Frag nicht „Wie seltsam?“, sondern „Wo ist der Test, und was gälte als Scheitern?“","quote":"","quoteLabel":"","beleg":"Werkstück F.0 (Red Flags; Anwendung & Relevanz; Das Härten im Feuer, Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Ob eine Lehre ernsthafte Randforschung ist, zeigt sich an der Methode: Nennt sie einen Test und akzeptiert sie, dass ein Scheitern die Idee widerlegt? Wer Kritik im Voraus zum Beweis erklärt, macht sich unangreifbar.","prueffrage":"Was weißt du über die Lehre selbst, nachdem die Anbieterin sie „mutig“ und „unterdrückt“ genannt hat?","rueckmeldung":[{"option":0,"text":"Viele Berichte beeindrucken, und manche Erfahrungen sind sicher echt. Als Beleg taugen sie aber kaum: Sie sind unkontrolliert und lassen sich für fast jede Lehre finden, ohne dass sie die Lehre selbst belegen."},{"option":2,"text":"Eine Ausbildung zeigt, dass jemand Fachkenntnis erworben hat. Über die Methode sagt sie aber nichts, denn auch fachlich Ausgewiesene können Unprüfbares vertreten. Entscheidend ist, ob die Idee testbar ist."},{"option":3,"text":"Ablehnung durch die Fachwelt ist ein Hinweis, mehr nicht: Auch ernsthafte Außenseiterideen stoßen zunächst auf Widerstand. Ob eine Lehre taugt, zeigt erst ein Test, nicht die Zahl derer, die sie ablehnen."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"43985581a84e6644"}},{"id":"qx-f-004","clusterId":"F","werkstueckRef":"F.0","stufe":4,"question":"Ein Bekannter wirft Skeptikern vor: „Ihr lehnt einfach alles Neue ab. Früher hat man auch über Ideen gelacht, die später stimmten.“ Welche Antwort geht auf den Einwand am besten ein?","options":["Bei neuen Behauptungen lohnt der Blick auf Geldgeber und Interessen, denn wer von einer Idee profitiert, urteilt selten neutral, und das trifft Außenseiter wie Etablierte.","Bei neuen Ideen sollte man zuerst fragen, wie ausgewiesen die Kritiker im jeweiligen Fach sind, denn ein Urteil aus einem fremden Fachgebiet hat nur geringes Gewicht.","Zuerst sollte geklärt werden, was mit „neu“ und was mit „Skeptiker“ gemeint ist, denn ohne genaue Begriffe redet man aneinander vorbei und kann dem Vorwurf nicht sachlich begegnen.","Neues ist willkommen, wenn es sich prüfen lässt, doch die meisten solcher Ideen scheitern am Test, und nur wenige setzen sich am Ende als gesichertes Wissen durch."],"correctIndex":3,"explanation":"Der Einwand verwechselt zwei Dinge: ob eine Idee neu oder ungewöhnlich ist und ob sie sich prüfen lässt. Entscheidend ist die Methode, nicht die Seltsamkeit der Behauptung. Zwei Fallen liegen nah. In die Falle des Dogmatikers tappt, wer jede neue, seltsam klingende Idee pauschal ablehnt und so potenziell revolutionäre Konzepte verpasst. In die Falle des Naiven tappt, wer jede als „alternativ“ oder „unterdrückt“ dargestellte Idee für legitim hält und so Scharlatanen auf den Leim geht. Die angemessene Haltung gegenüber spekulativen Ideen ist offene, aber kritische Neugier („Wie können wir sie testen?“). Ob eine Idee sich lohnt, zeigt der Test: Die meisten Ideen am Rand des gesicherten Wissens scheitern und verschwinden, nur wenige entwickeln sich zu etablierter Wissenschaft. Geldgeber und Interessen zu prüfen ist sinnvoll, wenn jemand etwas verkauft oder finanziert, doch der Vorwurf lautet hier nicht, dass jemand Interessen verfolgt, sondern dass Neues pauschal abgelehnt werde. Die Fachkenntnis von Kritikern zu hinterfragen hilft, wenn ein Urteil strittig ist, beantwortet aber nicht den Verdacht, Neues werde grundsätzlich abgewiesen. Begriffe zu klären ist nützlich bei unklaren Aussagen, doch der Einwand ist verständlich genug, um in der Sache beantwortet zu werden.","coreRule":"⚡ Offen für Neues, aber nur nach Methode: Prüfbarkeit zählt, nicht Außenseiterstatus. Die meisten Randideen scheitern, einige wenige werden Wissen.","beleg":"Werkstück F.0 (Anwendung & Relevanz: Falle des Dogmatikers und des Naiven; Kontext & Tiefe, Abschnitt II „Fortschritt“)","status":"entwurf","kurz":"Der Einwand verwechselt „neu“ mit „prüfbar“: Entscheidend ist, ob sich eine Idee testen lässt. Wer alles Neue ablehnt, verpasst Gutes, wer alles Neue glaubt, fällt auf Scharlatane herein, denn die meisten Randideen scheitern am Test.","prueffrage":"Wie viele der Ideen, über die früher gelacht wurde, stellten sich später als richtig heraus, und wie viele nicht?","rueckmeldung":[{"option":0,"text":"Geldgeber und Interessen zu prüfen ist sinnvoll, wenn jemand etwas verkauft oder finanziert. Der Vorwurf lautet hier aber nicht, dass jemand Interessen verfolgt, sondern dass Neues pauschal abgelehnt werde, und darauf gibt der Blick auf Geld keine Antwort."},{"option":1,"text":"Wie fachkundig Kritiker sind, ist bei strittigen Urteilen eine berechtigte Frage. Den Verdacht, Neues werde grundsätzlich abgewiesen, räumt das aber nicht aus, denn es sagt nichts darüber, ob sich die Idee prüfen lässt."},{"option":2,"text":"Begriffsklärung hilft bei unklaren Aussagen, doch dieser Einwand ist verständlich genug, um in der Sache beantwortet zu werden. Wer erst über Wörter streitet, weicht der eigentlichen Frage aus, wie sich die neue Idee testen lässt."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.5, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"8a2db48007ff070b"}},{"id":"qx-f-005","clusterId":"F","werkstueckRef":"F.1.1","stufe":1,"question":"Eine Prüferin stellt bei einer Heilmethode fest: Die Beweislast wird umgekehrt, die Aussagen sind nicht widerlegbar, es gibt fast nur Erfolgsgeschichten statt kontrollierter Studien, kritische Studien werden ignoriert, die Grundlehre ist seit Jahrhunderten unverändert und mit der Methode lassen sich teure Seminare verkaufen. Was darfst du daraus am vernünftigsten schließen?","options":["Die Methode imitiert sehr wahrscheinlich nur den Anschein von Wissenschaft, auch wenn nicht jedes denkbare Warnzeichen vorliegt.","Die Methode ist sehr wahrscheinlich ein vorsätzlicher Betrug, denn wer teure Seminare verkauft, täuscht seine Kundschaft bewusst.","Das Muster zeigt nur, dass die Anbieter unseriös auftreten; ob die Methode wirkt, lässt sich daraus nicht einmal abschätzen.","Jedes dieser Warnzeichen kommt gelegentlich auch bei seriöser Forschung vor; aus der Liste lässt sich daher nichts ableiten."],"correctIndex":0,"explanation":"Die Warnzeichen betreffen Methode und Verhalten, nicht den Inhalt jeder Einzelbehauptung. Eine Disziplin muss nicht alle denkbaren Kriterien erfüllen, damit das Muster aussagekräftig ist: Je mehr davon zutreffen, desto wahrscheinlicher ist es, dass nur die äußere Form von Wissenschaft nachgeahmt wird, ohne ihre Prinzipien (Prüfbarkeit, Selbstkorrektur, Offenheit für Gegenbeweise) zu befolgen. Das ist ein Wahrscheinlichkeitsurteil über die Methode, kein Beweis gegen jede einzelne Aussage.","coreRule":"⚡ Methodische Warnzeichen sind ein Scanner für Verhalten: Je mehr Treffer, desto wahrscheinlicher Imitation von Wissenschaft, aber nie ein Beweis.","beleg":"Werkstück F.1.1 (Kontext & Tiefe: 10-Punkte-Checkliste, Schlusssatz)","status":"entwurf","scenario":"","kurz":"Je mehr dieser Zeichen zusammenkommen, desto wahrscheinlicher ahmt die Methode nur die Form von Wissenschaft nach, ohne ihre Prinzipien zu befolgen. Das ist ein Urteil über die Methode, kein Beweis gegen jede Einzelaussage.","prueffrage":"Wie viele der aufgezählten Auffälligkeiten treffen bei dieser Heilmethode zugleich zu?","rueckmeldung":[{"option":1,"text":"Teure Seminare sind ein Warnzeichen, aber Gewinnstreben beweist keine Täuschungsabsicht: Anbieter können selbst überzeugt sein. Das Muster urteilt über die Methode, nicht über die Absicht der Anbieter."},{"option":2,"text":"Das Muster widerlegt tatsächlich keine einzelne Behauptung. Es sagt aber durchaus etwas über die Methode aus und verschiebt die Wahrscheinlichkeit, ob sie Wirksamkeit belegen kann. Gar nichts abschätzen zu können, geht zu weit."},{"option":3,"text":"Einzelne Zeichen kommen tatsächlich auch bei seriöser Forschung vor. Entscheidend ist hier aber das Zusammentreffen mehrerer: Das Muster als Ganzes ist aussagekräftig, auch wenn jedes Zeichen für sich es nicht wäre."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1, 5.2","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1e2624731f1dbbae"}},{"id":"qx-f-006","clusterId":"F","werkstueckRef":"F.1.1","stufe":2,"question":"Was ist an dieser Aussage aus Sicht der wissenschaftlichen Methode das Kernproblem?","scenario":"In einem Reiki-Kurs sagt der Leiter: „Wenn die Energieheilung bei dir nicht gewirkt hat, hat deine Skepsis den Energiefluss blockiert.“","options":["Sie verlangt vom Skeptiker, die Nichtexistenz der Energie zu beweisen, statt selbst Belege zu liefern.","Sie macht die Behauptung unwiderlegbar, weil jedes Scheitern dem Prüfenden angelastet werden kann.","Sie stützt sich auf einzelne Erfolgsgeschichten, statt auf kontrollierte Studien zu verweisen.","Sie greift nur die günstigen Ergebnisse heraus und übergeht die Studien, die dagegensprechen."],"correctIndex":1,"explanation":"Eine Behauptung, die jedes Scheitern auf den Prüfenden abwälzt, kann durch kein Experiment widerlegt werden: Wirkt die Behandlung, gilt sie als bestätigt; wirkt sie nicht, war der Zweifler schuld. Eine Aussage, die mit keinem denkbaren Ergebnis unvereinbar ist, sagt nichts Prüfbares über die Welt. Die anderen drei Fehler gibt es zwar, sie kommen in der Aussage aber nicht vor: Der Leiter verlangt keinen Gegenbeweis, beruft sich auf keine Einzelfälle und wählt keine Studien aus.","coreRule":"⚡ Wenn der Zweifler am Misserfolg schuld sein soll, ist die Behauptung nicht mehr prüfbar.","beleg":"Werkstück F.1.1 (Checkliste Punkt 2, mit Beispiel zur Energieheilung)","status":"entwurf","kurz":"Die Aussage lässt sich nie widerlegen: Wirkt die Behandlung, gilt sie als bestätigt, wirkt sie nicht, war der Zweifler schuld. Eine Behauptung, die mit keinem denkbaren Ergebnis unvereinbar ist, sagt nichts Prüfbares über die Welt.","prueffrage":"Welche Belege, Einzelfälle oder Studien führt der Leiter in seinem Satz überhaupt an?","rueckmeldung":[{"option":0,"text":"Die Umkehr der Beweislast ist ein bekannter Fehler und wirkt hier naheliegend. Der Leiter verlangt aber von niemandem einen Gegenbeweis, sondern erklärt im Nachhinein, warum ein Misserfolg nichts gegen seine Behauptung zeigt."},{"option":2,"text":"Einzelne Erfolgsgeschichten sind tatsächlich ein schwacher Beleg und bei Heilversprechen häufig. Im Satz des Leiters kommen aber weder Erfolgsgeschichten noch Studien vor, er beruft sich auf gar keine Fälle."},{"option":3,"text":"Das Herauspicken günstiger Studien ist ein echter Denkfehler und passt zu vielen Heilversprechen. Der Leiter nennt hier jedoch überhaupt keine Studien, weder günstige noch ungünstige. Sein Problem liegt in der Konstruktion des Satzes selbst."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"78c438c3ce185fe5"}},{"id":"qx-f-007","clusterId":"F","werkstueckRef":"F.1.1","stufe":3,"question":"Woran würdest du erkennen, dass aus dieser Hypothese eine Pseudowissenschaft geworden ist?","options":["Sie stützt sich auf Einzelberichte statt auf kontrollierte Experimente, sodass sie nie wirklich geprüft wurde.","Sie ist seit 20 Jahren unbestätigt, und eine Hypothese, die so lange keine Bestätigung findet, ist keine Wissenschaft mehr.","Sie ist nicht mehr testbar und bestätigt sich selbst, weil jedes denkbare Ergebnis zu ihren Gunsten ausgelegt wird.","Mehrere Experimente zu ihr sind gescheitert, und eine Hypothese, die sich nicht bewährt, ist damit pseudowissenschaftlich."],"correctIndex":2,"explanation":"Spekulative, seltsame oder lange unbestätigte Ideen können Wissenschaft bleiben, solange ein Test sie widerlegen könnte. Sie kippt, wenn sie sich der Prüfung entzieht: Wer Fehlschläge mit Ausreden auffängt und jedes Ergebnis als Bestätigung liest, hat aus der Hypothese ein Glaubenssystem gemacht, das nichts mehr widerlegen kann. Entscheidend ist die Prüfbarkeit selbst. Einzelberichte statt Experimente wären ein bekanntes Warnzeichen, doch die Forscherin hat experimentell geprüft. Dass niemand die Hypothese seit 20 Jahren bestätigen konnte, macht sie nicht pseudowissenschaftlich, solange ein Test sie widerlegen könnte. Gescheiterte Experimente gehören zur Wissenschaft, entscheidend ist, ob man sie als Widerlegung gelten lässt.","coreRule":"⚡ Nicht die Dauer oder die Seltsamkeit entscheidet, sondern ob die Idee noch scheitern darf.","beleg":"Werkstück F.1.1 (Der Kipppunkt)","status":"entwurf","scenario":"Eine Forscherin vertritt seit 20 Jahren eine ungewöhnliche Hypothese, die bisher niemand bestätigen konnte. In den vergangenen Jahren sind mehrere Experimente zur Hypothese gescheitert. Ihre Reaktion: Die Experimente seien nicht empfindlich genug gewesen, denn die Wirkung zeige sich nur, wenn niemand sie zu messen versucht. Jedes weitere Ergebnis deutet sie als Bestätigung.","kurz":"Pseudowissenschaftlich wird die Hypothese, weil kein denkbares Ergebnis sie mehr widerlegen könnte: Misserfolge werden mit Ausreden aufgefangen, jedes Ergebnis gilt als Bestätigung. Dass sie lange unbestätigt blieb oder Tests nicht bestand, reicht dafür nicht.","prueffrage":"Wie viele Experimente sind bisher gescheitert, und was folgerte die Forscherin jeweils daraus?","rueckmeldung":[{"option":0,"text":"Fehlende kontrollierte Experimente wären ein klares Warnzeichen. Hier wurde aber experimentell geprüft; das Problem liegt darin, wie die Forscherin mit den Ergebnissen umgeht."},{"option":1,"text":"Zwanzig Jahre ohne Bestätigung wecken Skepsis. Solange aber ein Test die Hypothese widerlegen könnte, bleibt sie Wissenschaft, auch wenn sie ungewöhnlich ist und lange unbestätigt blieb."},{"option":3,"text":"Dass sich eine Hypothese nicht bewährt, spricht gegen ihre Richtigkeit, nicht gegen ihre Wissenschaftlichkeit. Gescheiterte Experimente sind normal; entscheidend ist, ob man sie als Widerlegung gelten lässt."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 3.6, 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ba3d4c162687a4e4"}},{"id":"qx-f-008","clusterId":"F","werkstueckRef":"F.1.1","stufe":4,"question":"Wie solltest du auf dieses Seminarversprechen reagieren, wenn du seine Stichhaltigkeit prüfen willst?","options":["Du fragst, was „Quantenheilung“ und „biologische Schwingung“ genau bedeuten und wie man ihre Wirkung testen könnte. Bleibt die Antwort vage, ist der Anspruch nicht prüfbar.","Du prüfst bei den angeführten Studien, ob Stichprobengröße und Kontrollgruppe ausreichen. Zu kleine Stichproben ohne Vergleichsgruppe machen Ergebnisse unzuverlässig.","Du lässt dir die Qualifikation der Seminarleitung nachweisen. Ein anerkannter Abschluss ist ein Hinweis darauf, dass jemand in seinem Fach kompetent ist.","Du wägst den möglichen Nutzen und das Risiko des Seminars gegeneinander ab. Bei Heilversprechen kommt es auch darauf an, ob die Teilnahme einem Menschen schaden kann."],"correctIndex":0,"explanation":"Wissenschaftlich klingende Wörter beweisen nichts; entscheidend ist, ob eine Behauptung etwas Bestimmtes aussagt, das sich testen lässt. „Quantenheilung“ und „biologische Schwingung“ klingen nach Physik, ohne eine nachprüfbare Bedeutung zu haben, und der Verweis auf „Ganzheitlichkeit“ verlegt den Anspruch dorthin, wo ihn angeblich keine Prüfung erreicht. Die Rückfrage nach Bedeutung und Prüfbarkeit deckt genau das auf. Stichprobe und Kontrollgruppe sind sinnvolle Kriterien, setzen aber Studien voraus, und die werden hier gar nicht genannt. Eine Qualifikation sagt etwas über die Person, nicht darüber, ob die Behauptung überhaupt prüfbar ist. Die Abwägung von Nutzen und Risiko beantwortet eine andere Frage als die nach der Stichhaltigkeit.","coreRule":"⚡ Klingt eine Behauptung wissenschaftlich und beruft sich auf „Ganzheitlichkeit“, frag zuerst nach Bedeutung und Prüfbarkeit, bevor du Belege würdigst.","beleg":"Werkstück F.1.1 (Checkliste Punkte 8 und 9)","status":"entwurf","scenario":"Ein Seminar verspricht „Quantenheilung durch biologische Schwingung“. Auf Nachfrage heißt es, das sei „ganzheitlicher“, als es die „reduktionistische“ Wissenschaft je erfassen könne. Studien oder Messwerte werden nicht genannt.","kurz":"Wissenschaftlich klingende Wörter beweisen nichts; es zählt, ob die Behauptung etwas Bestimmtes aussagt, das sich testen lässt. Die Rückfrage nach Bedeutung und Prüfbarkeit zeigt, dass „Quantenheilung“ und „Ganzheitlichkeit“ genau dem Test ausweichen.","prueffrage":"Was genau soll bei Teilnehmenden nach dem Seminar anders sein als vorher?","rueckmeldung":[{"option":1,"text":"Stichprobengröße und Vergleichsgruppe sind gute Kriterien, wenn es Studien gibt. Das Seminar nennt aber keine, daher läuft die Prüfung ins Leere; zuerst muss klar sein, was überhaupt behauptet wird und testbar wäre."},{"option":2,"text":"Ein anerkannter Abschluss spricht meist für Fachkompetenz. Er sagt aber etwas über die Person und nicht darüber, ob die Behauptung eine prüfbare Bedeutung hat; dafür müsste man an der Aussage selbst ansetzen."},{"option":3,"text":"Nutzen und Risiko abzuwägen ist bei Heilversprechen sinnvoll, schon weil die Teilnahme schaden kann. Gefragt war aber, ob das Versprechen stichhaltig ist, und das beantwortet die Abwägung nicht."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"74c3762c39f827a6"}},{"id":"qx-f-009","clusterId":"F","werkstueckRef":"F.1.2","stufe":1,"question":"Ein Sportler trägt seit Jahren vor jedem Spiel seine Glückssocken, obwohl er weiß, dass sie nichts bewirken. Ein Kollege fragt ihn: „Warum machst du das dann?“ Welche Antwort ist die sinnvollste Erklärung für sein Verhalten?","options":["Das Ritual kann bestehen bleiben, weil er sich vor allem an Siege mit den Socken erinnert und Niederlagen übersieht, auch wenn die Socken nichts bewirken.","Das Ritual kann bestehen bleiben, weil es seine Anspannung dämpft und ihm ein Gefühl von Kontrolle gibt, auch wenn offen bleibt, ob er dadurch besser spielt.","Das Ritual kann bestehen bleiben, weil er nach den vielen Jahren nicht aufgeben will, was er hineingesteckt hat, auch wenn es ihm nichts bringt.","Das Ritual kann bestehen bleiben, weil er durch den Glauben an die Socken tatsächlich besser spielt, auch wenn er weiß, dass sie nichts bewirken."],"correctIndex":1,"explanation":"Wer sich einer Situation mit unsicherem Ausgang gegenübersieht, kann durch ein Ritual das Gefühl gewinnen, den Ausgang irgendwie zu beeinflussen. Dieses Gefühl von Kontrolle kann Angst dämpfen, auch wenn der Sportler rational weiß, dass die Socken nichts bewirken. Ein Feldexperiment mit religiösen Tempelritualen (Lang, Krátký und Xygalatas, 2020) deutet auf weniger berichtete Angst und weniger körperliche Anspannung nach einer Stressaufgabe hin (nach Angabe der Autoren erste, nicht laborgenau kontrollierte Belege); ob dasselbe für private Glücksrituale gilt, ist damit nicht gezeigt.","coreRule":"⚡ Ein Ritual kann beruhigen, ohne das Ergebnis zu beeinflussen: Trenne das Gefühl von Kontrolle von der tatsächlichen Wirkung.","beleg":"Werkstück F.1.2 (Kontext & Tiefe; Fn. gl-f-ritual-angst: Lang, Krátký, Xygalatas 2020, Abschn. 3 und 4)","status":"entwurf","scenario":"","kurz":"Das Ritual kann Anspannung dämpfen und das Gefühl geben, den unsicheren Ausgang irgendwie zu beeinflussen, auch wenn er weiß, dass die Socken nichts bewirken. Ob er dadurch besser spielt, bleibt offen.","prueffrage":"Was ließe sich beim Sportler vor einem Spiel mit und ohne Socken tatsächlich beobachten oder messen?","rueckmeldung":[{"option":0,"text":"Selektives Erinnern an Siege hält viele Aberglauben am Leben. Es setzt aber voraus, dass er die Siege den Socken zuschreibt, und genau das tut er nicht: Er weiß ja, dass sie nichts bewirken."},{"option":2,"text":"Wer schon viel investiert hat, hält oft an etwas fest. Hier ginge aber kaum etwas verloren, denn Socken anzuziehen kostet fast keinen Aufwand. Als Erklärung trägt das also nicht."},{"option":3,"text":"Der Glaube an eine Wirkung kann die Leistung tatsächlich beeinflussen. Dafür müsste er aber auf die Socken vertrauen, und er weiß, dass sie nichts bewirken. Ob solche Rituale die Leistung überhaupt verbessern, ist zudem nicht gesichert."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Lang, M.; Krátký, J.; Xygalatas, D. (2020): „The role of ritual behaviour in anxiety reduction“, Philosophical Transactions of the Royal Society B 375(1805)","oeffentlich":true,"doi":"10.1098/rstb.2019.0431","abruf":"2026-10-12"},{"typ":"doi","kurz":"Calin-Jageman, R. J.; Caldwell, T. L. (2014): „Replication of the Superstition and Performance Study by Damisch, Stoberock, and Mussweiler (2010)“, Social Psychology 45(3)","oeffentlich":false,"doi":"10.1027/1864-9335/a000190"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"aa5830c57cf41ae1"}},{"id":"qx-f-010","clusterId":"F","werkstueckRef":"F.1.2","stufe":2,"question":"Was ist an dieser Deutung das eigentliche Problem?","scenario":"Dein Kollege trägt zur Prüfung immer dieselbe Glückskette. Besteht er, sagt er: „Siehst du, sie wirkt.“ Fällt er durch, sagt er: „Ich habe sie zu spät angezogen.“","options":["Er stützt sich nur auf wenige Prüfungen mit der Kette; so kann der Zufall eine Wirkung vortäuschen, die es nicht gibt.","Er zählt nur die bestandenen Prüfungen und lässt die durchgefallenen weg; so gehen nur Erfolge in seine Bilanz ein.","Er verlässt sich auf Erzählungen anderer über Glücksketten statt auf eigene Prüfungen; so trägt bloßes Hörensagen sein Urteil.","Er wertet Bestehen als Beweis für die Kette und Durchfallen als eigenen Fehler; so kann kein Ergebnis die Kette widerlegen."],"correctIndex":3,"explanation":"Entscheidend ist die ungleiche Auswertung: Ein Treffer bestätigt das Ritual, ein Fehlschlag wird dem Anwender angelastet. Damit gibt es kein denkbares Ergebnis, das gegen die Kette sprechen würde, die Behauptung ist nicht widerlegbar und sagt deshalb auch nichts aus. Ob ein Ritual wirkt, ließe sich nur in einem kontrollierten Vergleich mit und ohne Ritual prüfen.","coreRule":"⚡ Wenn nur Erfolge dem Ritual zählen und Misserfolge dem Menschen, ist das Ritual immun gegen Widerlegung.","beleg":"Werkstück F.1.2 (Red Flags: asymmetrische Erklärung; Der Kipppunkt)","status":"entwurf","kurz":"Er deutet jedes Ergebnis zugunsten der Kette: Bestehen zeigt ihre Wirkung, Durchfallen liegt an ihm. So kann nichts gegen sie sprechen, und die Behauptung sagt nichts aus. Der naheliegende Fehler ist, einen Treffer schon als Beleg zu zählen.","prueffrage":"Was würde sich an seiner Deutung ändern, wenn er die Kette noch zwanzig weitere Prüfungen lang trägt?","rueckmeldung":[{"option":0,"text":"Wenige Prüfungen lassen dem Zufall tatsächlich viel Raum. Doch auch viele Durchgänge änderten nichts, solange jedes Ergebnis zugunsten der Kette gedeutet wird. Das Problem liegt in der Deutung, nicht in der Zahl."},{"option":1,"text":"Einseitiges Zählen wäre ein echter Fehler, hier passiert es aber nicht: Er lässt das Durchfallen nicht weg, sondern deutet es mit. Das Problem ist, wie er beide Ausgänge auslegt, nicht welche er mitzählt."},{"option":2,"text":"Hörensagen wäre eine schwache Grundlage, kommt hier aber nicht vor: Er beruft sich auf sein eigenes Erleben. Eigene Erfahrung ersetzt allerdings keinen Vergleich mit und ohne Kette, und sie schützt nicht vor einseitiger Deutung."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Skinner, B. F. (1948): „'Superstition' in the Pigeon“, Journal of Experimental Psychology 38 (Nachdruck Classics in the History of Psychology)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Skinner/Pigeon/","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"248f13cbfc410005"}},{"id":"qx-f-011","clusterId":"F","werkstueckRef":"F.1.2","stufe":3,"question":"Bei welcher Person ist die Grenze vom harmlosen Ritual zum echten Problem überschritten?","options":["Ein Händler nimmt von zwei gleich guten, gründlich geprüften Angeboten das mit seiner Glückszahl im Preis.","Eine Torfrau zieht vor jedem Spiel zuerst den linken Handschuh an, weil es sie beruhigt, und trainiert sonst wie geplant.","Eine Unternehmerin sagt eine gut vorbereitete Geschäftsentscheidung ab, weil ihr Tageshoroskop davon abrät.","Eine Familie verlegt ihren Ausflug vom Freitag, dem 13., auf den Samstag, obwohl beide Tage gleich gut passen."],"correctIndex":2,"explanation":"Ein Aberglaube ist dann ein Problem, wenn er echte, kostspielige Entscheidungen steuert, wenn er zwanghaft wird, wenn er wirksames Handeln ersetzt oder wenn er bei Misserfolg zu Selbstvorwürfen führt. Ein Horoskop, das darüber entscheidet, ob eine wichtige Geschäftsentscheidung fällt, hat mit dem Erfolg des Geschäfts nichts zu tun, kann aber viel Geld kosten. Die anderen drei Rituale sind klein und werden bewusst gehandhabt. Die Glückszahl entscheidet beim Händler nur zwischen zwei Angeboten, die er vorher gründlich geprüft hat und die gleich gut sind. Der Handschuh beruhigt die Torfrau und ersetzt keine Vorbereitung. Die Verlegung des Ausflugs kostet die Familie nichts, weil beide Tage gleich gut passen.","coreRule":"⚡ Harmlos ist das Ritual, das beruhigt; gefährlich wird es, wenn es Entscheidungen steuert.","beleg":"Werkstück F.1.2 (Der Kipppunkt, Punkt 1 bis 4)","status":"entwurf","scenario":"Vier Personen pflegen jeweils einen kleinen Aberglauben. Alle vier wissen, dass ihr Ritual keine nachweisbare Wirkung hat; es geht darum, was das Ritual im Alltag tatsächlich anrichtet.","kurz":"Entscheidend ist, was das Ritual kostet: Das Horoskop lässt eine gut vorbereitete Geschäftsentscheidung platzen, obwohl es mit dem Erfolg des Geschäfts nichts zu tun hat. Der naheliegende Fehler ist, jeden Aberglauben gleich zu bewerten, statt nach seinen Folgen zu fragen.","prueffrage":"Welche der vier Personen ändert wegen ihres Rituals überhaupt etwas an einer Entscheidung?","rueckmeldung":[{"option":0,"text":"Eine Zahl im Preis als Entscheidungsgrund wirkt albern. Hier zählt aber, dass der Händler beide Angebote vorher gründlich geprüft hat und sie gleich gut sind. Der Aberglaube entscheidet nur bei Gleichstand und kostet nichts."},{"option":1,"text":"Ein Ritual vor jedem Spiel erinnert leicht an Zwang. Der Handschuh beruhigt die Torfrau jedoch bloß; sie trainiert weiter wie geplant, nichts Wirksames wird verdrängt, und sie gewinnt oder verliert nicht wegen des Handschuhs."},{"option":3,"text":"Ein Datum zu meiden, obwohl es keine Wirkung hat, klingt nach echtem Aberglauben. Ein Problem entsteht dadurch nicht: Beide Tage passen gleich gut, die Familie verliert also weder Geld noch Chancen und ersetzt auch nichts Sinnvolles."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Lang, M.; Krátký, J.; Xygalatas, D. (2020): „The role of ritual behaviour in anxiety reduction“, Philosophical Transactions of the Royal Society B 375(1805)","oeffentlich":true,"doi":"10.1098/rstb.2019.0431","abruf":"2026-10-12"},{"typ":"doi","kurz":"Carlson, S. (1985): „A double-blind test of astrology“, Nature 318","oeffentlich":false,"doi":"10.1038/318419a0"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"4c078b1dd30514bc"}},{"id":"qx-f-012","clusterId":"F","werkstueckRef":"F.1.2","stufe":4,"question":"Eine Freundin zündet eine Kerze an, um „Reichtum anzuziehen“, und bekommt drei Wochen später eine Gehaltserhöhung. Sie sagt: „Siehst du, es hat funktioniert!“ Warum ist das noch kein Beleg dafür, dass die Kerze gewirkt hat?","options":["Dass die Erhöhung nach der Kerze kam, zeigt nicht, dass sie deswegen kam; erst ein Vergleich mit und ohne Kerze würde eine Wirkung zeigen.","Ursache und Wirkung sind vertauscht: Weil eine Gehaltserhöhung schon in Aussicht war, hat die Freundin die Kerze angezündet.","Sie erinnert sich nur an Kerzen, auf die eine Gehaltserhöhung folgte, und vergisst alle übrigen Rituale; so entsteht ein Überlebensfehler.","Sie überschätzt, wie häufig Gehaltserhöhungen sind, weil ihr die eigene Erhöhung lebhafter vor Augen steht als die vielen Wochen ohne."],"correctIndex":0,"explanation":"Die Kerze steht vor der Gehaltserhöhung, aber zeitliche Abfolge ist keine Ursache. Das ist der Fehlschluss „danach, also deswegen“. Es gibt keine plausible Verbindung zwischen einer brennenden Kerze und dem Gehalt, und ein einzelner Treffer ist mit Zufall bestens erklärbar: Gehaltserhöhungen kommen auch ohne Kerzen vor. Erst ein Vergleich würde zeigen, ob Menschen mit Kerze häufiger eine Erhöhung bekommen als Menschen ohne. Eine Umkehrung von Ursache und Wirkung klingt nach einer üblichen Fehlerquelle, scheitert aber daran, dass die Kerze drei Wochen vor der Erhöhung brannte und von einer erwarteten Erhöhung nichts erzählt wird. Das Vergessen anderer Rituale wäre ein bekannter Denkfehler, doch es geht um einen einzelnen Fall, nicht um eine Auswahl aus vielen. Eine Überschätzung der Häufigkeit wirkt naheliegend, aber die Freundin schätzt keine Häufigkeit; entscheidend ist, ob die Kerze überhaupt etwas dazu beiträgt.","coreRule":"⚡ Wer von „danach“ auf „deswegen“ schließt, braucht einen Vergleich mit und ohne die vermutete Ursache; die bloße Reihenfolge reicht nie.","beleg":"Werkstück F.1.2 (Kontext & Tiefe: Post hoc; Anwendung & Relevanz: In der Esoterik & New Age)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Dass die Erhöhung nach der Kerze kam, heißt nicht, dass sie deswegen kam. Gehaltserhöhungen gibt es auch ohne Kerzen; erst ein Vergleich von Menschen mit und ohne Kerze könnte eine Wirkung zeigen.","prueffrage":"Was ist in den drei Wochen zwischen Kerze und Gehaltserhöhung sonst noch geschehen, etwa bei ihrer Arbeit oder im Betrieb?","rueckmeldung":[{"option":1,"text":"Eine Umkehrung von Ursache und Wirkung gibt es tatsächlich. Hier gibt der Fall dafür aber nichts her: Von einer erwarteten Erhöhung ist nirgends die Rede, und die Kerze brannte drei Wochen davor."},{"option":2,"text":"Selektives Erinnern ist ein echter Fehler, setzt aber viele Rituale voraus, von denen nur die erfolgreichen im Gedächtnis bleiben. Hier geht es um einen einzelnen Fall, nicht um eine Auswahl aus vielen."},{"option":3,"text":"Eine Häufigkeit schätzt die Freundin gar nicht ein. Sie führt die Erhöhung auf die Kerze zurück. Die offene Frage ist deshalb, ob die Kerze etwas beiträgt, nicht, wie oft Erhöhungen vorkommen."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Eintrag „Post Hoc“","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2bcfb13a0d0e83b1"}},{"id":"qx-f-013","clusterId":"F","werkstueckRef":"F.1.3","stufe":1,"question":"Ein Online-Beitrag behauptet: „Eine geheime Elite steuert seit Jahrzehnten die Weltpolitik, ohne dass je ein Mitwisser geplaudert hat. Dass sie ständig verräterische Symbole in Filmen und Logos versteckt, beweist: Sie ist so sicher, dass sie sich nicht verstecken muss.“ Welcher Widerspruch macht diese Erzählung unglaubwürdig?","options":["Dieselbe Gruppe soll so umsichtig sein, dass sie ein Geheimnis jahrzehntelang perfekt wahrt, und so nachlässig, dass jeder Hobbydetektiv ihre Spuren findet.","Dieselbe Gruppe soll im Verborgenen sehr klein sein und zugleich in ihrer Wirkung weltumspannend, obwohl kleine Gruppen immer nur lokal wirken können.","Dieselbe Gruppe soll böswillig handeln und trotzdem von ihren Opfern ausdrücklich gelobt werden, weil sie deren Interessen vertritt.","Dieselbe Gruppe soll allmächtig sein und wird dennoch von den Verfassern der Erzählung nicht ernsthaft bekämpft, sondern nur beschrieben."],"correctIndex":0,"explanation":"Die Erzählung braucht einen Feind, der zwei Dinge zugleich sein muss: übermenschlich kompetent (er hält eine globale Verschwörung jahrzehntelang geheim) und unfassbar dumm (er hinterlässt „Hinweise“, die jeder YouTube-Detektiv finden kann). Beides gleichzeitig ist kaum plausibel. Wenn eine Erklärung nur funktioniert, indem sie ihrem Feind widersprüchliche Eigenschaften zuschreibt, ist das ein Warnsignal.","coreRule":"⚡ Allmächtig und doch schlampig: Wenn der Feind beides zugleich sein muss, trägt die Erzählung nicht.","beleg":"Werkstück F.1.3 (Kontext & Tiefe, Anatomie, Punkt 1: Ein allmächtiger, böswilliger Feind)","status":"entwurf","scenario":"","kurz":"Die Gruppe soll zugleich so perfekt sein, dass nie jemand plaudert, und so nachlässig, dass jeder ihre Symbole findet. Wenn ein Feind widersprüchliche Eigenschaften braucht, damit die Erzählung aufgeht, ist das ein Warnsignal.","prueffrage":"Wie erklärt der Beitrag, dass die angeblichen Symbole offen in Filmen und Logos zu sehen sind?","rueckmeldung":[{"option":1,"text":"Dass die Gruppe klein, aber weltumspannend wirken soll, hat man oft bei solchen Erzählungen im Ohr. Der Beitrag sagt über ihre Größe aber nichts, und kleine Gruppen können durchaus weit wirken. Der Widerspruch liegt woanders."},{"option":2,"text":"Ein Widerspruch zwischen Absicht und Wirkung klingt plausibel, doch von einem Lob durch die Opfer ist im Beitrag keine Rede. Die Unstimmigkeit steckt in den Eigenschaften, die der Gruppe selbst zugeschrieben werden."},{"option":3,"text":"Was die Verfasser selbst tun, sagt etwas über sie, aber nichts über die innere Stimmigkeit ihrer Behauptung. Der Widerspruch steckt in dem, was der Beitrag der Gruppe zuschreibt, nicht darin, wie die Verfasser auf sie reagieren."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2016): „On the Viability of Conspiratorial Beliefs“, PLOS ONE 11(1), e0147905","oeffentlich":true,"doi":"10.1371/journal.pone.0147905","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR, „Contradictory“","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9543a874e86a7240"}},{"id":"qx-f-014","clusterId":"F","werkstueckRef":"F.1.3","stufe":2,"question":"Wie erklärst du am besten, dass dir die Saboteur-Geschichte verführerischer vorkommt, obwohl sie kaum belegt ist?","scenario":"In deinem Haus zeigen sich Risse in der Wand, und die Tür klemmt. Ein Gutachter nennt instabilen Baugrund: ein komplexes, teures Problem, das ein aufwendiges Stabilisieren des Fundaments verlangt. Dein Nachbar flüstert dagegen, eine geheime Immobilien-Lobby wolle das Viertel billig aufkaufen und schlage nachts mit dem Hammer gegen dein Fundament. Der klemmende Türrahmen sei der Beweis.","options":["Sie wurde als Erste genannt und setzt damit einen Anker; alle weiteren Erklärungen werden an ihr gemessen, obwohl sie nicht mehr Belege liefert.","Sie ist einfach und dramatisch und bietet einen Feind, gegen den man kämpfen kann; sie erfüllt das Bedürfnis nach Sinn und Kontrolle, ohne mehr Belege zu liefern.","Sie wird von vielen Menschen geteilt, und die Zustimmung der Gruppe wirkt wie ein Beleg (sozialer Beweis); man schließt sich der Mehrheit an, ohne selbst zu prüfen.","Sie stammt von einem Nachbarn, den du magst, und die Sympathie für den Überbringer färbt deine Bewertung der Aussage selbst, obwohl sie kaum Belege hat."],"correctIndex":1,"explanation":"Wie verführerisch eine Erklärung wirkt, sagt nichts darüber, wie gut sie belegt ist. Die Saboteur-Geschichte bietet einen klaren Bösewicht, einen einfachen Plan und das Gefühl, Bescheid zu wissen und handeln zu können. Die Erklärung des Gutachters ist dagegen kompliziert, beängstigend und teuer, obwohl sie die Risse und die klemmende Tür ebenfalls erklärt. Dass eine Geschichte emotional befriedigt, ist kein Beleg für ihre Wahrheit. Die Forschung zu Verschwörungsglauben zeigt außerdem: Er wird von Bedürfnissen nach Sinn, Kontrolle und Zugehörigkeit getrieben, erfüllt sie aber meist nicht. Ein Ankereffekt scheidet aus, weil der Gutachter seine Erklärung zuerst nannte. Sozialer Beweis setzt voraus, dass viele die Geschichte teilen, hier flüstert aber nur ein Nachbar. Ob du den Nachbarn magst, steht nirgends und erklärt nicht, warum gerade diese Geschichte so anziehend wirkt.","coreRule":"⚡ Eine Erklärung kann sich gut anfühlen und trotzdem schlecht belegt sein: Prüfe Belege, nicht den Gefühlswert.","beleg":"Werkstück F.1.3 (Das rissige Fundament; Kernidee; Anatomie, Punkt 2: Apophenie)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wie anziehend eine Erklärung wirkt, sagt nichts über ihre Belege. Die Saboteur-Geschichte liefert einen Feind, einen einfachen Plan und das Gefühl, handeln zu können. Der Denkfehler: Befriedigung wird mit Wahrheit verwechselt.","prueffrage":"Was bietet die Geschichte des Nachbarn dem Hausbesitzer, das ihm das Gutachten nicht bietet?","rueckmeldung":[{"option":0,"text":"Wer zuerst etwas sagt, prägt oft die Maßstäbe. Hier war es aber umgekehrt: Der Gutachter nannte seine Erklärung zuerst, der Nachbar kam danach. Ein Anker kann die Anziehungskraft der Saboteur-Geschichte also nicht erklären."},{"option":2,"text":"Zustimmung der Mehrheit kann tatsächlich wie ein Beleg wirken. Dafür müssten aber viele die Geschichte teilen, und im Szenario flüstert nur ein einzelner Nachbar. Der Mechanismus ist real, passt hier aber nicht zur Lage."},{"option":3,"text":"Sympathie für den Überbringer kann die Bewertung einer Aussage durchaus färben. Im Szenario steht aber nirgends, dass du den Nachbarn magst. Und selbst dann bliebe offen, warum gerade diese Geschichte so anziehend wirkt."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f9c1bb8376186b8a"}},{"id":"qx-f-015","clusterId":"F","werkstueckRef":"F.1.3","stufe":3,"question":"Wie ordnest du seine Aussage am besten ein?","options":["Sein Satz zeigt, dass der Glaube ihm Kontrolle gibt; die Experimente prüften nur kurzes Lesen und sagen über Monate des Glaubens deshalb nichts aus.","Sein Satz zeigt, dass Kontrolle sein Motiv war; und weil ein Glaube ohne erfülltes Motiv aufgegeben würde, erfüllt er es nach Monaten offenbar auch.","Sein Satz zeigt, warum er glaubt, nicht dass er Kontrolle hat; die Experimente, in denen Lesen das Kontrollgefühl senkte, sprechen eher dagegen.","Sein Satz zeigt nur ein Gefühl, und Gefühle von Kontrolle lassen sich nicht messen; die Experimente können über seine Lage deshalb gar nichts aussagen."],"correctIndex":2,"explanation":"Hier sind zwei Fragen zu trennen: Warum glaubt jemand? Und: Bekommt er, was er sich davon verspricht? Die Forschung (Douglas, Sutton und Cichocka 2017) führt Verschwörungsglauben auf epistemische, existenzielle und soziale Motive zurück, etwa das Bedürfnis nach Sinn, Kontrolle und Zugehörigkeit. Der Satz deines Freundes passt genau zu diesem Motiv. Einen Beleg, dass der Glaube das Bedürfnis auch erfüllt, gibt es aber nicht; in Experimenten schwächte schon das Lesen von Verschwörungserzählungen das Gefühl von Kontrolle. Sein Gefühl ist real, belegt aber nicht, dass die Erzählung ihm tatsächlich Kontrolle verschafft: „Es fühlt sich nach Kontrolle an“ ist etwas anderes als „Ich habe Kontrolle“. Seine eigene Auskunft wirkt wie ein Beweis, gibt aber nur das Versprechen wieder, nicht den Befund. Dass er nach Monaten noch glaubt, zeigt, dass das Motiv wirkt, nicht dass es erfüllt wird. Und das Kontrollgefühl ist durchaus messbar, genau das haben die Experimente getan.","coreRule":"⚡ Wer fragt, ob ein Glaube ein Bedürfnis erfüllt, darf das Versprechen nicht mit dem Befund verwechseln: Verschwörungsglaube verspricht Halt, löst ihn aber meist nicht ein.","beleg":"Werkstück F.1.3 (Das Adaptive Talent); Fn. gl-f-douglas (Douglas, Sutton, Cichocka 2017, S. 538 f.)","status":"entwurf","scenario":"Ein Freund beschäftigt sich seit Monaten mit einer Verschwörungserzählung. Er sagt: „Seit ich die Verschwörung durchschaue, habe ich endlich Kontrolle in einer chaotischen Welt.“ Dir fallen zwei Dinge ein. Die Forschung erklärt solchen Glauben mit Bedürfnissen nach Sinn, Kontrolle und Zugehörigkeit. Und in Experimenten fühlten sich Versuchspersonen, die eine Verschwörungserzählung gelesen hatten, danach weniger in Kontrolle als andere.","kurz":"Sein Satz erklärt, warum er glaubt: Das Motiv Kontrolle passt dazu. Dass er sie auch bekommt, folgt daraus nicht, und Experimente, in denen schon Lesen das Kontrollgefühl senkte, sprechen eher dagegen. Ein Versprechen ist noch kein Befund.","prueffrage":"Was würde sich bei ihm im Alltag konkret ändern, wenn er wirklich mehr Kontrolle hätte?","rueckmeldung":[{"option":0,"text":"Dass die Experimente nur kurzes Lesen prüften, ist ein berechtigter Vorbehalt. Trotzdem ist ihr Befund ein Hinweis, den man nicht beiseiteschiebt, und sein Satz zeigt nur das Motiv und das Gefühl, nicht dass der Glaube Kontrolle verschafft."},{"option":1,"text":"Sein Satz passt tatsächlich zum Motiv Kontrolle. Die Annahme, ein Glaube ohne Erfüllung werde aufgegeben, ist aber unbelegt: Auch ein unerfülltes Motiv kann den Glauben über Monate tragen. Dass er noch glaubt, zeigt nur, dass das Motiv wirkt."},{"option":3,"text":"Ein Gefühl von Kontrolle ist etwas anderes als tatsächliche Kontrolle, das stimmt. Messbar ist es aber durchaus, genau das taten die Experimente. Sie beweisen nichts über seinen Fall, sind als Hinweis aber nicht wertlos."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"78b94425fe0891f2"}},{"id":"qx-f-016","clusterId":"F","werkstueckRef":"F.1.3","stufe":4,"question":"Welcher der beiden Beiträge gibt mehr Grund zur Sorge, und warum?","scenario":"Zwei Beiträge kursieren im Netz. Der erste scherzt, die Stadt Bielefeld existiere gar nicht und sei eine Erfindung. Der zweite behauptet, eine bestimmte Bevölkerungsgruppe steuere insgeheim die Wirtschaft und sei an Krisen schuld. Beide Beiträge bekommen viele Likes. Eine Freundin sagt: „Sind doch beides Verschwörungsgeschichten, also gleich harmlos oder gleich schlimm.“","options":["Beide Beiträge sind gleich ernst, weil beide ohne Beleg eine geheime Lenkung behaupten und damit Misstrauen säen können.","Der erste Beitrag ist ernster, weil er mit Bielefeld eine leicht überprüfbare Tatsache bestreitet und damit Wirklichkeit leugnen kann.","Der zweite Beitrag ist ernster, weil er mehr Zustimmung bekommt und damit eine größere Reichweite hat als der Bielefeld-Scherz.","Der zweite Beitrag ist ernster, weil er reale Menschen zum Feind erklärt und damit Ausgrenzung und Gewalt den Boden bereiten kann."],"correctIndex":3,"explanation":"Beide Beiträge haben die Form einer Verschwörungserzählung: ein verborgener Plan, bei dem Zufall keine Rolle spielt. Den entscheidenden Unterschied macht das Ziel. Ein Scherz über eine Stadt, die es angeblich nicht gibt, bleibt ein Gedankenspiel, das niemandem schadet. Wird dagegen eine reale Gruppe von Menschen zum geheimen Drahtzieher erklärt, entsteht ein Feindbild, und aus Feindbildern können Ausgrenzung, Hass und im schlimmsten Fall Gewalt entstehen. Historisch zeigt das der Vorwurf der Brunnenvergiftung, mit dem 1348 beim Herannahen der Pest jüdische Gemeinden ermordet wurden, oder die gefälschten „Protokolle der Weisen von Zion“, die dem modernen Antisemitismus als angeblicher Beweis dienten.","coreRule":"⚡ Gefährlich wird ein Mythos dort, wo er reale Menschen zum Feind erklärt.","beleg":"Werkstück F.1.3 (Der Kipppunkt; Anwendung & Relevanz: Historische Verschwörungsmythen)","status":"entwurf","kurz":"Entscheidend ist, wer als Drahtzieher benannt wird: Ein Scherz über eine erfundene Stadt bleibt ein Spiel, eine reale Gruppe als Feind schafft ein Feindbild, aus dem Ausgrenzung und Gewalt entstehen können. Dass beide ohne Beleg auftreten, trennt sie nicht.","prueffrage":"Worin unterscheiden sich die beiden Beiträge bei den Likes, und worin bei dem, was sie behaupten?","rueckmeldung":[{"option":0,"text":"Die gemeinsame Form leuchtet ein: Beide behaupten ohne Beleg einen verborgenen Plan. Das haben sie aber nur gemeinsam, es trennt sie nicht. Der Bielefeld-Scherz bleibt ein Gedankenspiel, der zweite Beitrag richtet sich gegen reale Menschen."},{"option":1,"text":"Bielefeld gibt es tatsächlich, und das lässt sich leicht prüfen. Der Beitrag scherzt aber erkennbar und leugnet nichts im Ernst. Gewichtiger ist der Beitrag, der reale Menschen zum geheimen Drahtzieher erklärt."},{"option":2,"text":"Reichweite wäre ein Grund zur Sorge, doch laut Szenario bekommen beide Beiträge viele Likes. Zustimmung unterscheidet die Fälle also nicht; den Unterschied macht, wer als Feind benannt wird."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"United States Holocaust Memorial Museum, Holocaust Encyclopedia: „Protocols of the Elders of Zion“","oeffentlich":true,"url":"https://encyclopedia.ushmm.org/content/en/article/protocols-of-the-elders-of-zion","abruf":"2026-10-12"},{"typ":"url","kurz":"Cohn, S. K. (2007): „The Black Death and the Burning of Jews“, Past and Present 196 (Einleitung bei Medievalists.net)","oeffentlich":true,"url":"https://www.medievalists.net/2011/01/the-black-death-and-the-burning-of-jews/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"3fdee6975387d78f"}},{"id":"qx-f-017","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":1,"question":"Was ist hier der sinnvollste erste Schritt?","options":["Zuerst die Einzelheiten prüfen: Das Video nennt viele Daten und Namen, und erst wenn jede davon bestätigt ist, lässt sich die Erzählung beurteilen.","Zuerst die Verbreitung prüfen: Das Video hat über zwei Millionen Aufrufe, und so viele Zuschauer hätten grobe Fehler längst bemerkt und gemeldet.","Zuerst die offenen Fragen prüfen: Der amtliche Bericht lässt zwei Punkte ungeklärt, und jede solche Lücke stützt die Erzählung des Videos.","Zuerst die Bauweise prüfen: Das Video wertet fehlende Beweise als Beweis, verlangt von dir den Gegenbeweis und erklärt Einwände zur Vertuschung."],"correctIndex":3,"explanation":"Ob eine Erzählung trägt, zeigt sich oft schon an ihrer Bauweise, noch bevor du ein einziges Detail geprüft hast. Das Video zeigt mehrere Alarmzeichen: Das Fehlen von Beweisen wird selbst als Beweis gewertet (Argument aus Unwissenheit), die Beweislast wird dir zugeschoben, und die Erzählung ist unfalsifizierbar, weil jeder Gegenbeweis zur Vertuschung erklärt wird. Eine Behauptung, die durch nichts widerlegt werden kann, ist keine robuste Hypothese, sondern eine uneinnehmbare Festung. Deshalb ist es klüger, zuerst die Struktur zu prüfen, statt endlos die „Fakten“ zu recherchieren, zumal du die Einzelheiten hier gar nicht überprüfen kannst. Alle Einzelheiten nachzuprüfen klingt gründlich, ist hier aber nicht möglich und änderte nichts daran, dass das Video jeden Gegenbeleg umdeutet. Zwei Millionen Aufrufe zeigen Beliebtheit, keine Prüfung. Und zwei offene Punkte im amtlichen Bericht machen die alternative Erzählung nicht wahrscheinlicher; Lücken der einen Darstellung sind kein Beleg für die andere.","coreRule":"⚡ Erst die Struktur prüfen, dann die Details: Wird fehlender Beweis als Beweis gewertet, die Beweislast umgekehrt und jeder Gegenbeweis eingemeindet, ist Vorsicht angebracht.","beleg":"Werkstück F.1.3.1 (Kernidee; Die 7 Warnsignale, Nr. 2–4; Werkbank-Frage)","status":"entwurf","scenario":"Eine Freundin schickt dir ein Video über ein Unglück. Es erklärt das Ereignis zum Werk einer kleinen, mächtigen Gruppe, nennt viele Daten und Namen und hat über zwei Millionen Aufrufe; der amtliche Untersuchungsbericht lässt zwei Punkte ungeklärt. Am Ende heißt es: „Dass keine Beweise auftauchen, zeigt nur, wie perfekt sie alles vertuschen. Beweise du mir erst mal, dass es nicht stimmt.“ Jeden Einwand erklärt das Video vorab zum Teil der Vertuschung. Du kannst die Einzelheiten selbst nicht überprüfen.","kurz":"Schon die Bauweise verrät viel: Das Video wertet fehlende Beweise als Beweis, schiebt dir die Beweislast zu und erklärt jeden Einwand zur Vertuschung, sodass nichts es widerlegen kann. Das erkennst du, ohne ein Detail zu prüfen.","prueffrage":"Welcher Beleg oder Einwand wäre denkbar, den das Video nicht zum Teil der Vertuschung erklären würde?","rueckmeldung":[{"option":0,"text":"Gründliches Nachprüfen wirkt seriös. Du kannst die Einzelheiten hier aber gar nicht prüfen, und selbst bestätigte Daten änderten nichts daran, dass das Video jeden Gegenbeleg umdeutet."},{"option":1,"text":"Viele Aufrufe wirken wie eine große Kontrolle durch viele Augen. Sie zeigen aber nur, wie viele das Video angeklickt haben, nicht, ob jemand es geprüft hat. Beliebtheit ist kein Wahrheitsbeleg."},{"option":2,"text":"Offene Punkte im amtlichen Bericht sind berechtigt und darf man ansprechen. Eine Lücke in der einen Darstellung belegt aber nicht die andere: Dass etwas ungeklärt ist, macht die Erzählung des Videos nicht wahrscheinlicher."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c882523a5c86ae24"}},{"id":"qx-f-018","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":2,"question":"In einem Online-Video heißt es: „Wer das noch nicht durchschaut hat, schläft noch. Du gehörst zu den wenigen, die endlich aufgewacht sind und hinter die Kulissen blicken.“ Welche Wirkung hat diese Rahmung auf das Denken des Publikums?","options":["Sie schmeichelt den Zuschauern mit einem Überlegenheitsgefühl; wer sich zu den „Wissenden“ zählt, ist für die Erzählung eingenommen.","Sie legt den Zuschauern die Beweislast auf; wer die Behauptung nicht widerlegen kann, soll sie vorläufig als wahr hinnehmen.","Sie erweckt den Eindruck, die meisten Menschen teilten diese Sicht; wer sich einer Mehrheit anschließen kann, prüft weniger genau.","Sie versetzt die Zuschauer in Angst und Wut über eine Bedrohung; wer sich bedroht fühlt, hinterfragt die Behauptungen nicht mehr."],"correctIndex":0,"explanation":"Die Einteilung in „Erwachte“ und „Schlafschafe“ befriedigt das Bedürfnis nach Überlegenheit: Wer sich zu den Wissenden zählt, fühlt sich den anderen überlegen und wird für die Erzählung eingenommen. Beweislastumkehr, Mitläufereffekt und Gefühlsappell kommen in Verschwörungserzählungen häufig vor, passen aber nicht zu diesem Satz. Er verlangt keinen Gegenbeweis und droht mit nichts. Er nennt „die wenigen“ und beruft sich damit gerade nicht auf eine Mehrheit, sondern schmeichelt dem Selbstbild des Publikums.","coreRule":"⚡ Wo die Welt in Erwachte und Schlafende zerfällt, wirkt das Überlegenheitsgefühl als Bindemittel und ersetzt die Prüfung durch Zugehörigkeit.","beleg":"Werkstück F.1.3.1 (Die 7 Warnsignale, Punkt 7)","status":"entwurf","scenario":"","kurz":"Die Einteilung in „Erwachte“ und „Schlafende“ schmeichelt: Wer sich zu den Wenigen zählt, die hinter die Kulissen blicken, fühlt sich überlegen und ist für die Erzählung eingenommen. Gegenbeweis oder Drohung verlangt der Satz dabei gar nicht.","prueffrage":"Wen teilt der Satz in welche zwei Gruppen ein, und zu welcher soll sich das Publikum zählen?","rueckmeldung":[{"option":1,"text":"Beweislastumkehr tritt in Verschwörungserzählungen oft auf. Hier verlangt der Satz aber gar keinen Gegenbeweis; er benennt keine Behauptung, die man widerlegen müsste, sondern teilt das Publikum in Wissende und Schlafende ein."},{"option":2,"text":"Dass die Zustimmung einer Mehrheit weniger genau prüfen lässt, stimmt als Mechanismus. Der Satz beruft sich aber auf „die wenigen“, die aufgewacht sind, also gerade nicht auf eine Mehrheit, sondern auf eine Auswahl, zu der man sich zählen darf."},{"option":3,"text":"Angst und Wut sind in Verschwörungserzählungen ein häufiges Mittel. In diesem Satz fehlt aber jede Bedrohung; er benennt keine Gefahr, sondern wertet das Selbstbild der Zuschauer auf."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR, „Persecuted victim“","abruf":"2026-10-12"},{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"65dc59eb9e4304d2"}},{"id":"qx-f-019","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":3,"question":"Wie beurteilst du die beiden Fälle?","options":["Beide zeigen den Kipppunkt: Anna wie Ben misstrauen demselben Amt, und schon dieses Misstrauen gegenüber einer Behörde ist das eigentliche Warnsignal.","Nur Ben zeigt den Kipppunkt: Annas Misstrauen ließ sich durch die Rohdaten korrigieren, Bens deutet jeden Beleg um und kostet ihn schon Beziehungen.","Keiner zeigt den Kipppunkt: Beide hatten wegen der falschen Fallzahlen im Vorjahr einen guten Anlass, und ein berechtigter Anlass schließt das Muster aus.","Nur Ben zeigt den Kipppunkt: Er zweifelt nach den alten auch an den neuen Zahlen, und wer einer Behörde wiederholt misstraut, hat die Grenze schon überschritten."],"correctIndex":1,"explanation":"Entscheidend ist nicht, ob jemand misstraut, sondern was aus dem Misstrauen wird. Gesundes Misstrauen gegenüber Autoritäten ist nützlich: Anna hatte nach den falschen Zahlen des Vorjahres Grund zur Skepsis, prüfte nach und ließ sich von den Rohdaten korrigieren. Der Kipppunkt ist erreicht, wenn Misstrauen zu einem geschlossenen Weltbild wird, das keinen Gegenbeweis mehr zulässt: Jeder Widerspruch gilt dann als Teil der Verschwörung, wie bei Ben. Ein zweites Kriterium kommt hinzu: wenn der Glaube an die Verschwörung wichtiger wird als persönliche Beziehungen und die eigene Sicherheit; auch das trifft auf Ben zu, der den Kontakt zu seiner Schwester abgebrochen hat. Die Ansicht, Misstrauen sei an sich verdächtig, verwechselt das Merkmal mit dem Muster und würde auch Annas berechtigte Prüfung verurteilen. Ein guter Anlass am Anfang schützt nicht davor, später zu kippen, wie Bens Fall zeigt. Und wiederholter Zweifel ist kein Kriterium, denn auch Anna zweifelte an den neuen Zahlen und blieb dabei offen für Belege.","coreRule":"⚡ Misstrauen darf prüfen; es darf nur nicht jeden Gegenbeweis ausschließen.","beleg":"Werkstück F.1.3.1 (Der Kipppunkt)","status":"entwurf","scenario":"Zwei Bekannte misstrauen dem Gesundheitsamt, seit es im Vorjahr falsche Fallzahlen genannt hatte. Anna zweifelt auch die neuen Zahlen an, prüft sie aber anhand der veröffentlichten Rohdaten nach und ändert ihre Meinung, als diese die Zahlen bestätigen. Ben erklärt dieselben Rohdaten für gefälscht, deutet jeden weiteren Beleg als Teil der Vertuschung und hat deswegen den Kontakt zu seiner Schwester abgebrochen. Ein Freund meint: „Beide stecken schon halb im Kaninchenbau, Misstrauen gegenüber Behörden ist an sich verdächtig.“","kurz":"Entscheidend ist, was aus dem Misstrauen wird: Anna prüfte nach und ließ sich korrigieren. Bei Ben gilt jeder Beleg als Vertuschung, und er hat den Kontakt zur Schwester abgebrochen. Misstrauen allein ist kein Kipppunkt.","prueffrage":"Was geschieht mit dem jeweiligen Misstrauen, wenn die Rohdaten die Zahlen bestätigen?","rueckmeldung":[{"option":0,"text":"Beide misstrauen demselben Amt, daher liegt der Vergleich nahe. Misstrauen allein ist aber kein Warnsignal, denn nach den falschen Zahlen war Skepsis berechtigt, und Anna zeigt, dass sie sich korrigieren lässt. Das Muster liegt im Umgang mit Belegen."},{"option":2,"text":"Ein guter Anlass ist hier tatsächlich gegeben, und der Zweifel am Anfang war berechtigt. Er schützt aber nicht davor, später zu kippen: Ben lässt keinen Gegenbeweis mehr gelten und hat den Kontakt zur Schwester abgebrochen."},{"option":3,"text":"Dass nur Ben kippt, stimmt, und er zweifelt auch an den neuen Zahlen. Wiederholter Zweifel ist aber kein Kriterium: Auch Anna zweifelte an den neuen Zahlen und blieb offen für Belege. Entscheidend ist, ob Gegenbelege noch etwas ändern können."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Kasten „Conventional vs. Conspiratorial Thinking“; Abschnitt CONSPIR","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"f96e925b26bc1b14"}},{"id":"qx-f-020","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":4,"question":"Welche Antwort wird der Lage am besten gerecht?","scenario":"Ein Bekannter erzählt dir, seine Schwägerin sei „komplett paranoid“, nur weil sie eine bekannte Online-Verschwörungserzählung glaubt. Du hast die Erzählung mit einer Liste typischer Warnsignale geprüft (allmächtiger Feind, Beweislastumkehr, Unfalsifizierbarkeit und weitere) und festgestellt, dass sie mehrere davon erfüllt.","options":["Die Erzählung erfüllt mehrere Warnsignale, aber das ist ein Befund über die Erzählung und ihren Denkstil, nicht über den seelischen Gesundheitszustand der Schwägerin.","Die Warnsignale zeigen nur, dass die Erzählung schlecht prüfbar gebaut ist; ob sie stimmt, entscheidet sich erst, wenn man ihre einzelnen Behauptungen an Quellen überprüft.","Die Warnsignale zeigen, dass die Schwägerin die Erzählung nicht kritisch geprüft hat, denn wer mehrere Warnsignale übersieht, hat sich mit der Erzählung kaum befasst.","Die Herkunft einer Erzählung gehört ebenfalls zu den Prüfpunkten; deshalb solltest du als Nächstes klären, wer sie verbreitet und ob er Belege vorlegt."],"correctIndex":0,"explanation":"Die Warnsignale (allmächtiger Feind, Beweislastumkehr, Unfalsifizierbarkeit und ähnliche) beschreiben Eigenschaften einer Erzählung: Wie ist sie gebaut, und lässt sie sich überhaupt prüfen? Daraus folgt nichts über den Gesundheitszustand eines Menschen, der sie glaubt. Auch die Fachwelt trennt hier: Psychiater müssen Überzeugungen aus Verschwörungserzählungen erst von Wahn und wahnähnlichen Überzeugungen unterscheiden (Holoyda 2022, Journal of the American Academy of Psychiatry and the Law); meist ist Verschwörungsglaube ein Denkstil und kein Wahn, und ob im Einzelfall mehr dahintersteckt, kann nur eine fachliche Untersuchung klären. Wer aus „glaubt eine unbelegbare Geschichte“ auf „ist krank“ schließt, springt von einer Eigenschaft der Erzählung auf eine Eigenschaft der Person und etikettiert, statt zu prüfen. Ob eine Erzählung stimmt, klärt erst die Prüfung ihrer einzelnen Behauptungen, doch der Bekannte urteilt über die Schwägerin und nicht über den Wahrheitsgehalt. Aus der Zahl der Warnsignale folgt auch nicht, dass die Schwägerin sie übersehen hätte, denn sie kann sie gekannt und anders gewichtet haben. Und die Herkunft der Erzählung zu klären ist ein guter weiterer Prüfschritt, beantwortet aber nicht, ob das Etikett „paranoid“ berechtigt ist.","coreRule":"⚡ Wir sezieren die Erzählung und ihren Denkstil, wir stellen keine Diagnosen über Menschen.","beleg":"Werkstück F.1.3.1 (Der Kipppunkt); Fn. gl-f-wahn (Holoyda 2022, JAAPL 50(1), S. 124--135)","status":"entwurf","kurz":"Die Warnsignale beschreiben, wie die Erzählung gebaut ist und ob sie sich prüfen lässt, nicht, ob ihre Anhängerin seelisch gesund ist. Wer von „glaubt Unbelegbares“ auf „ist krank“ schließt, springt von der Erzählung auf die Person.","prueffrage":"Was weißt du über die Schwägerin außer der Tatsache, dass sie diese Erzählung glaubt?","rueckmeldung":[{"option":1,"text":"Das ist richtig: Ob eine Erzählung stimmt, zeigt erst die Prüfung ihrer Behauptungen. Der Bekannte urteilt aber gar nicht über den Wahrheitsgehalt, sondern über die Schwägerin, und genau diese Frage lässt die Antwort offen."},{"option":2,"text":"Viele Warnsignale legen nahe, dass jemand nicht genau hingesehen hat. Das lässt sich aber nicht daraus schließen: Die Schwägerin kann sie gekannt und anders gewichtet haben. Auch das wäre ein Urteil über die Person, das die Warnsignale nicht tragen."},{"option":3,"text":"Die Herkunft einer Erzählung zu klären ist tatsächlich ein sinnvoller weiterer Prüfschritt. Er sagt aber nichts darüber, ob das Wort „paranoid“ für die Schwägerin berechtigt ist, und beantwortet damit nicht die gestellte Frage."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Holoyda, B. J. (2022): „The QAnon Conspiracy Theory and the Assessment of Its Believers“, Journal of the American Academy of Psychiatry and the Law 50(1)","oeffentlich":true,"url":"https://jaapl.org/content/50/1/124","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1d5bd5d2d1c57dc3"}},{"id":"qx-f-021","clusterId":"F","werkstueckRef":"F.1.4","stufe":1,"question":"Ein Freund nennt eine Gruppe einen Kult, weil sie an Engel glaubt. Woran würdest du stattdessen prüfen, ob die Gruppe ihre Mitglieder manipulativ kontrolliert?","options":["Daran, wie die Gruppe ihre Mitglieder behandelt, denn dort zeigt sich, ob sie deren Kontakte, Informationen, Denken und Gefühle steuert.","Daran, ob sich die Existenz von Engeln belegen lässt, denn das zeigt, ob die Lehre der Gruppe über die Welt zutrifft oder nicht.","Daran, wie viele Mitglieder die Gruppe hat und wie lange es sie schon gibt, denn das zeigt, ob sie eine etablierte Gemeinschaft ist.","Daran, woher die Engelrituale der Gruppe geschichtlich stammen, denn das zeigt, ob ihre Bräuche auf alte Überlieferungen zurückgehen."],"correctIndex":0,"explanation":"Ob eine Gruppe ihre Mitglieder manipulativ kontrolliert, zeigt sich nicht an dem, was sie glaubt, sondern an dem, was sie mit ihren Mitgliedern macht. Geprüft werden Struktur und Verhalten: Wird bestimmt, mit wem man Umgang haben darf? Werden kritische Informationen abgeschnitten? Wird Zweifel bestraft? Werden Angst und Schuld als Druckmittel eingesetzt? Der Glaube an Engel sagt darüber nichts, denn auch viele unbedenkliche Gemeinschaften glauben Dinge, die sich nicht belegen lassen. Und selbst wenn einzelne Merkmale zutreffen, ist nicht jede enge Gemeinschaft ein Kult: Je mehr Kontrollmerkmale in hoher Intensität zusammenkommen, desto eher ist der Einfluss manipulativ.","coreRule":"⚡ Nicht was eine Gruppe glaubt, sondern wie sie ihre Mitglieder kontrolliert, entscheidet über den Kultverdacht.","beleg":"Werkstück F.1.4 (Kontext & Tiefe: Das BITE-Modell der Gedankenkontrolle)","status":"entwurf","scenario":"Im Gespräch fällt der Satz: „Die glauben an Engel, das ist doch ein Kult!“ Über das Verhalten der Gruppe gegenüber ihren Mitgliedern weißt du noch nichts.","quote":"","quoteLabel":"","kurz":"Ob eine Gruppe manipuliert, zeigt sich an ihrem Umgang mit den Mitgliedern: Kontakte, Informationen, Zweifel, Druck. Der Glaube an Engel sagt darüber nichts, denn auch viele unbedenkliche Gemeinschaften glauben Unbelegbares.","prueffrage":"Welche anderen, als harmlos geltenden Gemeinschaften glauben ebenfalls an Engel?","rueckmeldung":[{"option":1,"text":"Ob sich Engel belegen lassen, beantwortet, ob die Lehre stimmt, aber nicht, wie die Gruppe mit ihren Mitgliedern umgeht. Auch viele unbedenkliche Gemeinschaften glauben Dinge, die sich nicht belegen lassen."},{"option":2,"text":"Größe und Alter zeigen, wie etabliert eine Gruppe ist, und das ist ein echtes Merkmal. Über Kontrolle sagt es aber nichts: Auch große, alte Gruppen können Mitglieder steuern, kleine können fair mit ihnen umgehen."},{"option":3,"text":"Woher die Rituale stammen, erklärt ihre Geschichte, nicht den Umgang mit den Mitgliedern. Eine alte Überlieferung entlastet eine Gruppe nicht, eine junge belastet sie nicht; entscheidend ist ihr Verhalten."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Deutscher Bundestag (1998): Endbericht der Enquete-Kommission „Sogenannte Sekten und Psychogruppen“, Drucksache 13/10950","oeffentlich":true,"url":"https://dserver.bundestag.de/btd/13/109/1310950.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"cd640f6028f31374"}},{"id":"qx-f-022","clusterId":"F","werkstueckRef":"F.1.4","stufe":2,"question":"Was ist an diesem Verhalten der Gruppe das eigentlich Auffällige und Prüfenswerte?","scenario":"Du gehst zu einem Vertriebsevent, weil dich eine Bekannte eingeladen hat. Dort wirst du mit Aufmerksamkeit und Lob überschüttet. Ein paar Wochen später heißt es, deine skeptischen Freunde „gönnen dir deinen Erfolg nicht“, und du solltest den Kontakt zu ihnen herunterfahren.","options":["Die Gruppe überschüttet dich zuerst mit Lob und wertet dann deine skeptischen Freunde ab, sodass du von deren Einwänden abgeschnitten wirst.","Die Gruppe verlangt nach dem Lob auf dem Event bald eine hohe Startsumme, sodass dir der Ausstieg wegen des eingesetzten Geldes kaum noch möglich erscheint.","Die Gruppe verspricht dir auf dem Event mit wenig Aufwand hohe Einkünfte, sodass du die Erfolgsaussichten des Vertriebs deutlich überschätzt.","Die Bekannte, die dich eingeladen hat, verschweigt, dass sie an deinem Beitritt verdient, sodass du ihre Motive nicht durchschaust."],"correctIndex":0,"explanation":"Auffällig ist die Kombination aus „Love Bombing“ und der Isolation von kritischen Freunden: Erst gibt es überschwängliche Zuwendung, dann heißt es „Die gönnen dir deinen Erfolg nicht“. Genau dadurch fehlen dir die Menschen, die Einwände äußern würden. Das ist ein Kontrollmuster, kein Zufall: Wer Bindung durch Zuwendung aufbaut und zugleich Kritiker abwertet, macht dich von der Gruppe abhängig. Ob eine Gruppe dir guttut, erkennst du daran, ob sie dein unabhängiges Denken und deine Beziehungen stärkt oder ob sie verlangt, beides zurückzufahren. Eine hohe Startsumme, die den Ausstieg erschwert, wäre bei Vertriebsangeboten prüfenswert, wird hier aber nicht verlangt. Auch ein Einkommensversprechen oder eine verdeckte Provision der Bekannten wären Warnzeichen, nur steht davon im Fall nichts; hier geht es um deine Beziehungen.","coreRule":"⚡ Überschwängliche Zuwendung plus Abkopplung von Kritikern ist ein Kontrollmuster, kein Zufall.","beleg":"Werkstück F.1.4 (Anwendung & Relevanz: Kommerzielle Kulte; BITE: Emotional Control)","status":"entwurf","kurz":"Auffällig ist, dass erst Lob kommt und dann die kritischen Freunde als neidisch gelten. So fehlen dir die Menschen, die Einwände äußern würden, und du wirst von der Gruppe abhängiger. Prüfenswert ist, ob sie dein eigenes Urteil und deine Beziehungen stärkt oder deren Abbau verlangt.","prueffrage":"Woher weiß die Gruppe, warum deine Freunde skeptisch sind, und hat sie je mit ihnen gesprochen?","rueckmeldung":[{"option":1,"text":"Hohe Startsummen, die den Ausstieg erschweren, wären bei Vertriebsangeboten tatsächlich prüfenswert. Im Fall wird aber nirgends Geld verlangt, der Anlass zum Misstrauen liegt woanders: in der Abwertung deiner Freunde."},{"option":2,"text":"Ein Einkommensversprechen mit wenig Aufwand wäre ein klares Warnzeichen. Davon steht im Fall aber nichts: Es gibt Lob und Aufmerksamkeit, und später den Rat, Freunde auf Abstand zu halten. Das Muster betrifft deine Beziehungen, nicht Erwartungen an den Verdienst."},{"option":3,"text":"Eine verdeckte Provision der Bekannten wäre allerdings ein Grund zur Vorsicht. Im Fall wird so etwas aber nicht erwähnt. Selbst dann bliebe unerklärt, warum später die skeptischen Freunde abgewertet werden, denn genau das ist hier das Auffällige."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"f1b7b7a8948ec9e3"}},{"id":"qx-f-023","clusterId":"F","werkstueckRef":"F.1.4","stufe":3,"question":"Was spricht am stärksten gegen den Plan der Behörde?","options":["Die Studie zeigt nur, dass die Punkte zusammenpassen, nicht dass sie Manipulation messen; sie stammt vom Entwickler, und ein Ja zeigt noch keine Intensität.","Die Liste stammt aus der Beratung religiöser Aussteiger; bei Chor und Sportverein fragt sie deshalb Bereiche ab, die es in weltlichen Gruppen gar nicht gibt.","Die Ja-Antworten bei Chor, Sportverein und Kloster beweisen, dass die Liste falsch misst, denn solche Gruppen üben keinerlei Kontrolle über Mitglieder aus.","Der Entwickler ist als früherer Aussteiger befangen; wer selbst in einer Gruppe war, kann kein Werkzeug entwickeln, das in der Beratung irgendeinen Nutzen hat."],"correctIndex":0,"explanation":"Wer ein Instrument selbst entwickelt und selbst prüft, kann Schwächen übersehen; dass die Punkte einer Liste in sich stimmig sind, zeigt nur, dass sie zusammenpassen, nicht dass sie das Gemeinte zuverlässig messen. Dafür braucht es eine unabhängige Prüfung, und die fehlt hier. Hinzu kommt: Ein Teil der beschriebenen Kontrolle gehört unvermeidlich zu jeder Gemeinschaft (so die Enquete-Kommission des Bundestages 1998), entscheidend sind Intensität und Verlust der Selbstbestimmung; die Ja-Antworten bei Chor, Sportverein und Kloster beweisen deshalb noch keine Manipulation. Als Orientierungshilfe in der Beratung kann die Liste nützlich sein, als verbindliche amtliche Messlatte reicht sie nicht. Die abgefragten Kontrollbereiche sind nicht an Religion gebunden, wie gerade der Probelauf mit weltlichen Gruppen zeigt. Dass Chor und Verein gar keine Kontrolle ausüben, stimmt nicht, denn ein gewisses Maß gehört zu jeder Gemeinschaft. Und die Herkunft des Entwicklers macht die Liste nicht nutzlos; das Problem ist die fehlende unabhängige Prüfung, nicht seine Biografie.","coreRule":"⚡ Als Checkliste brauchbar, als Messlatte ungeeignet: Wer das eigene Instrument selbst prüft, liefert keine unabhängige Prüfung, und entscheidend sind Intensität und Verlust der Selbstbestimmung.","beleg":"Werkstück F.1.4 (Das BITE-Modell); Fn. gl-f-6; Fn. gl-f-enquete (Bundestag 1998, Drucksache 13/10950, S. 77)","status":"entwurf","scenario":"Eine Behörde will Gruppen amtlich als manipulativ einstufen und dafür eine Merkmalsliste als verbindliches Messinstrument nutzen. Entwickelt hat sie ein früherer Sektenaussteiger, der heute Betroffene berät; die Liste fragt Kontrolle über Verhalten, Information, Gedanken und Gefühle ab. Als Beleg für ihre Zuverlässigkeit führt er eine eigene Fragebogenstudie an, nach der die Punkte der Liste in sich stimmig sind. In einem Probelauf erhalten auch ein Chor, ein Sportverein und ein Kloster bei einzelnen Punkten ein Ja.","kurz":"Dass die Punkte der Liste zusammenpassen, belegt nicht, dass sie Manipulation messen, und geprüft hat sie nur ihr Entwickler selbst. Für eine verbindliche amtliche Messlatte fehlt eine unabhängige Prüfung; als Orientierungshilfe in der Beratung kann sie dennoch taugen.","prueffrage":"Wer hat die Zuverlässigkeit der Liste geprüft, und wäre das Ergebnis auch bei einer Prüfung durch Dritte so ausgefallen?","rueckmeldung":[{"option":1,"text":"Dass die Liste aus der Beratung stammt, lässt vermuten, sie sei auf bestimmte Gruppen zugeschnitten. Die abgefragten Bereiche, Verhalten, Information, Gedanken und Gefühle, gibt es aber in jeder Gemeinschaft, wie der Probelauf mit Chor und Sportverein gerade zeigt."},{"option":2,"text":"Die Ja-Antworten bei Chor, Sportverein und Kloster zeigen tatsächlich, dass ein Ja allein noch keine Manipulation belegt. Doch ein gewisses Maß an Kontrolle gehört zu jeder Gemeinschaft; entscheidend sind Intensität und Verlust der Selbstbestimmung. Dass die Liste falsch misst, folgt daraus nicht."},{"option":3,"text":"Wer ein Werkzeug selbst entwickelt und selbst prüft, übersieht leicht Schwächen. Das liegt aber am fehlenden Gegenprüfen, nicht an der Biografie: Ob die Liste in der Beratung als Orientierung nützt, hängt nicht davon ab, dass der Entwickler selbst in einer Gruppe war."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Deutscher Bundestag (1998): Endbericht der Enquete-Kommission „Sogenannte Sekten und Psychogruppen“, Drucksache 13/10950","oeffentlich":true,"url":"https://dserver.bundestag.de/btd/13/109/1310950.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hassan, S. A. (2020): The BITE Model of Authoritarian Control. Diss. Fielding Graduate University","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"27a8f19a4268d687"}},{"id":"qx-f-024","clusterId":"F","werkstueckRef":"F.1.4","stufe":4,"question":"Eine Person bestimmt, mit wem ihr Partner Umgang hat, verwaltet dessen Geld allein und macht dessen Freunde schlecht. Eine Bekannte meint: „Kontrolle in dieser Form gibt es nur in Sekten, in einer Zweierbeziehung kann das gar nicht passieren.“ Welche Antwort trifft den Denkfehler am besten?","options":["Sie schließt von der bekanntesten Form auf die einzige: Entscheidend ist nicht die Gruppengröße, sondern ob Umgang, Geld und Information gezielt gelenkt werden, um den anderen abhängig zu machen.","Sie baut einen Strohmann: Sie verzerrt die Position der kontrollierenden Person zu einer Karikatur, damit sie sich leichter widerlegen lässt, und befasst sich nicht mit dem tatsächlichen Verhalten.","Sie unterstellt eine Rutschbahn: Sie nimmt an, dass aus jedem Eingriff in den Umgang zwangsläufig immer schwerere Eingriffe folgen, ohne zu belegen, dass jeder Schritt den nächsten nach sich zieht.","Sie greift die Person an statt das Verhalten: Sie wertet die kontrollierende Person als Mensch ab, anstatt zu prüfen, ob ihr Verhalten tatsächlich andere in Abhängigkeit bringt."],"correctIndex":0,"explanation":"Die Bekannte schließt von der bekanntesten Form (Sekte) auf die einzige Form. Entscheidend ist aber die Struktur: Wer Kontakte einschränkt, finanzielle Abhängigkeit schafft und Freunde abwertet, isoliert den anderen und entzieht ihm andere Informations- und Rückhalt-Quellen. Das sind dieselben Kontrollmechanismen, die man bei manipulativen Gruppen beobachtet, nur im Format einer Zweierbeziehung. Dafür braucht es weder einen Anführer noch eine Gruppe. Dabei gilt: Ein gewisses Maß an Einfluss gehört zu jeder Gemeinschaft, problematisch wird es erst bei systematischer Isolation, Abhängigkeit und Manipulation. Ein Strohmann würde eine fremde Position verzerren, die Bekannte stellt aber eine eigene, überprüfbare Behauptung auf. Eine Rutschbahn braucht eine behauptete Kette von Folgen, die hier nirgends vorkommt. Und einen Angriff auf die Person gibt es nicht: Sie bewertet weder den Menschen noch sein Verhalten, sondern bestreitet nur, dass so etwas außerhalb von Sekten vorkommt.","coreRule":"⚡ Prüfe die Struktur der Kontrolle (Umgang, Geld, Information, Gefühle), nicht die Größe oder das Etikett der Gruppe.","beleg":"Werkstück F.1.4 (Anwendung & Relevanz: Missbräuchliche Beziehungen)","status":"entwurf","scenario":"","kurz":"Aus „die bekannteste Form findet sich in Sekten“ wird „nur dort“. Entscheidend ist aber nicht die Gruppengröße, sondern ob Umgang, Geld und Information gezielt gelenkt werden, um den anderen abhängig zu machen. Das geht auch zu zweit.","prueffrage":"Welcher der drei Schritte, die die Person unternimmt, wäre ohne eine Gruppe im Hintergrund nicht möglich?","rueckmeldung":[{"option":1,"text":"Ein Strohmann würde eine fremde Position verzerren und die Karikatur widerlegen. Die Bekannte stellt aber eine eigene, überprüfbare Behauptung auf, nämlich dass so etwas nur in Sekten vorkomme. Ihr Fehler liegt im Schluss selbst."},{"option":2,"text":"Eine Rutschbahn setzt eine behauptete Kette von Folgen voraus, bei der ein Schritt angeblich den nächsten nach sich zieht. Die Bekannte spricht aber von keiner Eskalation, sondern bestreitet nur, dass solche Kontrolle in Zweierbeziehungen vorkommt."},{"option":3,"text":"Ein Angriff auf die Person wertet den Menschen ab, statt die Sache zu prüfen. Die Bekannte sagt nichts über den Charakter der kontrollierenden Person; sie behauptet nur, wo solche Kontrolle auftreten kann. Das ist ein Fehlschluss über die Sache."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Crown Prosecution Service: „Controlling or Coercive Behaviour in an Intimate or Family Relationship“ (Leitlinie, Stand 07.02.2025)","oeffentlich":true,"url":"https://www.cps.gov.uk/legal-guidance/controlling-or-coercive-behaviour-intimate-or-family-relationship","abruf":"2026-10-12"},{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2180c8562b9bbad3"}},{"id":"qx-f-025","clusterId":"F","werkstueckRef":"F.1.5","stufe":1,"question":"Welche Frage hilft dir am besten, bei einer beeindruckend aussehenden „Studie“ zu prüfen, ob sie echte Forschung ist oder nur deren äußere Form nachahmt?","options":["Ob die Zahlen im Bericht rechnerisch stimmen und ob die Grafiken sauber beschriftet und nachvollziehbar aufgebaut sind","Ob das Institut ein Impressum mit Adresse hat und ob die Autoren mit „Dr.“ öffentlich auffindbar und überprüfbar sind","Ob der Bericht auch Ergebnisse nennt, die der Behauptung widersprechen, und ob andere Forscher sie wiederholen konnten","Ob der Bericht die Fachbegriffe korrekt verwendet und durchgehend sachlich bleibt, ohne jede Werbesprache oder Übertreibung"],"correctIndex":2,"explanation":"Jargon, Grafiken, Titel und Institutsnamen lassen sich leicht nachahmen, sie sagen nichts darüber, ob die Methode taugt. Entscheidend ist die selbstkritische Redlichkeit: Echte Forschung berichtet auch Belege, die der eigenen Theorie widersprechen, und sucht aktiv nach Wegen, sie zu widerlegen. Ob unabhängige Forscher das Ergebnis wiederholen können, zeigt, ob mehr dahintersteckt als eine schön gebaute Hülle. Der Physiker Richard Feynman nannte dieses Muster „Cargo-Kult-Wissenschaft“: Inselbewohner bauten nach dem Zweiten Weltkrieg Landebahnen, Feuer und Holz-Kopfhörer nach, um Flugzeuge zurückzulocken. Die Form stimmte, das Verständnis fehlte, und die Flugzeuge blieben aus.","coreRule":"⚡ Nicht das Aussehen, sondern die Redlichkeit macht Wissenschaft aus: Frag nach Gegenbelegen und Wiederholbarkeit, nicht nach Jargon und Titeln.","beleg":"Werkstück F.1.5 (Kernidee; Kontext & Tiefe); Fn. gl-f-7 (Feynman 1974, Caltech-Rede)","status":"entwurf","scenario":"Ein Institut, das du nicht kennst, veröffentlicht einen Bericht mit Fachjargon, vielen Grafiken und Titeln wie „Dr.“. Der Bericht stützt eine Behauptung, die dir zweifelhaft vorkommt.","kurz":"Ob ein Bericht auch Belege gegen die eigene Behauptung nennt und ob andere Forscher das Ergebnis wiederholen konnten, zeigt echte Forschung. Jargon, Titel und Grafiken lassen sich nachbauen, wie die Landebahnen im Cargo-Kult: Die Form stimmt, das Verständnis fehlt.","prueffrage":"Welche der Merkmale, die dich an dem Bericht beeindrucken, könnte auch jemand ohne echte Daten herstellen?","rueckmeldung":[{"option":0,"text":"Stimmige Zahlen und saubere Grafiken sind ein sinnvoller erster Check, grobe Fehler wären ein Warnsignal. Beides lässt sich aber ebenso nachbauen wie Jargon und sagt nicht, ob die Methode taugt oder Widersprechendes verschwiegen wurde."},{"option":1,"text":"Ein Impressum und auffindbare Autoren zeigen, dass es das Institut gibt und Verantwortliche greifbar sind. Ob dort sauber geforscht wird, folgt daraus nicht, denn auch Titel und Institutsnamen gehören zur nachahmbaren äußeren Form."},{"option":3,"text":"Korrekt gebrauchte Fachbegriffe in nüchternem Ton wirken seriös, gehören aber gerade zur äußeren Form, die sich leicht übernehmen lässt. Werbesprache kann misstrauisch machen, ihr Fehlen belegt jedoch keine gute Methode."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11, 13","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e5c3cf3e9faed809"}},{"id":"qx-f-026","clusterId":"F","werkstueckRef":"F.1.5","stufe":2,"question":"Wie bewertest du das Vorgehen der Gruppe?","scenario":"Eine Forschungsgruppe testet Telepathie in 40 Versuchsreihen. Veröffentlicht werden die drei Reihen mit auffälligem Treffer, die übrigen 37 verschwinden in der Schublade. Ein Kollege sagt: „Drei klare Treffer sind doch ein Ergebnis. Es steht ja alles korrekt in der Veröffentlichung.“","options":["Als vertretbar, denn die drei Treffer sind korrekt wiedergegeben; unredlich wäre erst, Daten zu fälschen, und das ist bei den 40 Versuchsreihen nicht geschehen.","Als Verwechslung von Auffälligkeit und Bedeutung, denn drei auffällige Reihen sagen noch nichts darüber, wie groß oder wichtig ein Telepathie-Effekt tatsächlich wäre.","Als Nachahmung von Forschung ohne ihren Kern, denn wer nur die drei Treffer zeigt und die 37 Fehlschläge verschweigt, täuscht ein Ergebnis vor, das die Gesamtlage nicht trägt.","Als Verzerrung durch Selbstauswahl der Teilnehmenden, denn wer sich für telepathisch begabt hält, meldet sich eher zu den Versuchen und verfälscht so die Stichprobe."],"correctIndex":2,"explanation":"Aussagekraft hat erst das Gesamtbild aller Versuche, nicht die herausgepickten Treffer. Wer nur die drei Treffer zeigt und die 37 Fehlschläge verschweigt, erzeugt den Eindruck eines Effekts, den die Daten insgesamt nicht hergeben. Redliche Forschung berichtet auch über alles, was der eigenen Hypothese widerspricht. Fachsprache, Versuchsaufbau und Veröffentlichung können dann perfekt aussehen, und trotzdem fehlt der Kern der Wissenschaft: die Bereitschaft, die eigene Idee scheitern zu sehen. Feynman nannte das Cargo-Kult-Wissenschaft: Die Landebahn steht, aber die Flugzeuge der Erkenntnis landen dort nicht. Die Pflicht, auch widersprechende Ergebnisse zu berichten, besteht unabhängig davon, ob die Gruppe von Beweis spricht. Dass die drei Treffer für sich richtig wiedergegeben sind, klingt nach Redlichkeit, doch das Verschweigen der übrigen Reihen täuscht auch ohne gefälschte Zahl. Wie groß oder wichtig ein Effekt wäre, ist hier nicht die Frage, sondern welche Reihen gezeigt werden. Und eine Selbstauswahl der Teilnehmenden betrifft die Zusammensetzung der Stichprobe, nicht das Weglassen ganzer Reihen.","coreRule":"⚡ Wer Fehlschläge verschweigt, baut nur die Landebahn, aber keine Wissenschaft.","beleg":"Werkstück F.1.5 (Anwendung & Relevanz: In der Parapsychologie)","status":"entwurf","kurz":"Aussagekraft hat nur das Gesamtbild aller 40 Reihen. Wer nur drei Treffer zeigt und 37 Fehlschläge weglässt, erzeugt den Eindruck eines Effekts, den die Daten insgesamt nicht hergeben, auch wenn jede einzelne Zahl stimmt.","prueffrage":"Wie viele auffällige Treffer würde man bei 40 Versuchsreihen allein durch Zufall erwarten?","rueckmeldung":[{"option":0,"text":"Dass die drei Treffer korrekt wiedergegeben sind, stimmt. Redlichkeit endet aber nicht beim Nicht-Fälschen: Wer 37 von 40 Reihen weglässt, täuscht auch ohne verfälschte Zahl, weil das Gesamtbild fehlt."},{"option":1,"text":"Wie groß oder wichtig ein Telepathie-Effekt wäre, ist eine berechtigte, aber andere Frage. Hier geht es darum, welche Reihen überhaupt gezeigt werden: Fehlen 37 von 40, lässt sich über die Effektgröße noch gar nichts sagen."},{"option":3,"text":"Selbstauswahl der Teilnehmenden kann eine Stichprobe tatsächlich verzerren, betrifft aber die Zusammensetzung der Gruppe. Davon steht im Szenario nichts; der Mangel liegt darin, dass 37 Reihen verschwinden."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11–12","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d6d9e3f234c0c987"}},{"id":"qx-f-027","clusterId":"F","werkstueckRef":"F.1.5","stufe":3,"question":"Dein Kollege sagt dazu: „Unseriöse Forschung gibt es nur bei Homöopathen und Parapsychologen. Was an einer Hochschule veröffentlicht wird, hat Institut, Fachjargon und Peer-Review, also ist es automatisch Wissenschaft.“ Was ist an diesem Schluss fehlerhaft?","options":["Er schließt von der äußeren Form auf die Qualität: Institut, Fachjargon und Peer-Review sagen nichts darüber, ob die Forschenden ihre eigenen Ideen ernsthaft scheitern lassen wollten.","Er schließt von der Medienaufmerksamkeit auf die Belegtheit: Weil über die Studie eine Schlagzeile erscheint, hält er ihre Behauptung für gesichert, ohne ihre Methode zu kennen.","Er schließt von einzelnen Fällen auf alle: Weil er fehlerhafte Hochschulstudien kennt, hält er die gesamte Hochschulforschung für unseriös und lehnt auch gute Studien ab.","Er schließt von der Quelle auf die Absicht: Weil Hochschulen Drittmittel einwerben, hält er ihre Studien für zwangsläufig verfälscht, wie sorgfältig auch gearbeitet wurde."],"correctIndex":0,"explanation":"Der Kollege verwechselt die äußere Form der Wissenschaft mit ihrer Substanz. Ob Forschung trägt, entscheidet sich an der selbstkritischen Redlichkeit: Werden Gegenbelege gesucht und berichtet, gibt es Kontrollgruppen, ist das Ergebnis wiederholbar? Das gilt überall, auch an Hochschulen. Richard Feynman nannte in seiner Rede „Cargo Cult Science“ (1974) ausdrücklich auch Studien zu Lesemethoden und Rattenversuche der Psychologie, die die sorgfältigen Kontrollen eines vorbildlichen Vorgängers nicht beachteten, als Beispiele für Forschung, die nur die Form der Wissenschaft wahrt. Die anderen Schlüsse sind bekannte Fehlschlüsse, die der Kollege hier aber nicht zieht: Er nimmt nicht das Medienecho der Schlagzeile als Beleg für die Studie. Er verwirft auch nicht die Hochschulforschung wegen einzelner Fehler, im Gegenteil. Und von Drittmitteln und Geldgebern spricht er nicht. Sein Fehler ist, die Form als Beweis der Substanz zu nehmen.","coreRule":"⚡ Ein Titel, ein Institut und Fachjargon beweisen keine Redlichkeit: Prüfe die Methode, nicht das Etikett.","beleg":"Werkstück F.1.5 (Kernidee); Fn. gl-f-7 (Quelle der Feynman-Rede „Cargo Cult Science“, 1974)","status":"entwurf","scenario":"Ihr sprecht über eine Schlagzeile zu einer neuen Studie, die an einer Universität entstanden ist.","kurz":"Institut, Fachjargon und Peer-Review sind nur die äußere Form. Ob eine Studie trägt, zeigt sich daran, ob die Forschenden ihre Idee ernsthaft scheitern lassen wollten, etwa mit Kontrollgruppen und der Suche nach Gegenbelegen. Wer die Form für den Beweis nimmt, übersieht das.","prueffrage":"Ist schon einmal eine Hochschulstudie mit Peer-Review später zurückgezogen worden oder bei der Wiederholung gescheitert?","rueckmeldung":[{"option":1,"text":"Eine Schlagzeile allein belegt tatsächlich nichts, und ihr Anlass ist hier gegeben. Der Kollege beruft sich aber nicht auf das Medienecho, sondern auf Institut, Fachjargon und Peer-Review. Sein Fehler liegt woanders."},{"option":2,"text":"Von wenigen Fällen auf alles zu schließen, wäre ein Fehler, nur zieht der Kollege diesen Schluss nicht. Er nennt keine schlechten Hochschulstudien und lehnt auch keine ab, sondern hält Hochschulforschung pauschal für Wissenschaft."},{"option":3,"text":"Geldgeber können Studien beeinflussen, das ist ein eigenes Thema. Der Kollege spricht aber weder von Drittmitteln noch von Absichten und misstraut Hochschulen nicht, sondern vertraut ihnen allein wegen ihrer Form."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 10, 13","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"661ce019a762c596"}},{"id":"qx-f-028","clusterId":"F","werkstueckRef":"F.1.6","stufe":1,"question":"Ein Bekannter sagt: „Meine Schwester ist Ärztin und gewohnt, Behauptungen kritisch zu prüfen. Seit dem Tod ihres Mannes schwört sie auf einen Heiler, der angeblich Kontakt zu Verstorbenen herstellt. Ausgerechnet sie fällt auf so etwas nie herein, da muss etwas dran sein.“ Welcher Schluss ist am besten begründet?","options":["Die einfachste Erklärung ist, dass der Heiler wirklich Kontakt herstellt, denn nach dem Sparsamkeitsprinzip zählt die Erklärung mit den wenigsten Annahmen.","Die Überzeugung der Ärztin beweist wenig, denn auch geübte Skeptiker prüfen Behauptungen nicht mehr, wenn der Verlust ihres Mannes ein tiefes Bedürfnis berührt.","Solange niemand bewiesen hat, dass der Heiler keinen Kontakt herstellen kann, spricht die Erfahrung der Ärztin dafür, dass es möglich ist, und die Beweislast liegt bei den Zweiflern.","Ihre Berufserfahrung macht sie zur verlässlichen Prüferin, denn wer täglich Behauptungen kritisch prüft, erkennt auch bei einem Heiler, was echt ist."],"correctIndex":1,"explanation":"Intelligenz oder Fachkompetenz belegen nicht, dass eine Überzeugung stimmt. Das zeigt der Fall des Schriftstellers Arthur Conan Doyle: Der Schöpfer des kühlen Logikers Sherlock Holmes hielt nach den Verlusten im Ersten Weltkrieg die inszenierten „Cottingley Fairies“-Fotos trotz ihrer Fälschung für Zeugnisse einer unsichtbaren Lebensform, öffentlich vorsichtig als starken ersten Anschein, privat als erwiesen. Kritisches Denken ist keine feste Eigenschaft, sondern eine Praxis, die bewusst angewendet werden muss; niemand ist durch Intelligenz oder Skepsis dauerhaft immun. Ein überwältigendes Bedürfnis nach Trost oder Hoffnung kann sie ausgerechnet bei der eigenen Überzeugung abschalten, und dann dient der Verstand als Anwalt für den Glauben statt als Prüfer. Der Verweis auf ihre Kompetenz hilft also nicht weiter; entscheidend ist, ob die Behauptung selbst einer Prüfung standhält. Das Sparsamkeitsprinzip stützt hier eher die Gegenseite, denn dass Trauer ein Urteil färbt, braucht weniger Annahmen als ein Kontakt zu Verstorbenen. Dass niemand das Gegenteil bewiesen hat, ist kein Beleg, denn wer etwas behauptet, muss es belegen. Und die Routine einer Ärztin im Prüfen von Behauptungen gilt für ihren Beruf; sie schützt nicht davor, dass ein tiefes Bedürfnis die Prüfung bei der eigenen Überzeugung aussetzt.","coreRule":"⚡ Skepsis ist eine Praxis, keine Eigenschaft: Sie muss gerade dort angewendet werden, wo es weh tut.","beleg":"Werkstück F.1.6 (Kernidee; Anwendung & Relevanz)","status":"entwurf","scenario":"Ein Bekannter erzählt dir von seiner Schwester, einer erfahrenen Ärztin. Sie ist es gewohnt, Behauptungen kritisch zu prüfen, glaubt aber seit dem Tod ihres Mannes fest an einen Heiler, der angeblich Kontakt zu Verstorbenen herstellt.","quote":"","quoteLabel":"","kurz":"Fachkompetenz sagt nicht, ob eine bestimmte Überzeugung stimmt, denn ein tiefes Bedürfnis nach Trost kann die Prüfung ausgerechnet bei der eigenen Überzeugung abschalten. Der Fehler ist, aus „sie prüft sonst kritisch“ zu schließen, dass sie es auch hier tut.","prueffrage":"Welche Belege für die Fähigkeiten des Heilers gibt es außer der Überzeugung der Ärztin selbst?","rueckmeldung":[{"option":0,"text":"Das Sparsamkeitsprinzip ist ein gutes Werkzeug, spricht hier aber gegen den Kontakt: Dass Trauer ein Urteil färbt, braucht weniger Annahmen als ein Kontakt zu Verstorbenen mit allem, was dazugehörte."},{"option":2,"text":"Ein Kontakt zu Verstorbenen lässt sich schwer widerlegen, das macht ihn aber nicht wahrscheinlicher. Wer etwas behauptet, muss es belegen; fehlender Gegenbeweis ersetzt keinen Beleg, und die Erfahrung der Ärztin ist ebenfalls keiner."},{"option":3,"text":"Im Beruf prüft die Ärztin vermutlich gut. Diese Routine schützt aber nicht davor, dass ein tiefes Bedürfnis die Prüfung bei der eigenen Überzeugung aussetzt, und dann zeigt ihre Kompetenz nichts über den Heiler."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies, Kap. II (Strand-Artikel: „strong prima facie case“) und Kap. IV (Brief an Gardner: „You and I needed no confirmation“) (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Leeds Library, Special Collections: Katalogeintrag Cottingley Fairies","oeffentlich":true,"url":"https://explore.library.leeds.ac.uk/special-collections-explore/8705","abruf":"2026-10-12"},{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7edb4cf2b0bd2ff7"}},{"id":"qx-f-029","clusterId":"F","werkstueckRef":"F.1.6","stufe":2,"question":"Was zeigt dieser Unterschied am ehesten?","options":["Er zweifelt privat stärker als öffentlich und fürchtet insgeheim, dass die Belege gefälscht sind.","Er ist sich öffentlich wie privat gleich sicher und nennt die Belege überall den endgültigen Beweis.","Er hat die Überzeugung längst gefasst und gibt sich nach außen nur vorsichtig, statt die Belege ergebnisoffen zu prüfen.","Er hat die Belege inzwischen gründlich widerlegt und gibt sich nach außen nur aus Höflichkeit vorsichtig."],"correctIndex":2,"explanation":"Die vorsichtige öffentliche Formulierung und die private Gewissheit passen nicht zusammen. Das spricht dafür, dass die Überzeugung innerlich schon feststeht und die Vorsicht nach außen eher Zurückhaltung oder Taktik ist. Die Belege werden dann eher verteidigt als ergebnisoffen geprüft. Hohe Intelligenz schützt davor nicht: Sie liefert dann bloß bessere Argumente für das, was man ohnehin glauben will. Gerade bei Behauptungen, die ein tiefes persönliches Bedürfnis berühren, lohnt es sich daher, genau auf diese Diskrepanz zu achten. Ein Beispiel ist Arthur Conan Doyle, der Schöpfer von Sherlock Holmes: Öffentlich sprach er von einem „starken ersten Anschein“ der Cottingley-Feenfotos (Strand-Artikel vom Dezember 1920), im Brief an seinen Mitstreiter E. L. Gardner vom Oktober 1920 hielt er die Sache dagegen für erwiesen.","coreRule":"⚡ Wer privat schon überzeugt ist, prüft öffentlich nur noch pro forma: Der Wunsch regiert.","beleg":"Werkstück F.1.6 (Der Riss in der Festung); Fn. gl-f-doyle (Doyle 1922, Kap. I, II und IV)","status":"entwurf","scenario":"Ein sehr kluger, öffentlich bekannter Mann verteidigt eine Behauptung, die ihm seit einem schweren Verlust sehr wichtig ist. Der Verlust liegt kurz zurück, die Behauptung verspricht ihm Trost, und die Belege sind dünn. Öffentlich schreibt er, die Belege sprächen für einen „starken ersten Anschein“, mehr nicht; in einem privaten Brief an einen Gleichgesinnten nennt er die Sache längst erwiesen.","kurz":"Wer öffentlich nur von einem „starken ersten Anschein“ spricht, privat aber von „längst erwiesen“, hat sich vermutlich schon festgelegt. Die Vorsicht nach außen ist dann eher Zurückhaltung oder Taktik, und die Belege werden verteidigt statt ergebnisoffen geprüft.","prueffrage":"Wie stark sind die Belege, und welche der beiden Äußerungen geht über das hinaus, was sie hergeben?","rueckmeldung":[{"option":0,"text":"Der Unterschied springt ins Auge, und man liest ihn schnell als verborgenen Zweifel. Der Brief nennt die Sache aber „längst erwiesen“: Das zeigt private Gewissheit, nicht Unsicherheit, und von gefälschten Belegen ist nirgends die Rede."},{"option":1,"text":"Privat ist er tatsächlich sehr sicher. Öffentlich spricht er aber nur von einem „starken ersten Anschein“, mehr nicht. Die beiden Aussagen sind gerade nicht gleich, und genau dieser Unterschied ist das Auffällige."},{"option":3,"text":"Höfliche Zurückhaltung wäre eine freundliche Lesart. Wer die Belege aber widerlegt hätte, würde die Sache privat nicht „längst erwiesen“ nennen. Von einer Widerlegung ist nirgends die Rede, die Belege sind nur dünn."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies, Kap. II und IV (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahan, D. M. u. a. (2013): Motivated Numeracy and Enlightened Self-Government (Working Paper)","oeffentlich":true,"url":"https://scholarsbank.uoregon.edu/items/e034d504-ed17-4e0c-a713-ac3f85a8187a/full","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d323cc46a3a5e95b"}},{"id":"qx-f-030","clusterId":"F","werkstueckRef":"F.1.6","stufe":3,"question":"Was ändert sich am Wechsel vom Freundeskreis zur Kolumne am stärksten?","options":["Neu ist, dass sie ihren guten Ruf einsetzt, um eine unbewiesene Behauptung zu verbreiten, sodass andere ihr vertrauen, ohne selbst zu prüfen.","Neu ist, dass sie Prüfungen mit immer neuen Ausreden entkräftet, sodass ihre Überzeugung durch keinen Befund mehr widerlegbar ist.","Neu ist, dass der Verlust ihres Bruders ihr Urteil trübt, sodass sie ihre eigene Überzeugung nicht mehr nüchtern prüfen kann.","Neu ist, dass sie in zufälligen Signalen des Geräts Muster erkennt, sodass sie bloßes Rauschen als Botschaft von Verstorbenen deutet."],"correctIndex":0,"explanation":"Ein privater Glaube, der Trost spendet, betrifft vor allem die Person selbst. Problematisch wird es, wenn Ansehen und Reichweite eingesetzt werden, um eine ungeprüfte Behauptung zu verbreiten: Andere vertrauen ihr womöglich, weil der Name der Person dem Unsinn den „Stempel der Genialität“ verleiht, statt selbst zu prüfen (Appell an die falsche Autorität). Genau das tat Arthur Conan Doyle, als er die Cottingley-Feen-Fotos mit seinem Ruf als Denker adelte; sie waren, wie die Mädchen später zugaben, mit Papierfiguren und Nadeln inszeniert. Dass jemand Trost sucht, ist menschlich; zur Gefahr wird es, wenn das Vertrauen in einen Namen an die Stelle der Prüfung tritt und andere in die Irre führt.","coreRule":"⚡ Privater Trost ist Privatsache; zur Gefahr wird er, wenn berühmte Autorität ihn in die Öffentlichkeit trägt und andere das Prüfen ersetzen lässt.","beleg":"Werkstück F.1.6 (Der Kipppunkt)","status":"entwurf","scenario":"Eine für ihren scharfen Verstand berühmte Wissenschaftsjournalistin hat ihren Bruder verloren. Seitdem ist sie überzeugt, dass sich Verstorbene über ein bestimmtes Gerät melden, und ist dafür bisher keiner Prüfung begegnet, die sie nicht mit immer neuen Ausreden entkräftet hätte. Zunächst erzählt sie nur Freunden davon. Dann beginnt sie, das Gerät in einer reichweitenstarken Kolumne als gut belegt zu empfehlen.","kurz":"Der Glaube selbst bleibt derselbe; neu ist, dass ihr Ruf nun als Bürgschaft dient. Wer ihrem Namen vertraut, übernimmt die Behauptung, statt sie zu prüfen, und genau so wirkt der Appell an die falsche Autorität.","prueffrage":"Was an ihrer Überzeugung und an ihrem Umgang mit Prüfungen ist vor und nach dem Wechsel gleich geblieben?","rueckmeldung":[{"option":1,"text":"Dieses Ausweichen vor Prüfungen ist auffällig, kam aber schon vor der Kolumne vor. Es erklärt ihren Glauben, nicht, was sich ändert, wenn sie ihn mit großer Reichweite vor anderen vertritt."},{"option":2,"text":"Trauer kann das Urteil trüben, das wirkte aber schon im Freundeskreis. Neu ist nicht ihr Zustand, sondern dass durch die Reichweite viele Menschen dieser Behauptung vertrauen könnten."},{"option":3,"text":"Ob sie Zufälliges als Botschaft deutet, betrifft ihren eigenen Glauben und wäre im Freundeskreis nicht anders. Am Wechsel zur Kolumne ändert sich etwas anderes: die Wirkung auf Menschen, die ihr vertrauen."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Leeds Library, Special Collections: Katalogeintrag Cottingley Fairies (Veröffentlichung im Strand Magazine 1920/1921, Papierfiguren mit Hutnadeln, Geständnis 1983)","oeffentlich":true,"url":"https://explore.library.leeds.ac.uk/special-collections-explore/8705","abruf":"2026-10-12"},{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8e794de8f86f9367"}},{"id":"qx-f-031","clusterId":"F","werkstueckRef":"F.1.6","stufe":4,"question":"Wie gehst du mit ihr am sinnvollsten um?","scenario":"Eine kluge Bekannte vertraut seit dem Tod ihres Mannes den Botschaften eines Mediums. Wenn du Widersprüche ansprichst, findet sie jedes Mal eine neue, geschickte Begründung, warum die Botschaften trotzdem stimmen. Du möchtest ihr helfen und dabei nicht überheblich wirken.","options":["Die Widersprüche in den Botschaften sammeln und ihr gebündelt vorlegen, denn je mehr Belege zusammenkommen, desto schwerer lässt sich der Glaube an das Medium halten.","Gemeinsam mit anderen Angehörigen deutlich machen, dass das Medium sie täuscht, denn mehrere Stimmen überzeugen eher als ein einzelner Einwand von dir allein.","Nach dem Bedürfnis fragen, das der Glaube an das Medium seit dem Tod ihres Mannes für sie erfüllt, denn Intelligenz schützt nicht vor Selbsttäuschung, wenn ein Wunsch im Spiel ist.","Das Thema vorerst ruhen lassen und das Medium nicht mehr ansprechen, denn Kritik an einer Überzeugung wirkt in der Trauer um ihren Mann in aller Regel unpassend."],"correctIndex":2,"explanation":"Intelligenz ist kein Gütesiegel für einzelne Behauptungen, und wer in einem Gebiet brillant ist, kann in einem anderen völlig danebenliegen (Appell an die falsche Autorität). Kein Mensch ist immun gegen Selbsttäuschung, egal wie intelligent oder skeptisch er sonst ist. Auffällig ist hier das Muster: Eine intelligente Person verteidigt eine unbewiesene Behauptung, die ein tiefes persönliches Bedürfnis berührt, wendet ihre kritischen Fähigkeiten nicht auf die eigene, liebgewonnene Überzeugung an und erfindet für widersprüchliche Beweise immer neue Rationalisierungen. Der Schlüssel liegt also im Bedürfnis dahinter (Trost, Hoffnung, Sinn). Die Frage, welches tiefe emotionale Bedürfnis dieser Glaube für sie erfüllt, nimmt sie ernst und zeigt, warum die Prüfung bei ihr aussetzt. Das schafft die Grundlage für ein Gespräch.","coreRule":"⚡ Erst fragen, was ein Glaube leistet, dann prüfen, was er behauptet.","beleg":"Werkstück F.1.6 (Das Härten im Feuer: Schmiede-Übung; Anwendung & Relevanz: Lektion in Demut; Red Flags)","status":"entwurf","kurz":"Wer ein Gespräch will, fragt, welches Bedürfnis der Glaube seit dem Tod ihres Mannes erfüllt. Klugheit schützt nicht vor Selbsttäuschung, wenn ein Wunsch im Spiel ist, und weitere Gegenbeweise prallen an immer neuen Begründungen ab.","prueffrage":"Wendet sie ihre kritische Schärfe, die sie sonst zeigt, auch auf die Botschaften des Mediums an?","rueckmeldung":[{"option":0,"text":"Die Widersprüche sind real, und sie zu sammeln wirkt gründlich. Genau damit hat sie aber bisher Erfahrung: Für jeden fand sie eine neue Begründung, ein ganzer Stapel wirkt eher wie ein Angriff als wie Hilfe."},{"option":1,"text":"Rückhalt durch mehrere Menschen kann Mut machen, hier erzeugt er aber Druck und genau die Überheblichkeit, die du vermeiden willst. Dazu kommt: Das Bedürfnis dahinter bleibt unberührt, und davon hängt ab, ob ihre Prüfung aussetzt."},{"option":3,"text":"Rücksicht in der Trauer ist ein guter Anlass, und niemand muss sofort Kritik üben. Schweigen heißt aber, auf jede Hilfe zu verzichten: Zuhören und nach dem Bedürfnis fragen verletzen sie nicht, sondern öffnen das Gespräch."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahan, D. M. u. a. (2013): Motivated Numeracy and Enlightened Self-Government (Working Paper)","oeffentlich":true,"url":"https://scholarsbank.uoregon.edu/items/e034d504-ed17-4e0c-a713-ac3f85a8187a/full","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"02e0ab722a352b24"}},{"id":"qx-f-032","clusterId":"F","werkstueckRef":"F.1.7","stufe":1,"question":"In einer Diskussion sagt jemand: „Eine Taschenuhr hat offensichtlich einen Uhrmacher. Lebewesen sind noch viel komplexer, also muss es auch für sie einen Designer geben.“ Welcher Einwand trifft den Schwachpunkt dieses Vergleichs am besten?","options":["Eine Uhr wird in einer einzigen Herstellungsphase fertig gebaut, Lebewesen entstehen dagegen über lange Zeiträume schrittweise durch Variation und Selektion; der Vergleich überträgt also die Entstehungsweise eines Objekts auf einen ganz anders ablaufenden Prozess.","Eine Uhr besteht aus Metall, Lebewesen bestehen dagegen aus organischen Stoffen; wer beide vergleicht, mischt also zwei Materialklassen, die sich grundsätzlich nicht gegenüberstellen lassen.","Eine Uhr erfüllt erkennbar einen Zweck, Lebewesen dagegen nicht; wer ihnen eine Funktion zuschreibt, deutet also menschliche Absichten in die Natur hinein, die dort gar nicht vorkommen.","Eine Uhr braucht einen Hersteller, weil sie eine Ursache haben muss; Lebewesen sind dagegen unverursacht und entstehen aus reinem Zufall, ohne dass irgendein Mechanismus wirkt."],"correctIndex":0,"explanation":"Eine Analogie trägt nur so weit, wie die verglichenen Dinge in dem Punkt übereinstimmen, auf den der Schluss sich stützt. Hier ist der entscheidende Punkt die Entstehungsweise: Eine Taschenuhr könnte in ihrer heutigen Form nicht aus winzigen, funktionsfähigen Vorformen herauswachsen, sie wird in einer Herstellungsphase fertig gebaut. Lebewesen entstehen dagegen über viele Generationen, weil zufällige Mutationen auftreten und die Selektion nicht-zufällig diejenigen bevorzugt, die sich besser fortpflanzen. Teilstrukturen können dabei zunächst andere Vorteile bieten und später in neue Funktionen eingebunden werden (Exaptation). Der Uhrmacher-Schluss setzt also stillschweigend voraus, dass Komplexität nur durch fertige Planung entsteht, und genau das ist der unbelegte Schritt. Die anderen Einwände greifen daneben: Der Materialunterschied ist für den Schluss unerheblich, Funktionen lassen sich an Organen sehr wohl feststellen, und Evolution ist gerade nicht reiner Zufall, denn Selektion ist nicht zufällig.","coreRule":"⚡ Prüfe bei jeder Analogie, ob die verglichenen Dinge in dem Punkt übereinstimmen, auf den der Schluss sich stützt.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 4; Abschnitt „Die Uhr im Garten“); Fn. gl-f-8 nur für Paleys Uhr-Analogie (Paley 1802, Kap. 1 und 3)","status":"entwurf","scenario":"","kurz":"Der Vergleich trägt nur, wenn Uhr und Lebewesen auf gleiche Weise entstehen: Eine Uhr wird fertig gebaut, Lebewesen haben sich über viele Generationen schrittweise entwickelt. Dass Komplexität nur durch Planung entstehen kann, setzt der Schluss stillschweigend voraus.","prueffrage":"Woran erkennt man bei einer Taschenuhr, dass ein Uhrmacher sie gebaut hat, und trifft dasselbe auf eine Katze zu?","rueckmeldung":[{"option":1,"text":"Metall und organische Stoffe unterscheiden sich tatsächlich, nur hängt der Schluss nicht am Material. Entscheidend ist, wie etwas entsteht, und dazu sagt der Stoffunterschied nichts. Verglichen werden kann auch über Materialgrenzen hinweg."},{"option":2,"text":"Wer Funktionen in der Natur sieht, deutet leicht Absichten hinein, das ist eine bekannte Gefahr. Die Funktion eines Organs lässt sich aber feststellen, und die Selektion erklärt sie ohne Absicht. Das Problem des Vergleichs liegt woanders."},{"option":3,"text":"Mutationen sind zwar zufällig, die Selektion ist es nicht: Sie bevorzugt, wer sich besser fortpflanzt. Von „unverursacht“ kann also keine Rede sein. Der Vergleich scheitert nicht an fehlender Ursache, sondern an der Art der Entstehung."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kitzmiller v. Dover Area School District, Memorandum Opinion vom 20.12.2005","oeffentlich":true,"url":"https://www.pamd.uscourts.gov/sites/pamd/files/opinions/04v2688d.pdf","seite":"S. 74–75, 80–81","abruf":"2026-10-12"},{"typ":"url","kurz":"University of California Museum of Paleontology: Understanding Evolution, „Misconceptions about evolution“","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"cdefbcd858d890be"}},{"id":"qx-f-033","clusterId":"F","werkstueckRef":"F.1.7","stufe":2,"question":"Was ist an der Aussage sachlich falsch?","scenario":"Ein Mitschüler behauptet im Biologieunterricht: „Evolution ist doch reiner Zufall. So etwas Komplexes wie ein Auge kann nicht zufällig entstehen.“ Du willst herausfinden, ob die Behauptung überhaupt auf den tatsächlichen Mechanismus zielt.","options":["Er verwechselt Evolution mit der Entstehung des ersten Lebens: Wie die erste Zelle entstand, ist eine andere Frage als die Entwicklung der Arten und ihrer Augen danach.","Er verwechselt Evolution mit der Entwicklung einzelner Lebewesen: Nicht einzelne Individuen entwickeln sich im evolutionären Sinn, sondern Populationen über viele Generationen.","Er setzt Evolution mit Zufall gleich: Zufällige Mutationen treffen auf eine nicht-zufällige Auslese, die vorteilhafte Veränderungen über viele Generationen anhäuft.","Er verwechselt Evolution mit einem Wettlauf zu immer größerer Komplexität: Die Auslese begünstigt, was in der jeweiligen Umwelt besser zurechtkommt, nicht, was komplexer ist."],"correctIndex":2,"explanation":"Der Fehler liegt in der Gleichsetzung von „Evolution“ mit „Zufall“. Der Prozess kombiniert zwei Teile: zufällige Mutation und nicht-zufällige Selektion. Natürliche Selektion filtert aus unzähligen Mutationen beständig diejenigen heraus, die den Fortpflanzungserfolg steigern. Über Millionen von Generationen entstehen so komplexe Anpassungen, ohne dass ein bewusster Designer nötig wäre. Biologische Systeme entstehen über lange Zeiträume und vielfältige Zwischenstufen, nicht in einem einzigen Schritt. Wer die Frage stellt, wie wahrscheinlich es ist, dass ein Auge rein zufällig entsteht, bekämpft daher ein Zerrbild der Evolution.","coreRule":"⚡ Mutation würfelt, Selektion sortiert: Das Ergebnis ist alles andere als Zufall.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 2: Zufällige Mutation, nicht-zufällige Selektion)","status":"entwurf","kurz":"Evolution ist nicht reiner Zufall: Mutationen sind zufällig, die Selektion danach ist es nicht, und sie sammelt über viele Generationen und Zwischenstufen Vorteilhaftes an. Wer fragt, wie wahrscheinlich ein Auge rein zufällig entsteht, bekämpft ein Zerrbild.","prueffrage":"Hat ein Tier mit einer schädlichen Veränderung dieselben Chancen auf Nachwuchs wie eines mit einer nützlichen?","rueckmeldung":[{"option":0,"text":"Die Unterscheidung stimmt: Die Entstehung der ersten Zelle ist eine eigene Frage. Der Mitschüler spricht aber vom Auge, also von dem, was danach kam, und genau dort liegt sein Fehler nicht."},{"option":1,"text":"Dass sich Populationen und nicht einzelne Lebewesen entwickeln, trifft zu. Über einzelne Individuen sagt der Mitschüler aber nichts, sein Denkfehler liegt an anderer Stelle: bei der Rolle des Zufalls."},{"option":3,"text":"Selektion zielt tatsächlich nicht auf mehr Komplexität. Der Mitschüler unterstellt aber auch kein Ziel, er behauptet Zufall. Damit trifft dieser Einwand eine andere Aussage als die gemachte."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"University of California Museum of Paleontology: Understanding Evolution, „Misconceptions about evolution“ (Abschnitt „Evolution happens by chance“)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"5947fb24b1ef6019"}},{"id":"qx-f-034","clusterId":"F","werkstueckRef":"F.1.7","stufe":3,"question":"Ein Podiumsredner sagt: „Wissenschaftliche Methodik hin oder her – ob eine Idee in den Biologieunterricht gehört, ist reine Geschmacksfrage. Wir stellen einfach beide Erklärungen gleichwertig nebeneinander und lassen die Schüler entscheiden.“ Die Idee, um die es geht: Bestimmte Strukturen seien so komplex, dass ein bewusster Designer sie geplant haben müsse. Welche Prüffrage trifft den Kern, ob die Idee als gleichwertige wissenschaftliche Alternative in den Lehrplan gehört?","options":["Sagt die Idee eines planenden Designers etwas voraus, das sich beobachten oder widerlegen lässt, und wurden ihre prüfbaren Teilbehauptungen getestet?","Wer finanziert die Verbreitung der Designer-Idee, und welche Interessen verfolgen die Geldgeber damit, dass sie im Biologieunterricht vorkommt?","Fördert das gleichwertige Nebeneinander beider Erklärungen im Biologieunterricht das selbstständige Urteilen der Schüler besser als eine einzige Erklärung?","Lässt sich die Designer-Idee Schülern in einer Unterrichtsstunde verständlich und anschaulich erklären, ohne dass sie von den Beispielen überfordert sind?"],"correctIndex":0,"explanation":"Ob etwas gleichwertige Wissenschaft ist, entscheidet die Prüfbarkeit. Eine Hypothese, die jeden Befund als weiteren Beleg deutet, ist nicht falsifizierbar, und die Beweislast liegt bei dem, der sie vorbringt. Prüfbar ist beim Designer-Argument nur die Teilbehauptung, bestimmte Strukturen seien „irreduzibel komplex“, also ohne jedes einzelne Teil nutzlos – und sie wurde geprüft: Beim bakteriellen Flagellum entspricht ein Teil der Bauteile denen des Typ-III-Sekretionssystems, das für sich allein voll funktionsfähig ist. Ein US-Bundesgericht urteilte 2005 im Fall Dover: Intelligent Design sei keine Wissenschaft und lasse sich von seinen kreationistischen Wurzeln nicht trennen; der Schulbezirk durfte es deshalb nicht im Biologieunterricht vorstellen lassen. Maßgeblich ist, ob die Idee prüfbar und damit wissenschaftlich ist. Wer die Verbreitung finanziert, zeigt Interessen, aber nicht, ob sich die Idee prüfen lässt. Ob ein Nebeneinander das Urteilen fördert, ist eine pädagogische Frage, die erst nach der Klärung des wissenschaftlichen Status zählt. Wie anschaulich sich die Idee erklären lässt, sagt nichts darüber, ob sie sich testen lässt.","coreRule":"⚡ Ob eine Idee als Wissenschaft gleichwertig neben anderen steht, entscheidet ihre Prüfbarkeit – nicht Beliebtheit, Weltbild-Verträglichkeit oder Lautstärke ihrer Vertreter.","beleg":"Werkstück F.1.7 (Anwendung & aktuelle Bedeutung, Wissenschaftspolitik; Der Kipppunkt); Fn. gl-f-kitzmiller (Kitzmiller v. Dover, 20.12.2005, S. 28 f., 64 und 136)","status":"entwurf","scenario":"","kurz":"Ob die Idee gleichwertig neben die Biologie gehört, hängt an ihrer Prüfbarkeit. Naheliegend ist, nach Geschmack oder Nutzen zu fragen, doch gerade die prüfbare Teilbehauptung der „irreduziblen Komplexität“ wurde getestet, etwa am Flagellum.","prueffrage":"Woran sollen die Schüler nach dem Vorschlag des Redners erkennen, welche der beiden Erklärungen zutrifft?","rueckmeldung":[{"option":1,"text":"Die Frage nach Geldgebern ist als Quellenprüfung sinnvoll und kann Motive offenlegen. Ob sich die Idee testen lässt, beantwortet sie aber nicht: Auch eine finanzierte Idee kann prüfbar sein, eine uneigennützige unprüfbar."},{"option":2,"text":"Wie sich das Urteilen der Schüler am besten fördern lässt, ist eine echte pädagogische Frage. Sie setzt aber schon voraus, dass beide Erklärungen gleichwertig sind, und genau das ist offen. Erst der wissenschaftliche Status entscheidet."},{"option":3,"text":"Eine Idee kann sich leicht und anschaulich erklären lassen und trotzdem nicht prüfbar sein. Verständlichkeit macht sie nicht wissenschaftlich; sie sagt nichts darüber, ob sich die Idee testen oder widerlegen lässt."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Kitzmiller v. Dover Area School District, Memorandum Opinion vom 20.12.2005","oeffentlich":true,"url":"https://www.pamd.uscourts.gov/sites/pamd/files/opinions/04v2688d.pdf","seite":"S. 64, 76–77, 136","abruf":"2026-10-12"},{"typ":"url","kurz":"Thornton, S.: Karl Popper, Stanford Encyclopedia of Philosophy (Abschn. 2–3, Falsifizierbarkeit)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"fef615f2118f406a"}},{"id":"qx-f-035","clusterId":"F","werkstueckRef":"F.1.7","stufe":4,"question":"Eine Verteidigerin einer Theorie sagt: „Findet man in den Gesteinsschichten eine Zwischenform, ist das ein Beleg für meine Theorie; findet man keine, ist es ebenfalls ein Beleg.“ Wo liegt das methodische Problem?","options":["Die Verteidigerin nennt nur die Schichten mit Zwischenform als Beleg und übergeht die Schichten ohne Fund (Rosinenpickerei).","Die Verteidigerin stützt sich darauf, dass die Theorie in der Fachwelt breit anerkannt ist, statt auf die Funde (Autoritätsargument).","Die Verteidigerin zeichnet die Einwände ihrer Kritiker verzerrt nach, damit Fund und Nichtfund als Beleg erscheinen (Strohmann-Argument).","Die Verteidigerin wertet Fund und Nichtfund als Bestätigung; die Theorie sagt nichts voraus und kann nie scheitern (Immunisierung)."],"correctIndex":3,"explanation":"Eine Theorie, die sowohl den Fund als auch das Ausbleiben des Funds als Bestätigung verbucht, schließt keinen denkbaren Befund aus. Damit kann nichts sie widerlegen, und gerade deshalb prüft nichts sie. Wissenschaftliche Modelle sagen dagegen etwas voraus, das auch scheitern könnte: „Wenn die Theorie stimmt, dürfen wir X nicht finden.“ Wer jeden Ausgang als Treffer wertet, erklärt scheinbar alles, in Wahrheit aber nichts. Das Gegenmittel ist die Frage: „Welcher Befund würde dich umstimmen?“ Gibt es keinen, ist die Behauptung nicht prüfbar. Die anderen Deutungen nennen bekannte Fehler, passen aber nicht auf diesen Satz. Rosinenpickerei läge vor, wenn nur die passenden Funde zählten, sie wertet aber gerade beide Ausgänge, Fund wie Nichtfund. Auf Ansehen beruft sie sich nicht, sie bezieht sich auf Funde. Und von Kritikern oder deren Einwänden ist im Satz keine Rede, sodass nichts verzerrt dargestellt wird.","coreRule":"⚡ Wer jeden Befund erklären kann, erklärt nichts: Ein prüfbares Modell muss etwas ausschließen.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 3: Beweislast und Falsifizierbarkeit; Red Flags)","status":"entwurf","scenario":"","kurz":"Wer Fund und Nichtfund gleichermaßen als Beleg wertet, schließt keinen Befund aus; die Theorie sagt nichts voraus und kann nie scheitern. Gerade deshalb prüft nichts sie, auch wenn sie scheinbar alles erklärt.","prueffrage":"Was weißt du nach ihrer Aussage über die Gesteinsschichten, das du vorher noch nicht wusstest?","rueckmeldung":[{"option":0,"text":"Rosinenpickerei klingt passend, weil es um den Umgang mit Befunden geht. Hier wird aber nichts übergangen: Fund wie Nichtfund zählen beide als Beleg. Das Problem ist, dass jeder Ausgang zählt."},{"option":1,"text":"Dass die Theorie breit anerkannt sei, steht im Satz nirgends. Die Verteidigerin bezieht sich auf Funde, nicht auf Ansehen. Das Problem liegt darin, wie sie Funde auswertet, nicht in einer Berufung auf Autorität."},{"option":2,"text":"Von Kritikern oder deren Einwänden ist im Satz keine Rede, also wird auch nichts verzerrt nachgezeichnet. Der Strohmann ist ein bekannter Fehler, passt aber nicht auf diese Aussage über Fund und Nichtfund."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (Abschn. 2 „Backdrop to Popper's Thought“, Abschn. 3 „The Problem of Demarcation“)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"77836866856bdf81"}},{"id":"qx-f-036","clusterId":"F","werkstueckRef":"F.2.1","stufe":1,"question":"Welche Prüfung zeigt am besten, ob die Aussage wirklich etwas Besonderes über deine Freundin verrät?","scenario":"Eine Freundin liest dir aus ihrem Tageshoroskop vor: „Du hast ein kreatives Potenzial, das noch nicht voll ausgeschöpft ist.“ Sie ist begeistert: „Das trifft genau auf mich zu! Das kann doch kein Zufall sein.“ Du willst herausfinden, ob die Aussage wirklich etwas über sie verrät.","options":["Fragen, ob dieselbe Aussage auch auf andere Menschen zutreffen würde, etwa auf ihre Kollegen und Nachbarn.","Prüfen, ob das Horoskop aus einer seriösen Quelle stammt und seine Autoren und Methoden offenlegt.","Klären, ob sie sich nur an die Treffer früherer Horoskope erinnert und die Fehlschläge längst vergessen hat.","Klären, ob deine Freundin ohnehin an Horoskope glaubt und deshalb eher einen Treffer in der Aussage sieht."],"correctIndex":0,"explanation":"Eine Aussage verrät nur dann etwas über eine bestimmte Person, wenn sie auf diese Person besser passt als auf andere. „Du hast ein kreatives Potenzial, das noch nicht voll ausgeschöpft ist“ ist eine typische Barnum-Aussage: vage, schmeichelhaft und universell genug, dass jeder sich darin wiedererkennt. Solche Sätze fühlen sich persönlich an, sind es aber nicht. Das Gefühl der Treffsicherheit ist deshalb kein Beleg. Entscheidend ist, ob die Aussage auch auf andere zutrifft. Die Herkunft des Horoskops ist eine berechtigte Frage der Quellenkritik, sagt aber nichts darüber, ob dieser eine Satz auf deine Freundin besser passt als auf andere. Die Erinnerung an frühere Treffer ist ein bekannter Fehler, betrifft hier aber nicht die vorgelesene Aussage, die sie gerade zum ersten Mal hört. Dass sie an Horoskope glaubt, erklärt ihre Begeisterung, zeigt aber nicht, ob die Aussage etwas über sie verrät.","coreRule":"⚡ Passt eine Aussage auf alle, sagt sie über niemanden etwas: Prüfe, ob sie auch auf andere zutreffen würde.","beleg":"Werkstück F.2.1 (Die Anatomie der Täuschung: Barnum-Effekt, B.10)","status":"entwurf","kurz":"Der Satz sagt nur dann etwas über deine Freundin, wenn er auf sie besser passt als auf andere. Er ist vage und schmeichelhaft genug, dass sich fast jeder darin wiedererkennt, und das Gefühl, er treffe genau, ist deshalb kein Beleg.","prueffrage":"Wer in deinem Bekanntenkreis würde von sich sagen, sein kreatives Potenzial sei schon voll ausgeschöpft?","rueckmeldung":[{"option":1,"text":"Nach der Herkunft zu fragen ist eine berechtigte Frage der Quellenkritik. Sie klärt aber nur, wer den Satz geschrieben hat, nicht, ob er auf deine Freundin besser passt als auf andere."},{"option":2,"text":"Selektive Erinnerung an Treffer ist ein bekannter Fehler und kann bei Horoskopen eine Rolle spielen. Hier geht es aber um einen Satz, den sie gerade zum ersten Mal hört, nicht um frühere Vorhersagen."},{"option":3,"text":"Ein Glaube an Horoskope könnte ihre Begeisterung erklären, denn wer etwas erwartet, sieht eher einen Treffer. Ob der Satz selbst etwas über sie verrät, bleibt damit aber offen: Das zeigt nur der Vergleich mit anderen."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: The Skeptic's Dictionary, Art. „Forer effect“","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Forer, B. R. (1949): The fallacy of personal validation: a classroom demonstration of gullibility. Journal of Abnormal and Social Psychology 44(1), S. 118 ff.","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d87b8bed81f1019c"}},{"id":"qx-f-037","clusterId":"F","werkstueckRef":"F.2.1","stufe":2,"question":"Ein Astrologe behauptet: „Die Schwerkraft der Planeten prägt den Charakter eines Menschen bei der Geburt.“ Welcher Einwand trifft diese Behauptung am stärksten?","options":["Ein Körper im selben Raum, etwa der Geburtshelfer, zieht das Neugeborene ähnlich stark oder stärker an als der Mars. Wäre Schwerkraft der Mechanismus, bestimmte der Geburtshelfer das Horoskop mit.","Das Licht der Fixsterne ist bei der Geburt viel zu schwach, um messbar auf ein Neugeborenes zu wirken. Eine Prägung des Charakters durch Sternenstrahlung ist deshalb nicht plausibel.","Die Sternbilder des Tierkreises haben sich seit der Antike durch die Präzession verschoben. Die heutigen Tierkreiszeichen passen deshalb nicht mehr zu den Sternbildern am Himmel.","Die Sterne eines Sternbilds liegen weit auseinander und gehören nur aus Sicht der Erde zusammen. Ein Sternbild bildet deshalb keine reale Einheit, die einen Charakter prägen könnte."],"correctIndex":0,"explanation":"Der Einwand prüft, ob die behauptete Ursache überhaupt ausreicht: Die Anziehung des Geburtshelfers neben der Mutter liegt je nach Marsstellung und Abstand in derselben Größenordnung wie die des Planeten oder deutlich darüber, und seine Gezeitenwirkung übertrifft die des Mars um viele Größenordnungen. Wäre Schwerkraft der Mechanismus, müsste das Horoskop also mindestens ebenso vom Geburtshelfer abhängen wie vom Planeten. Das ist offensichtlich nicht gemeint, also taugt die Schwerkraft nicht als Erklärung. Das schwache Licht der Fixsterne ist zutreffend, betrifft aber nicht die Schwerkraft der Planeten, auf die sich der Astrologe beruft. Die Verschiebung der Sternbilder ist real, betrifft aber die Zuordnung der Zeichen und nicht die Frage, ob Schwerkraft als Ursache reicht. Dass die Sterne eines Sternbilds nur scheinbar zusammengehören, ist eine berechtigte Kritik an den Sternbildern, sagt aber nichts über die Schwerkraft der Planeten.","coreRule":"⚡ Eine behauptete Ursache muss stärker sein als naheliegende Alternativen im selben Raum. Sonst taugt sie nicht als Erklärung.","beleg":"Werkstück F.2.1 (Die Konfrontation mit der Realität: Verletzung der Physik)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Wenn Schwerkraft der Mechanismus wäre, müsste der Geburtshelfer im Raum das Horoskop mindestens ebenso mitbestimmen wie der ferne Mars. Das ist offensichtlich nicht gemeint, also reicht die behauptete Ursache nicht aus. Die Stärke der Wirkung wird gar nicht geprüft.","prueffrage":"Wovon hängt ab, wie stark ein Körper ein Neugeborenes anzieht, und wie ändert sich das mit der Entfernung?","rueckmeldung":[{"option":1,"text":"Dass Fixsternlicht bei der Geburt kaum etwas bewirkt, stimmt. Die Behauptung beruft sich aber auf die Schwerkraft der Planeten, nicht auf Sternenlicht. Der Einwand trifft also einen anderen Mechanismus als den genannten."},{"option":2,"text":"Die Verschiebung der Sternbilder durch die Präzession ist real, betrifft aber die Zuordnung der Zeichen zu den Sternbildern. Ob Schwerkraft überhaupt als Ursache ausreicht, bleibt dabei unberührt."},{"option":3,"text":"Die Sterne eines Sternbilds gehören tatsächlich nur aus Sicht der Erde zusammen, das ist eine berechtigte Kritik an Sternbildern. Die Behauptung spricht aber von den Planeten und ihrer Schwerkraft, nicht von Sternbildern."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Universe Today: „Debunking Astrology: Mars Can't Influence You“","oeffentlich":true,"url":"https://universetoday.com/articles/debunking-astrology-mars-cant-influence-you","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"cbe390c606412098"}},{"id":"qx-f-038","clusterId":"F","werkstueckRef":"F.2.1","stufe":3,"question":"Du kritisierst: „Wegen der Präzession passt dein Sternzeichen nicht mehr zu dem Sternbild, in dem die Sonne bei deiner Geburt tatsächlich stand.“ Ein Astrologe entgegnet: „Mein Tierkreis richtet sich bewusst nach den Jahreszeiten, gezählt ab dem Frühlingsanfang, nicht nach den Sternbildern.“ Wie bewertest du diese Antwort?","options":["Sie beantwortet den Einwand, aber dann deutet die Astrologie streng genommen nicht mehr die Sterne, sondern nur noch den Kalender der Jahreszeiten.","Sie weicht nur aus, denn die Präzession verschiebt auch den Frühlingspunkt, sodass die Zählung ab Frühlingsanfang denselben Fehler hat.","Sie entkräftet den Einwand restlos, denn Jahreszeiten und Sternbilder verschieben sich gleich schnell, sodass die Zeichen den Sternen treu bleiben.","Sie ist ein Zirkelschluss, denn sie begründet die Bindung an den Frühlingsanfang mit einer Wirkung der Zeichen, die erst bewiesen werden müsste."],"correctIndex":0,"explanation":"Die Verteidigung ist in sich stimmig: Ein tropischer Tierkreis wird von Frühlingspunkt zu Frühlingspunkt gezählt und ist damit an die Jahreszeiten gebunden, nicht an die Sternbilder. Der Einwand der Präzession trifft ihn deshalb nicht. Aber die Antwort hat einen Preis: Wenn sich die Zeichen nach dem Kalender richten, ordnet die Astrologie Menschen nach dem Datum und nicht nach der Stellung der Himmelskörper. Damit fällt auch die Behauptung, die Sterne selbst hätten einen Einfluss. Eine Verteidigung, die den ursprünglichen Gegenstand aufgibt, hat den Streitpunkt nicht gewonnen, sondern verlagert. Die anderen Antworten klingen sinnvoll, scheitern aber an Einzelheiten. Dass die Präzession auch den Frühlingspunkt verschiebt, stimmt, doch der tropische Tierkreis ist per Definition an ihn gebunden und behauptet keine Übereinstimmung mit den Sternbildern. Jahreszeiten und Sternbilder verschieben sich gerade nicht gleich schnell, das ist der Kern der Präzession, die Zeichen bleiben den Sternen also nicht treu. Ein Zirkelschluss liegt nicht vor, denn die Bindung an den Frühlingsanfang ist eine Festlegung der Zählweise und keine Begründung durch eine Wirkung der Zeichen.","coreRule":"⚡ Wer den Himmel gegen den Kalender tauscht, hat die Sterne aus der Astrologie gestrichen.","beleg":"Werkstück F.2.1 (Verletzung der Astronomie); Fn. gl-f-tropisch (Carroll 2003, Skeptic's Dictionary, Art. astrology)","status":"entwurf","scenario":"Du diskutierst mit einem Astrologen über die Verschiebung der Sternbilder seit der Antike.","quote":"","quoteLabel":"","kurz":"Der tropische Tierkreis ist an die Jahreszeiten gebunden, der Einwand der Präzession trifft ihn also nicht. Der Preis: Dann zählt das Datum und nicht mehr die Stellung der Sterne, der Streitpunkt ist verlagert, nicht gewonnen.","prueffrage":"Welches Zeichen hätte nach diesem Tierkreis jemand, der heute am selben Kalendertag geboren wird wie jemand vor 2000 Jahren?","rueckmeldung":[{"option":1,"text":"Dass die Präzession auch den Frühlingspunkt verschiebt, stimmt. Der tropische Tierkreis ist aber per Definition an diesen Punkt gebunden und behauptet gar keine Übereinstimmung mit den Sternbildern, deshalb steckt in seiner Zählung kein Fehler."},{"option":2,"text":"Jahreszeiten und Sternbilder verschieben sich gerade nicht gleich schnell, das ist der Kern der Präzession. Die Zeichen bleiben den Sternen daher nicht treu, und die Antwort rettet den Anspruch auf Sterneinfluss ohnehin nicht."},{"option":3,"text":"Die Bindung an den Frühlingsanfang klingt nach einer Begründung durch die Wirkung der Zeichen. Sie ist aber nur eine Festlegung der Zählweise, und eine Festlegung beweist nichts. Ein Zirkelschluss liegt deshalb nicht vor."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Carroll, R. T.: The Skeptic's Dictionary, Art. „astrology“","oeffentlich":true,"url":"https://skepdic.com/astrology.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"87df423d89781f3f"}},{"id":"qx-f-039","clusterId":"F","werkstueckRef":"F.2.1","stufe":4,"question":"Welche Testanordnung prüft die Behauptung der Astrologin am fairsten?","options":["Die Astrologin ordnet Horoskope den Persönlichkeitsprofilen zu, und die Testleitung, die die richtigen Zuordnungen kennt, begleitet den Ablauf nur beobachtend.","Die Astrologin ordnet Horoskope den Persönlichkeitsprofilen zu, und was als Treffer zählt, legt man erst nach Sicht der Ergebnisse gemeinsam mit ihr fest.","Die Astrologin deutet Horoskope von zufällig ausgewählten Freiwilligen, und diese bewerten anonym, wie gut die Deutung zu ihnen passt.","Die Astrologin ordnet Horoskope den passenden Persönlichkeitsprofilen zu, und weder sie noch die Testleitung wissen währenddessen, welche Zuordnung richtig ist."],"correctIndex":3,"explanation":"Ein fairer Test muss ausschließen, dass etwas anderes als das Horoskop die Treffer erzeugt. Im Doppelblindtest kennt niemand die Lösung, sodass Erwartung und Vorwissen ausscheiden und nur zählt, ob mehr als der Zufall herauskommt. Genau so ein Test fand statt: Carlson ließ Astrologen Horoskope den passenden Persönlichkeitsprofilen zuordnen, und die Trefferquote betrug 0,34 bei einer Zufallsquote von 0,33. Ein anderer Test mit „Zeitzwillingen“ (gut 2.000 Londoner, geboren im März 1958) zeigte ebenfalls keine Ähnlichkeit über den Zufall hinaus: Sie ähnelten ihren Zeitzwillingen in Intelligenz, Verhalten und Körpermerkmalen nicht stärker als beliebigen anderen Menschen.","coreRule":"⚡ Fair testen heißt blind testen: Wer Vorwissen oder Bewertung in der Hand hat, misst seine Erwartung, nicht die Behauptung.","beleg":"Werkstück F.2.1 (Das Zwillings-Problem); Fn. gl-f-astrotests (Carlson 1985, Nature 318, S. 419--425; Dean, Kelly 2003)","status":"entwurf","scenario":"Eine Astrologin behauptet: „Ich erkenne den Charakter eines Menschen an seinem Horoskop, auch wenn ich ihn nie getroffen habe.“ Ein Skeptiker will das prüfen, ohne dass das Ergebnis durch Erwartungen, Vorwissen oder Wohlwollen verzerrt wird. Er schlägt vier Testanordnungen vor.","kurz":"Nur wenn weder die Astrologin noch die Testleitung die Lösung kennen, kann nichts außer dem Horoskop die Treffer erzeugen, und es zählt, ob sie über den Zufall hinausgehen. Wer die Lösung kennt, kann unbewusst Hinweise geben.","prueffrage":"Woher könnte in jeder der vier Anordnungen ein Treffer kommen, wenn Horoskope gar nichts über den Charakter verraten?","rueckmeldung":[{"option":0,"text":"Rein beobachtend zu bleiben klingt neutral, und die Zuordnung ist die richtige Aufgabe. Wer die Lösung kennt, kann sie aber unbewusst verraten, etwa durch Mimik oder Zögern. Dann ist es kein echter Doppelblindtest."},{"option":1,"text":"Die Astrologin einzubeziehen wirkt entgegenkommend, und die Zuordnungsaufgabe ist sinnvoll. Legt man den Treffer erst nach Sicht der Ergebnisse fest, lässt sich fast jedes Resultat als Erfolg deuten. Das begünstigt den Bestätigungsfehler. Kriterien müssen vorher feststehen."},{"option":2,"text":"Zufällige Auswahl und anonyme Bewertung wirken fair. Vage Deutungen werden aber fast immer als zutreffend empfunden (Barnum-Effekt), und es fehlt der Vergleich mit dem Zufall. Gemessen wird so eher die Vagheit der Deutung als ihre Treffsicherheit."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Carlson, S. (1985): A double-blind test of astrology. Nature 318, S. 419–425","oeffentlich":false,"doi":"10.1038/318419a0"},{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is Astrology Relevant to Consciousness and Psi? (Webfassung)","oeffentlich":true,"url":"https://www.astrology-and-science.com/D-psia2.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"2be1b2d6ddce1aea"}},{"id":"qx-f-040","clusterId":"F","werkstueckRef":"F.2.2","stufe":1,"question":"Welche Frage prüft die Behauptung „Je stärker verdünnt und geschüttelt, desto stärker die Wirkung“ am besten auf Plausibilität?","options":["Wie viel von der Ausgangssubstanz steckt bei C30 noch im Fläschchen, und wodurch soll dann eine Wirkung entstehen?","Wer hat das C30-Fläschchen hergestellt, und verdient er daran, dass Käufer glauben, stärkere Verdünnung wirke stärker?","Entspricht die Aufschrift C30 der tatsächlich durchgeführten Verdünnungsreihe, und wurde bei jedem Schritt vorschriftsmäßig geschüttelt?","Welche Nebenwirkungen sind für das C30-Mittel bekannt, und für welche Personen wäre die Einnahme gefährlich oder ungeeignet?"],"correctIndex":0,"explanation":"Eine Wirkbehauptung prüft man zuerst an ihrem Mechanismus: Soll eine Substanz wirken, muss sie in der Lösung auch vorhanden sein. Bei C30 beträgt der Verdünnungsfaktor 10^60; statistisch ist kein einziges Molekül der Ausgangssubstanz mehr zu erwarten, schon ab etwa C12 ist die Avogadro-Grenze überschritten. Außerdem beruht die Pharmakologie auf der Dosis-Wirkungs-Beziehung: Mehr Wirkstoff bewirkt mehr Wirkung (bis zu einem Sättigungs- oder Giftigkeitspunkt), nicht weniger. „Mehr Verdünnung, mehr Wirkung“ widerspricht dem und kommt ohne plausiblen Mechanismus aus. Die anderen Fragen klingen nach sorgfältiger Prüfung, beantworten aber etwas anderes. Wer das Mittel herstellt und was er verdient, ist eine berechtigte Frage der Quellenkritik, klärt aber nicht, ob eine Wirkung möglich ist. Ob die Aufschrift zur Herstellung passt, zeigt Produktqualität, nicht Wirksamkeit. Bekannte Nebenwirkungen betreffen die Sicherheit und sagen nichts darüber, ob die Behauptung physikalisch plausibel ist.","coreRule":"⚡ Prüfe bei jeder Wirkbehauptung zuerst den Mechanismus: Ist der behauptete Wirkstoff überhaupt vorhanden, und passt die Behauptung zur Dosis-Wirkungs-Beziehung?","beleg":"Werkstück F.2.2 (Die Kern-Behauptung); Fn. gl-f-9 (Hahnemann 1796, Hufelands Journal Bd. 2, S. 433)","status":"entwurf","scenario":"Ein Bekannter schwärmt von seinem Globuli-Fläschchen mit der Aufschrift C30. Er sagt: „Je mehr das Mittel verdünnt und geschüttelt wird, desto stärker wirkt es.“","kurz":"Eine Wirkbehauptung prüft man zuerst am Mechanismus: Bei C30 ist statistisch kein Molekül der Ausgangssubstanz mehr zu erwarten, und in der Pharmakologie wirkt mehr Wirkstoff stärker, nicht weniger. Wer nur Hersteller, Etikett oder Nebenwirkungen prüft, umgeht diese Kernfrage.","prueffrage":"Was würde mit der Wirkung einer Kopfschmerztablette geschehen, wenn man sie immer weiter mit Wasser verdünnt?","rueckmeldung":[{"option":1,"text":"Wer an einer Behauptung verdient, ist für die Quellenkritik tatsächlich interessant. Ob eine Wirkung überhaupt möglich ist, klärt das aber nicht: Auch ein Verkäufer mit Eigeninteresse kann recht haben oder unrecht, das entscheidet sich an der Sache."},{"option":2,"text":"Ein Mittel, das nicht zum Etikett passt, wäre ein Qualitätsproblem. Selbst bei korrekter Herstellung bliebe aber offen, ob bei dieser Verdünnung überhaupt eine Wirkung entstehen kann. Die Frage betrifft das Produkt, nicht die Plausibilität der Behauptung."},{"option":3,"text":"Nebenwirkungen und Risikogruppen betreffen die Sicherheit eines Mittels und sind wichtig, wenn man es einnimmt. Sie sagen aber nichts darüber, ob die Behauptung „stärker verdünnt, stärker wirksam“ überhaupt möglich ist."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"apotheken.de (Deutscher Apotheker Verlag): „Grundlagen der Homöopathie“ (nach Renz-Polster/Escher, Gesundheit heute)","oeffentlich":true,"url":"https://www.apotheken.de/sondertext/33c22-potenzierung","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), S. 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b63c081816af16c0"}},{"id":"qx-f-041","clusterId":"F","werkstueckRef":"F.2.2","stufe":2,"question":"Was kannst du ihr über den Inhalt des Fläschchens sagen?","scenario":"Eine Freundin schwärmt von ihren Globuli: „Auf dem Fläschchen steht C30, das sind hochwirksame Spuren des Heilstoffs, nur eben sehr fein dosiert.“ Auf dem Beipackzettel steht: Bei einer C-Potenz wird in jedem Schritt im Verhältnis 1 zu 100 verdünnt und verschüttelt, die Zahl gibt die Anzahl der Schritte an. Du weißt außerdem: Ab einer Gesamtverdünnung von etwa 10 hoch 24, das entspricht C12, ist statistisch kein einziges Molekül des Ausgangsstoffs mehr zu erwarten.","options":["Es sind feine Spuren enthalten: C30 steht für ein Verhältnis von eins zu dreißig, also steckt rund ein Dreißigstel der Ausgangsmenge in der Arznei.","Es sind feine Spuren enthalten: Jeder der 30 Schritte lässt ein Hundertstel übrig, und ein noch so kleiner Bruchteil einer Menge wird nie ganz null.","Es ist kein Molekül zu erwarten: 30 Schritte zu je 1 zu 100 ergeben 10 hoch 60, und das liegt weit jenseits der Grenze von 10 hoch 24 bei C12.","Es ist mehr enthalten als bei C12: Beim Verschütteln reichert sich der Stoff mit jedem Schritt an, sodass höhere Potenzen trotz Verdünnung dichter sind."],"correctIndex":2,"explanation":"C30 bedeutet 30 Schritte zu je 1 zu 100, also einen Verdünnungsfaktor von 100 hoch 30 = 10 hoch 60, nicht „eins zu dreißig“. Die Avogadro-Grenze liegt bei D24 bzw. C12: Ab dort ist statistisch kein Molekül der Ausgangssubstanz mehr zu erwarten (rechnerisch 0,6 Moleküle je Mol Endprodukt). C30 liegt weit jenseits dieser Grenze. Niedrigpotenzen wie D6 bis D12 enthalten noch Spuren des Ausgangsstoffs, Hochpotenzen wie C30 statistisch keines mehr; chemisch ist das Fläschchen Zucker und Wasser (Rademacher 2013). Die Lesart „eins zu dreißig“ übersieht, dass die Zahl die Schritte zählt und jeder Schritt durch 100 teilt. Ein Bruchteil wird rechnerisch zwar nie null, ein Stoff besteht aber aus einzelnen Molekülen, und ein winziger Bruchteil eines einzelnen Moleküls bleibt nicht im Fläschchen zurück. Dass die Konzentration beim Verschütteln wieder ansteigt, widerspricht der Arithmetik: Potenzieren bedeutet schrittweises Verdünnen, nicht Aufkonzentrieren.","coreRule":"⚡ Ab etwa C12 ist statistisch kein Wirkstoffmolekül mehr zu erwarten: Rechne die Verdünnung in Teilchen um, bevor du von „Spuren“ sprichst.","beleg":"Werkstück F.2.2 (Verletzung der Chemie); Fn. gl-f-tiefpotenzen (Rademacher 2013, S. 25--26); Fn. gl-f-10","status":"entwurf","kurz":"Die Zahl hinter C zählt Schritte, und jeder teilt durch 100: C30 ist ein Faktor von 10 hoch 60, weit jenseits der Grenze von 10 hoch 24, ab der statistisch kein Molekül mehr übrig ist. Wer „eins zu dreißig“ liest, übersieht das.","prueffrage":"Was genau zählt die Zahl hinter dem C, und um welchen Faktor wird bei jedem dieser Schritte verdünnt?","rueckmeldung":[{"option":0,"text":"Die Zahl hinter dem C wirkt wie ein Mengenverhältnis, daher liegt „eins zu dreißig“ nah. Laut Beipackzettel zählt sie aber Schritte, und jeder Schritt teilt durch 100. Das ergibt einen Faktor von 10 hoch 60, nicht ein Dreißigstel."},{"option":1,"text":"Richtig ist, dass jeder Schritt rechnerisch ein Hundertstel übrig lässt und ein Bruchteil nie ganz null wird. Ein Stoff besteht aber aus einzelnen Molekülen, und ab etwa C12 ist statistisch keines mehr zu erwarten. Bei C30 bleibt davon nichts übrig."},{"option":3,"text":"Jeder Schritt teilt durch 100, und Verschütteln fügt keinen Stoff hinzu. Eine höhere Potenz bedeutet deshalb stärkere Verdünnung und weniger Ausgangsstoff, nicht mehr. Aufkonzentrieren widerspricht der Rechnung auf dem Beipackzettel."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"apotheken.de (Deutscher Apotheker Verlag): „Grundlagen der Homöopathie“","oeffentlich":true,"url":"https://www.apotheken.de/sondertext/33c22-potenzierung","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), S. 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c0572d845f066fe2"}},{"id":"qx-f-042","clusterId":"F","werkstueckRef":"F.2.2","stufe":3,"question":"Was folgt aus diesem Muster am ehesten?","options":["Der Nutzen zeigt sich nur in den weniger sauberen Studien. Das spricht dafür, dass die positiven Ergebnisse auf Verzerrung beruhen und nicht auf einer echten Wirkung.","Alle Studien untersuchten nur Kinder, nicht Erwachsene. Das spricht dafür, dass die Ergebnisse nur für Kinder gelten und das Muster eine Besonderheit dieser Altersgruppe ist.","Ein nachweisbarer Unterschied muss nicht bedeutsam sein. Das spricht dafür, dass die positiven Studien zwar eine Wirkung zeigen, diese für Kinder aber kaum praktische Bedeutung hat.","Mit 1.813 Kindern ist die Datenbasis zu klein für gesicherte Aussagen. Das spricht dafür, dass das Muster erst mit deutlich mehr Studien belastbar wird."],"correctIndex":0,"explanation":"Entscheidend ist das Muster: Die Studien mit geringem Verzerrungsrisiko finden keinen Nutzen, positive Ergebnisse stammen ausschließlich aus Studien mit unklarem oder hohem Risiko. Genau das erwartet man, wenn es keine echte Wirkung gibt. Positive Ergebnisse entstehen dann durch Verzerrung im Studienaufbau, etwa durch fehlende Verblindung oder unsaubere Zuteilung, oder durch Zufall. Gäbe es eine echte Wirkung, müsste sie sich auch in den sauber durchgeführten Studien zeigen. Dieser Befund ist ein Beispiel dafür, wie man bei einem Evidenzkörper nicht nur zählt, wie viele Studien positiv ausfallen, sondern auch fragt, wie belastbar sie sind. Er gilt für diese Altersgruppe und diese Beschwerden und ersetzt keine ärztliche Beratung. Dass alle Studien Kinder betrafen, begrenzt, auf wen man das Ergebnis übertragen kann, erklärt aber nicht, warum die Ergebnisse nach Studienqualität und nicht nach Alter variieren. Ob ein Unterschied bedeutsam wäre, ist eine andere Frage; hier verschwindet der Nutzen bei sauberer Messung ganz. Zur Datenmenge sagt das Muster nichts: Es ergibt sich aus der Sortierung nach Studienqualität, nicht aus der Zahl der Kinder.","coreRule":"⚡ Wenn der Nutzen mit der Studienqualität verschwindet, spricht das gegen eine echte Wirkung.","beleg":"Werkstück F.2.2 (Abschluss-Diagnose); Fn. gl-f-homoeopathie-evidenz (Hawke u. a. 2022, Cochrane CD005974)","status":"entwurf","scenario":"Eine Übersichtsarbeit fasst elf Studien mit insgesamt 1.813 Kindern zusammen, die ein homöopathisches Mittel gegen akute Atemwegsinfekte testen. Die Autoren sortieren die Studien danach, wie anfällig ihr Aufbau für Verzerrungen ist (z. B. fehlende Verblindung oder unsaubere Zuteilung der Kinder auf die Gruppen). Dabei zeigt sich ein Muster: Alle Studien mit sauberem Aufbau finden keinen Nutzen. Positive Ergebnisse stammen ausschließlich aus Studien mit unklarem oder hohem Verzerrungsrisiko.","kurz":"Wenn der Nutzen nur dort auftaucht, wo der Aufbau Verzerrung zulässt, und bei sauberer Messung verschwindet, passt das zu einer Scheinwirkung. Eine echte Wirkung müsste sich auch in den sauberen Studien zeigen.","prueffrage":"Wie fallen die Ergebnisse aus, wenn du die Studien nach der Sauberkeit ihres Aufbaus ordnest, statt sie nur zu zählen?","rueckmeldung":[{"option":1,"text":"Dass alle Studien nur Kinder betrafen, begrenzt tatsächlich, auf wen sich das Ergebnis übertragen lässt. Das Muster verläuft aber nach Studienqualität, nicht nach Alter: Alle Studien hatten dieselbe Altersgruppe und trotzdem unterschiedliche Ergebnisse."},{"option":2,"text":"Ob ein Unterschied praktisch bedeutsam ist, ist eine berechtigte Frage, aber erst, wenn es einen echten Unterschied gibt. Hier verschwindet der Nutzen in den sauberen Studien ganz, die Wirkung ist also gar nicht belegt."},{"option":3,"text":"Eine kleine Datenbasis kann Aussagen tatsächlich unsicher machen. Das Muster hier ergibt sich aber aus der Sortierung nach Studienqualität, nicht aus der Zahl der Kinder. Mehr unsaubere Studien würden daran nichts ändern."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Hawke, K.; King, D.; van Driel, M. L.; McGuire, T. M. (2022): Homeopathic medicinal products for preventing and treating acute respiratory tract infections in children. Cochrane Database of Systematic Reviews, CD005974.pub6 (frei in PMC9746041)","oeffentlich":true,"doi":"10.1002/14651858.CD005974.pub6","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9746041/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ee2d2c3e7f1062d7"}},{"id":"qx-f-043","clusterId":"F","werkstueckRef":"F.2.2","stufe":4,"question":"Was ist an der Argumentation des Verkäufers der rhetorische Kniff?","scenario":"Ein Verkäufer sagt: „Dieses C200-Globuli heilt deine Lungenentzündung.“ Eine Ärztin wendet ein, dass in C200-Globuli kein einziges Molekül des Wirkstoffs mehr enthalten ist und es keinen Wirksamkeitsnachweis gibt. Der Verkäufer antwortet: „Naja, Homöopathie ist eben ganzheitlich und regt die Selbstheilungskräfte an.“","options":["Er begründet die Wirkung der Globuli mit der Wirkung der Globuli und setzt damit voraus, was er zeigen will.","Er unterstellt der Ärztin eine Behauptung, die sie nie aufgestellt hat, und widerlegt dann diese.","Er zieht sich unter Kritik von der kühnen Heilbehauptung auf eine bescheidene, kaum widerlegbare Aussage zurück.","Er greift die Person der Ärztin an, statt auf ihre sachlichen Einwände einzugehen."],"correctIndex":2,"explanation":"Zuerst steht eine mutige, überprüfbare Behauptung im Raum: Die Globuli heilen eine Lungenentzündung. Sobald Kritik kommt, wechselt der Verkäufer zu einer weichen Aussage („ganzheitlich“, „regt Selbstheilungskräfte an“), die so vage ist, dass sie sich kaum widerlegen lässt. Die Kritik der Ärztin zielte aber auf die erste Behauptung, und die bleibt unbeantwortet. Ein Zirkelschluss liegt nicht vor, denn er begründet nichts mit sich selbst. Ein Strohmann scheidet aus, weil er der Ärztin nichts Falsches in den Mund legt. Ein Angriff auf die Person fehlt ebenfalls. Entscheidend ist der Rückzug von der kühnen auf die bescheidene Behauptung, die man auch „Motte-and-Bailey“ nennt: Hinter dem Rückzug steht die Hoffnung, dass das Publikum später wieder die große Behauptung im Kopf hat.","coreRule":"⚡ Erst die große Behauptung, bei Gegenwind der Rückzug auf eine bescheidene, kaum angreifbare Aussage.","beleg":"Werkstück F.2.2 (Die Anatomie der Täuschung: Motte-and-Bailey)","status":"entwurf","kurz":"Aus der kühnen, prüfbaren Heilbehauptung wird unter Kritik eine vage Aussage, die kaum zu widerlegen ist. Der Einwand der Ärztin zielte auf die erste Behauptung, und genau die bleibt unbeantwortet.","prueffrage":"Auf welche Behauptung bezog sich der Einwand der Ärztin, und beantwortet die Reaktion des Verkäufers genau diese?","rueckmeldung":[{"option":0,"text":"„Ganzheitlich“ und „Selbstheilungskräfte“ klingen, als würde die Wirkung nur mit anderen Worten wiederholt. Der Verkäufer begründet aber nichts mit sich selbst, er weicht auf eine vagere Aussage aus; eine Begründung, die im Kreis läuft, fehlt."},{"option":1,"text":"Ein Strohmann braucht eine verzerrte Fassung dessen, was die andere Seite gesagt hat. Die Ärztin wird aber weder falsch wiedergegeben noch widerlegt. Ihr Einwand wird schlicht übergangen."},{"option":3,"text":"Den Einwand zu übergehen, ist noch kein Angriff auf die Person. Der Verkäufer wertet die Ärztin weder ab noch greift er ihre Kompetenz oder ihre Motive an. Er wechselt das Thema und lässt die Sachfrage offen."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): „Motte and Bailey Doctrines“. Practical Ethics, Oxford Uehiro Centre, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Shackel, N. (2005): The Vacuity of Postmodernist Methodology. Metaphilosophy 36(3)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"a368fbee9daa085f"}},{"id":"qx-f-044","clusterId":"F","werkstueckRef":"F.2.3","stufe":1,"question":"Ein Forscherteam will ein Tier aufspüren, dessen Existenz bisher unbelegt ist. Welches Vorhaben ist ein seriöser Versuch der Entdeckung und keine bloße Monsterjagd?","options":["Ein Team untersucht in einem kaum erforschten Waldgebiet Hinweise auf ein unbekanntes Tier und will das Tier selbst oder eindeutiges Probenmaterial beschaffen.","Ein Team reist in ein kaum erforschtes Waldgebiet und will aus übereinstimmenden Berichten von Dorfbewohnern auf die Existenz eines unbekannten Tieres schließen.","Ein Team stellt in einem kaum erforschten Tal Kamerafallen für ein tonnenschweres Raubtier auf, obwohl die dortige Beute für eine überlebensfähige Population nicht reicht.","Ein Team sucht in einem gut erforschten Schutzgebiet mit dichtem Kameranetz ein großes Raubtier, das auf keiner Aufnahme der letzten Jahre zu sehen war."],"correctIndex":0,"explanation":"Dass Gorilla, Okapi und Riesenkalmar einst als Legenden galten, zeigt nur, dass die Welt früher weniger erforscht war. Es sagt nichts darüber, ob ein bestimmtes Tier heute existiert. Entscheidend sind zwei Fragen: Wie plausibel ist die Behauptung nach dem bekannten biologischen Wissen, und wie gut sind die Beweise? Ein Vorhaben ist seriös, wenn es in wirklich unerforschtem Gebiet nach einem Tier mit plausiblen Hinweisen sucht und handfeste, prüfbare Belege anstrebt, etwa einen Kadaver, DNA oder klare Filmaufnahmen. In gut erforschten Gebieten ist eine unbemerkte, überlebensfähige Population eines großen Tieres ohne jede eindeutige Spur äußerst unwahrscheinlich.","coreRule":"⚡ Nicht die Seltsamkeit des Tieres, sondern Plausibilität und Beweisqualität trennen Suche von Jagd.","beleg":"Werkstück F.2.3 (Die Konfrontation mit der Realität: Die legitime Grenzwissenschaft); Fn. gl-f-okapi, gl-f-kalmar","status":"entwurf","scenario":"Vier Teams planen Expeditionen. Alle berufen sich darauf, dass Gorilla, Okapi und Riesenkalmar einst als Legenden galten und später doch wissenschaftlich beschrieben wurden. Du sollst einschätzen, welches der Vorhaben auf dieser Grundlage tatsächlich eine Entdeckung erwarten lässt.","kurz":"Dass früher als Legende geltende Tiere real waren, zeigt nur, wie wenig damals erforscht war. Seriös ist, in wirklich unerforschtem Gebiet nach plausiblen Hinweisen zu suchen und Handfestes wie ein Tier oder eindeutiges Probenmaterial zu beschaffen.","prueffrage":"Welche Spuren müsste ein großes Tier über Jahrzehnte hinterlassen, und wo hätte man sie längst finden müssen?","rueckmeldung":[{"option":1,"text":"Berichte von Dorfbewohnern sind ein guter Anfang und können zeigen, wo man suchen sollte. Übereinstimmende Erzählungen ersetzen aber keinen Beleg: Beweisen kann die Existenz nur ein Tier, ein Kadaver, DNA oder klares Filmmaterial."},{"option":2,"text":"Kamerafallen sind ein gutes Werkzeug, und das Tal ist kaum erforscht. Doch ein tonnenschweres Raubtier bräuchte genug Beute, um dort überleben zu können. Fehlt sie, ist die Annahme schon nach bekanntem biologischem Wissen kaum plausibel."},{"option":3,"text":"Auch das klingt nach Forschung, und Kameras sind ein sinnvolles Mittel. In einem gut erforschten Gebiet mit dichtem Netz spricht das Ausbleiben jeder Aufnahme aber eher gegen ein verborgenes großes Raubtier. Unbemerkt überlebt hätte es dort äußerst unwahrscheinlich."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Tetrapod Zoology (tetzoo.com): „The Discovery of the Okapi, Part 1“ (2023)","oeffentlich":true,"url":"https://tetzoo.com/blog/2023/4/11/the-discovery-of-the-okapi-part-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281, 20140161","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"},{"typ":"url","kurz":"Traill, L. W. u. a. (2007): Minimum viable population size (Autorenfassung)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"5fb88109e6628a55"}},{"id":"qx-f-045","clusterId":"F","werkstueckRef":"F.2.3","stufe":2,"question":"Jemand behauptet, im Loch Ness lebe eine Population riesiger Reptilien, die sich dort seit Generationen hält. Welche Überlegung spricht am stärksten dagegen?","options":["Als grobe Faustregel wiegen Räuber zusammen höchstens etwa ein Zehntel ihrer Beute; auf eine überlebensfähige Gruppe verteilt, wäre jedes Tier viel zu klein.","Viele Sichtungen lassen sich durch Wellen, Treibholz und Wasservögel erklären; Augenzeugenberichte sind deshalb als Beleg für große Tiere wenig wert.","Die Beweislast liegt bei dem, der eine außergewöhnliche Behauptung aufstellt; solange kein Belegtier vorliegt, ist die Behauptung nicht gestützt.","Dass nie ein Tier gefangen oder tot gefunden wurde, ist noch kein Gegenbeweis; fehlende Funde schließen eine verborgene Population nicht aus."],"correctIndex":0,"explanation":"Die Behauptung lässt sich mit einer einfachen Bilanz prüfen: Akustische Schätzungen (Shine 1993) und Probennahmen ergaben rund 17 bis 24 Tonnen Fisch im freien Wasser des Sees. Nach einer ökologischen Faustregel macht die Masse aller Räuber zusammen davon meist höchstens etwa ein Zehntel aus, also rund zwei Tonnen. Eine Art braucht aber eine Mindestzahl von Tieren, um nicht auszusterben; bei etwa zehn Tieren käme jedes auf höchstens rund 200 Kilogramm Körpermasse, viel zu wenig für riesige Reptilien. Einschränkung: Die Faustregel gilt nur näherungsweise, und die Zahl gilt nur für das freie Wasser, Uferzone, Bodenfische und Wanderfische sind nicht erfasst; sie ist eine Größenordnung, kein exakter Wert.","coreRule":"⚡ Prüfe Existenzbehauptungen mit einer Bilanz: Reicht die Nahrung für eine überlebensfähige Population?","beleg":"Werkstück F.2.3 (Verletzung der Ökologie & des Energiebedarfs); Fn. gl-f-nessie (Shine 1993, S. 271 f.; auch Loxton, Prothero 2013, S. 158 f.)","status":"entwurf","scenario":"In einem Gespräch über Loch Ness sagt jemand: „Der See ist riesig und tief, da kann sich locker eine Gruppe großer Reptilien verstecken.“ Du weißt: Im freien Wasser des Sees schwimmen nach Sonarzählungen und Probennahmen nur rund 17 bis 24 Tonnen Fisch.","quote":"","quoteLabel":"","kurz":"Der See gibt nach der Fischbilanz nur etwa zwei Tonnen Räubermasse her. Auf eine überlebensfähige Gruppe verteilt, bliebe für jedes Tier viel zu wenig für riesige Reptilien. Die Faustregel gilt nur näherungsweise, die Größenordnung genügt aber.","prueffrage":"Welche Zahl über den See ist bekannt, und was lässt sich mit ihr nachrechnen?","rueckmeldung":[{"option":1,"text":"Dass Wellen, Treibholz und Vögel viele Sichtungen erklären, stimmt, und es schwächt Zeugenberichte. Es rechnet aber nicht nach, ob der See solche Tiere überhaupt ernähren könnte; dieses Argument greift die Behauptung selbst an."},{"option":2,"text":"Die Beweislast beim Behauptenden zu sehen ist richtig. Sie sagt aber nur, dass die Behauptung unbelegt ist, und liefert kein Argument aus den Gegebenheiten des Sees, das gegen die Population spricht."},{"option":3,"text":"Fehlende Funde sind tatsächlich kein Gegenbeweis. Das spricht aber eher für die Möglichkeit einer verborgenen Population, als gegen sie, und sagt nichts darüber, ob der See genug Nahrung für sie hätte."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Shine, A. J. (1993): Postscript: Surgeon or Sturgeon? Scottish Naturalist 105, S. 271–282 (Webfassung des Loch Ness Project)","oeffentlich":true,"url":"https://lochnessproject.org/ARCHIVE%20ROOM/papershtml/loch_ness_surgeon_sturgeon.htm","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"150709cec6dca977"}},{"id":"qx-f-046","clusterId":"F","werkstueckRef":"F.2.3","stufe":3,"question":"Ein Forscherteam sammelt Haarproben, die Yeti, Bigfoot und ähnlichen Wesen zugeschrieben wurden, und analysiert sie genetisch. Von den Proben mit auswertbarer DNA stammt keine einzige von einem unbekannten Primaten; gefunden werden unter anderem Bär, Pferd, Kuh, Hund, Wolf, Kojote und ein Mensch. Ein Freund sagt: „Das ist der Beweis, dass es diese Wesen nicht gibt.“ Wie ordnest du das Ergebnis richtig ein?","options":["Die Studie beweist die Nichtexistenz, denn nach dem Sparsamkeitsprinzip ist die einfachste Erklärung, dass alle Haarproben von Bär, Pferd oder Mensch stammen, damit gesichert.","Die Studie lässt die Existenz offen, denn dass in den untersuchten Haarproben kein unbekannter Primat steckt, beweist keine Nichtexistenz, liefert aber auch keinen Beleg.","Die Studie entlarvt alle Sichtungen als Irrtum, denn jede Probe, die einem Wesen zugeschrieben wurde, stammte von einem bekannten Tier.","Die Studie ändert nichts, denn die Beweislast liegt bei den Skeptikern, und solange nicht jede Sichtung widerlegt ist, gilt die Existenz als belegt."],"correctIndex":1,"explanation":"Von den Proben mit auswertbarer DNA stammte keine von einem unbekannten Primaten. Das Ergebnis zeigt: Die untersuchten Haare, die Yetis oder Bigfoots zugeschrieben wurden, stammten von bekannten Tieren und einem Menschen. Eine endgültige Widerlegung ist das nicht, denn ein einzelnes Nichtfinden kann nie beweisen, dass etwas nirgends existiert; die Autoren der Studie sagten selbst, sie könne die Existenz unbekannter Primaten weder widerlegen noch belegen. Umgekehrt trägt die Behauptung die Beweislast, und bisher fehlt jeder tragfähige Beleg. Wer „kein Fund“ als „Beweis des Gegenteils“ liest, macht denselben Fehler wie jemand, der „nicht widerlegt“ als „bewiesen“ liest.","coreRule":"⚡ Gezielt gesucht, nichts gefunden: Das ist kein Beweis der Nichtexistenz, aber ein weiterer Mangel an Belegen für die Behauptung.","beleg":"Werkstück F.2.3 (Verletzung der Populationsbiologie); Fn. gl-f-sykes (Sykes u. a. 2014, Proc. R. Soc. B 281, S. 1--3)","status":"entwurf","scenario":"","kurz":"Kein Fund in diesen Proben zeigt nur, dass sie von bekannten Tieren stammen, nicht, dass es nirgends etwas gibt. Wer „nichts gefunden“ als „Gegenteil bewiesen“ liest, macht denselben Fehler wie bei „nicht widerlegt, also wahr“.","prueffrage":"Was genau wurde untersucht, und was fand sich in den Proben mit auswertbarer DNA?","rueckmeldung":[{"option":0,"text":"Die einfachste Erklärung für die untersuchten Haare ist tatsächlich meist ein bekanntes Tier. Das Sparsamkeitsprinzip bevorzugt aber nur einfache Deutungen, es beweist nichts, und die Proben sind nur ein kleiner Ausschnitt."},{"option":2,"text":"Für die untersuchten Haarproben stimmt das: Sie stammten von bekannten Tieren. Von dieser Stichprobe auf alle Sichtungen zu schließen, trägt aber nicht, denn viele Sichtungen haben gar keine Probe hinterlassen."},{"option":3,"text":"Dass die Studie keine Widerlegung liefert, ist richtig. Die Beweislast liegt aber bei der Behauptung: „Nicht widerlegt“ ist kein Beleg, und bisher fehlt jeder tragfähige Beleg für diese Wesen."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Sykes, B. C.; Mullis, R. A.; Hagenmuller, C.; Melton, T. W.; Sartori, M. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281(1789), 20140161 (CC BY, PMC4100498)","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"eab6e980e8b6f222"}},{"id":"qx-f-047","clusterId":"F","werkstueckRef":"F.2.3","stufe":4,"question":"Ein Bigfoot-Fan sagt: „Der Gorilla galt lange als Mythos und existiert doch. Also kann es auch Bigfoot geben.“ Welche Antwort trifft den Denkfehler am besten?","options":["Der Gorilla-Fall zeigt nur, dass Entdeckungen möglich sind. Für das jetzt behauptete Tier Bigfoot liefert er keinen einzigen Beleg.","Der Fan schließt aus fehlenden Gegenbeweisen. Dass niemand Bigfoots Nichtexistenz bewiesen hat, ist für ihn der Grund, ihn für möglich zu halten.","Der Fan argumentiert im Kreis. Er setzt voraus, dass Bigfoot existiert, und nimmt genau das als Grund dafür, dass er existieren kann.","Der Fan verwechselt Abfolge mit Ursache. Dass auf die Gorilla-Legende die Entdeckung folgte, soll auch bei Bigfoot gelten, obwohl die Abfolge nichts erzwingt."],"correctIndex":0,"explanation":"Der Fan schließt von „es gab Fälle, in denen eine Legende wahr war“ auf „also ist diese Legende wahr“. Das ist kein Beleg, sondern ein Präzedenzfall: Er zeigt nur, dass Entdeckungen möglich sind. Die Welt war damals unerforschter, und für das Okapi (1901 anhand von Fellstreifen beschrieben) und den Riesenkalmar (1857 anhand von Funden beschrieben) folgten handfeste Belege. Für Bigfoot fehlen solche Belege; gezielte DNA-Analysen angeblicher Haarproben ergaben 2014 nur bekannte Tiere, darunter Bären, Pferde, Kühe, Hunde und einen Menschen. Dazu kommt: Eine verborgene Population riesiger Primaten bräuchte Tausende Tiere, die in einer von Satelliten und Smartphones kartierten Welt keine eindeutigen Spuren hinterlassen. Dass früher manches unerforscht war, macht die Behauptung heute nicht wahrscheinlicher. Die anderen Deutungen nennen bekannte Fehler, treffen aber nicht, was der Fan sagt. Auf fehlende Gegenbeweise beruft er sich nicht, er zieht den Gorilla heran. Er setzt Bigfoots Existenz nicht schon voraus, also argumentiert er auch nicht im Kreis. Und er behauptet keine Ursache-Wirkung-Beziehung zwischen Legende und Entdeckung; sein Fehler ist der Sprung vom Möglichen zum Belegten.","coreRule":"⚡ „Früher galt es auch als Mythos“ ersetzt keinen Beleg für das jetzt behauptete Tier.","beleg":"Werkstück F.2.3 (Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"","kurz":"Der Gorilla zeigt nur, dass Entdeckungen möglich sind, ein Beleg für Bigfoot ist das nicht. Der Fehler ist der Sprung vom Möglichen zum Belegten: Bei Gorilla, Okapi und Riesenkalmar folgten handfeste Funde, bei Bigfoot fehlen sie.","prueffrage":"Was hat Fachleute am Ende vom Gorilla überzeugt, und gibt es für Bigfoot etwas Vergleichbares?","rueckmeldung":[{"option":1,"text":"Der Fehler, fehlende Gegenbeweise als Grund zu nehmen, kommt bei Bigfoot-Debatten oft vor. Hier beruft sich der Fan aber nicht darauf, dass niemand das Gegenteil bewiesen hat, sondern auf den Gorilla als Vorbild."},{"option":2,"text":"Ein Zirkelschluss liegt nur vor, wenn die Schlussfolgerung schon in der Annahme steckt. Der Fan setzt Bigfoots Existenz aber nicht voraus, sondern stützt sich auf ein Beispiel, den Gorilla. Der Fehler liegt woanders."},{"option":3,"text":"Das Muster „erst Legende, dann Entdeckung“ erinnert an eine Abfolge. Der Fan behauptet aber keine Ursache-Wirkung-Beziehung zwischen beidem. Er zieht einen Präzedenzfall heran und schließt vom Möglichen aufs Belegte."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tetrapod Zoology (tetzoo.com): „The Discovery of the Okapi, Part 1“ (2023)","oeffentlich":true,"url":"https://tetzoo.com/blog/2023/4/11/the-discovery-of-the-okapi-part-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kubodera, T.; Mori, K. (2005): First-ever observations of a live giant squid in the wild. Proc. R. Soc. B 272(1581), S. 2583–2586 (PMC1559985)","oeffentlich":true,"doi":"10.1098/rspb.2005.3158","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281, 20140161","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8cde0b0d831ff624"}},{"id":"qx-f-048","clusterId":"F","werkstueckRef":"F.2.4","stufe":1,"question":"Eine Werbung für ein neues Buch lautet: „Millionen Leser können sich nicht irren – dieses Buch beweist, dass Außerirdische die Pyramiden gebaut haben!“ Was ist an dieser Argumentation fehlerhaft?","options":["Sie folgert aus der großen Verbreitung eines Buches, dass seine Behauptung belegt ist, obwohl Verkaufszahlen nichts über die Beweislage aussagen.","Sie verlangt, dass die Behauptung schon deshalb richtig sein muss, weil bisher niemand den Beweis erbracht hat, dass die Pyramiden von Menschen gebaut wurden.","Sie stützt sich auf ein einziges Buch als Quelle; würden mehrere Bücher dieselbe These vertreten, wäre die Behauptung damit belegt.","Sie schließt aus einem sehr alten Bauwerk, dass die damaligen Menschen es nicht errichtet haben können, weil ihnen die nötige Technik gefehlt habe."],"correctIndex":0,"explanation":"Verkaufszahlen messen Neugier, Marketing und Unterhaltungswert, nicht Wahrheit. Erich von Däniken etwa trug die Alien-Idee 1968 mit „Erinnerungen an die Zukunft“ zu einem Millionenpublikum (die englische Ausgabe verkaufte sich über sieben Millionen Mal), obwohl die Idee älter war und dadurch nicht besser belegt wurde. Ob eine Behauptung stimmt, entscheiden Belege und Methoden, nicht die Zahl derer, die sie gekauft, gehört oder geglaubt haben. Prüfe deshalb immer: Welche Beweise werden vorgelegt, und nicht: Wie viele glauben es?","coreRule":"⚡ Bekannt gemacht ist nicht bewiesen: Die Popularität einer Idee ist kein Beleg.","beleg":"Werkstück F.2.4 (Die Autopsie-Akte); Fn. gl-f-daeniken (Inselmann 2026, Skeptiker 1/2026, S. 25 und 27)","status":"entwurf","scenario":"","kurz":"Millionen Käufer zeigen nur, dass ein Buch Neugier weckt und sich gut verkauft, nicht dass seine These stimmt. Der Fehler liegt im Schluss von „viele glauben es“ auf „es ist belegt“: Ob etwas stimmt, entscheiden Belege und Methoden.","prueffrage":"Welche Belege nennt die Werbung selbst, und was davon sagt etwas über die Pyramiden?","rueckmeldung":[{"option":1,"text":"Die Beweislast so umzudrehen, wäre tatsächlich ein klassischer Fehlschluss. Die Werbung tut das aber nicht, sie beruft sich auf die Leserzahl. Außerdem ist der Bau der Pyramiden durch Menschen gut belegt."},{"option":2,"text":"Die Zahl der Quellen ist nicht der Kern: Auch viele Bücher mit derselben These belegen nichts, solange keines Beweise vorlegt. Die Werbung macht einen anderen Fehler, sie beruft sich auf die Zahl der Leser statt auf Belege."},{"option":3,"text":"Das „Es fehlte die Technik“-Argument kommt in Alien-Theorien oft vor, steht aber nicht in dieser Werbung, und es stimmt auch nicht: Die Ägypter besaßen die nötigen Werkzeuge und Organisation. Diese Werbung setzt auf Verkaufszahlen."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to the People“/„Bandwagon“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Associated Press via NBC News (11.01.2026): „Erich von Däniken, Swiss writer who spawned alien archaeology, dies at 90“","oeffentlich":true,"url":"https://www.nbcnews.com/news/obituaries/erich-von-daniken-swiss-writer-spawned-alien-archaeology-dies-90-rcna253448","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Inselmann, L. (2026): Zurück zu den Sternen. Ein skeptischer Nachruf auf Erich von Däniken. Skeptiker 1/2026, S. 25–35","oeffentlich":false,"seite":"S. 27"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6964cbf8fd894a43"}},{"id":"qx-f-049","clusterId":"F","werkstueckRef":"F.2.4","stufe":2,"question":"Welche Frage prüft die Deutung des Sprechers am besten?","scenario":"In einer Dokumentation wird eine Höhlenmalerei gezeigt: eine stilisierte Figur mit großem Kopfschmuck. Der Sprecher sagt: „Das ist ein Wesen im Raumanzug, kein Zweifel.“ Erhalten sind weder Beschriftungen noch Beigaben, die die Figur erklären.","options":["Wie ähnlich sieht der Kopfschmuck der Figur einem heutigen Raumanzughelm, und welche Teile der Figur lassen sich als Schläuche oder Visier deuten?","Welche Kopfbedeckungen und rituellen Gewänder gab es in der Kultur, die das Bild gemalt hat, und passt der Kopfschmuck der Figur dazu?","Mit welchen Farbstoffen und welcher Technik wurde die Figur gemalt, und lässt sich der Kopfschmuck damit zeitlich einordnen?","Wie lässt sich ausschließen, dass die Figur samt Kopfschmuck eine spätere Fälschung ist, und wer hat die Höhle zuerst untersucht?"],"correctIndex":1,"explanation":"Der Sprecher liest ein sehr altes Bild durch die Brille der Gegenwart: Weil wir Raumanzüge kennen, sehen wir sie auch dort, wo ein Kopfschmuck zu sehen ist. Das ist Präsentismus. Die Deutung gewinnt nicht dadurch an Gewicht, dass sie dem heutigen Auge naheliegt. Entscheidend ist, was für die Entstehungszeit und den kulturellen Rahmen des Bildes belegt ist. In vielen frühen Kulturen gehören Kopfschmuck und Masken zu Ritualen, und eine Figur mit auffälligem Kopfschmuck passt deshalb wahrscheinlich zu einer Person in ritueller Kleidung, etwa einem Schamanen. Die beste Prüffrage fragt daher nach dem Kontext des Bildes. Die anderen Fragen klingen sinnvoll, führen hier aber nicht weiter. Wer nach Ähnlichkeiten mit einem Raumanzughelm sucht, sucht nur Bestätigung für die Deutung, die erst geprüft werden soll. Farbstoffe und Technik sind für Restauratoren und die Datierung wichtig, sagen aber nichts darüber, was die Figur darstellt. Eine Fälschungsprüfung ist sinnvoll, wenn die Echtheit zweifelhaft ist, davon ist hier nicht die Rede.","coreRule":"⚡ Wer ein altes Bild deuten will, fragt zuerst nach dem Kontext seiner Zeit, nicht nach der Ähnlichkeit zu heutiger Technik.","beleg":"Werkstück F.2.4 (Verletzung der Kunstgeschichte & Religionswissenschaft)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Das heutige Auge liest einen Raumanzug in den Kopfschmuck, weil wir Raumanzüge kennen. Das ist Präsentismus. Belastbar ist, was zur Entstehungszeit und zum kulturellen Rahmen des Bildes belegt ist, etwa rituelle Kopfbedeckungen.","prueffrage":"Was ist von dem Bild selbst erhalten, und was fügt der Sprecher aus eigenem Wissen hinzu?","rueckmeldung":[{"option":0,"text":"Ähnlichkeiten lassen sich fast immer finden, wenn man gezielt danach sucht. So bestätigt man aber nur die Deutung, die erst geprüft werden soll, und fragt nicht, was die Figur für ihre Zeit bedeutete."},{"option":2,"text":"Farbstoffe und Technik sind für Datierung und Restaurierung wichtig. Sie verraten jedoch nicht, was die Figur darstellen soll, und klären deshalb die Deutung des Sprechers nicht."},{"option":3,"text":"Eine Fälschungsprüfung ist sinnvoll, wenn die Echtheit zweifelhaft ist. Davon ist hier nicht die Rede, und wer die Höhle zuerst untersuchte, sagt nichts darüber, was die Figur darstellt."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Colavito, J.: „Faking Ancient Art in Uzbekistan“ (jasoncolavito.com)","oeffentlich":true,"url":"https://www.jasoncolavito.com/faking-ancient-art-in-uzbekistan.html","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"3ce13b3245f01f67"}},{"id":"qx-f-050","clusterId":"F","werkstueckRef":"F.2.4","stufe":3,"question":"Eine Doku-Reihe fragt in jeder Folge neu: „Was, wenn die Götter in Wahrheit Astronauten waren?“ Eine Zuschauerin sagt: „Die behaupten ja gar nichts, die fragen nur. Da kann man ihnen nichts vorwerfen.“ Was ist an dieser Verteidigung fehlerhaft?","options":["Wer nur fragt, legt eine Antwort nahe, ohne sie zu behaupten, und umgeht so die Pflicht, sie zu belegen.","Eine offene Frage lässt jedem Zuschauer die Prüfung selbst und ist deshalb die sauberste Form einer Hypothese.","Wer nichts behauptet, kann auch nichts Falsches sagen, und deshalb bleibt eine Frage immer frei von Fehlschlüssen.","Eine Frage verlagert die Beweislast auf die Kritiker, weil diese das Gegenteil zeigen müssen, um sie zu entkräften."],"correctIndex":0,"explanation":"Eine Suggestivfrage wie „Was, wenn die Götter in Wahrheit Astronauten waren?“ stellt keine beweisbare Behauptung auf, legt aber eine bestimmte Antwort nahe. Das erzeugt ein Gefühl des Mysteriums, und weil nichts Konkretes behauptet wird, muss auch nichts belegt werden. Die Beweislast liegt jedoch bei dem, der eine außergewöhnliche Deutung nahelegt, nicht bei denen, die sie bezweifeln. Wer nur fragt, entzieht sich der Prüfung und bekommt trotzdem die Wirkung einer Behauptung. Ein Test: Formuliere die Frage als Aussage um („Die Götter waren Astronauten“). Wenn du dann Belege verlangen würdest, gilt das auch für die Frageform.","coreRule":"⚡ Wer nur fragt, scheint nichts zu behaupten und umgeht so die Beweislast: Das ist die Wirkung der Suggestivfrage.","beleg":"Werkstück F.2.4 (Die Anatomie der Täuschung: „Ich stelle ja nur Fragen“)","status":"entwurf","scenario":"","kurz":"Eine Suggestivfrage behauptet nichts Konkretes und legt trotzdem eine bestimmte Antwort nahe. So entsteht die Wirkung einer Behauptung, ohne dass jemand Belege liefern muss. Der Fehler liegt darin, dass die Frageform vor der Prüfung schützt.","prueffrage":"Welchen Eindruck hinterlässt die Frage bei dir, und was bliebe von ihr übrig, wenn du sie als bloße Aussage lesen würdest?","rueckmeldung":[{"option":1,"text":"Eine echte Hypothese ist so formuliert, dass man sie prüfen kann. Die Frage hier lenkt dagegen auf eine bestimmte Antwort, ohne sich festzulegen, und entgeht damit genau der Prüfung, die eine Hypothese braucht."},{"option":2,"text":"Wer nichts behauptet, sagt in der Tat nichts Falsches. Doch die Suggestivfrage erzielt die Wirkung einer Behauptung und umgeht den Beleg. Deshalb bleibt sie keineswegs immer frei von Fehlschlüssen."},{"option":3,"text":"Wer eine Frage nicht widerlegen kann, scheint im Nachteil. Die Beweislast trägt aber, wer eine außergewöhnliche Deutung nahelegt; Kritiker müssen das Gegenteil nicht zeigen, um die Deutung anzuzweifeln."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Loaded Question“, „Complex Question“ und „Burden of Proof“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f41319df7fffa842"}},{"id":"qx-f-051","clusterId":"F","werkstueckRef":"F.3.1","stufe":1,"question":"Der Heilpraktiker sagt: „Krebs ist keine Fehlfunktion des Körpers, sondern ein sinnvolles Programm, das durch einen seelischen Schock ausgelöst wird. Eine Chemotherapie stört diesen Heilungsprozess und ist die eigentliche Todesursache.“ Welcher Einwand trifft den Kern dieser Behauptung am besten?","options":["Krebs ist kein sinnvolles Programm, sondern entsteht aus mutierten körpereigenen Zellen, die unkontrolliert wachsen und unbehandelt zum Tod führen können.","Der Heilpraktiker hat keine ärztliche Zulassung, und schon deshalb kann nichts von dem stimmen, was er dem Onkel über Krebs und Chemotherapie erklärt.","Ein Heilpraktiker, der von der Operation abrät, verdient womöglich an Alternativbehandlungen, und deshalb muss seine Erklärung des Krebses falsch sein.","Der Onkel ist durch die Diagnose verunsichert und deshalb leicht zu beeinflussen, also ist die Erklärung, die ihm der Heilpraktiker gibt, nicht ernst zu nehmen."],"correctIndex":0,"explanation":"Die Behauptung deutet eine zerstörerische Krankheit in einen „sinnvollen“ Vorgang um, ohne einen zellbiologischen Mechanismus anzugeben. Krebs ist unkontrolliertes Wachstum mutierter körpereigener Zellen, das Gewebe zerstört und den Organismus ohne Behandlung töten kann. Dass ein Tumor „Sinn“ hätte, ist eine Zuschreibung, kein Befund. Dazu kommt: Wird die Behandlung für den Tod verantwortlich gemacht, kann die Aussage nie scheitern. Wer geheilt wird, bestätigt sie; wer stirbt, hat den „Konflikt nicht gelöst“, einen „Folgekonflikt“ erlitten oder wurde durch die „panikmachende Schulmedizin“ getötet. Eine Aussage, die durch kein denkbares Ergebnis widerlegt werden kann, sagt nichts über die Welt aus.","coreRule":"⚡ Wer eine tödliche Krankheit zum „sinnvollen Programm“ erklärt, braucht einen prüfbaren Mechanismus; ohne ihn ist es eine Umdeutung, keine Erklärung.","beleg":"Werkstück F.3.1 (Die Kern-Behauptung; Verletzung der Onkologie & Zellbiologie; Falsifizierbarkeit)","status":"entwurf","scenario":"Eine Bekannte erzählt dir, ihr Onkel habe eine Krebsdiagnose bekommen. Er wolle die Operation absagen, weil ihm ein Heilpraktiker eine ungewöhnliche Erklärung gegeben habe.","kurz":"Der Einwand muss die Behauptung selbst prüfen: Krebs ist unkontrolliertes Wachstum mutierter Körperzellen, ein „Sinn“ wird nur zugeschrieben, und die Aussage kann durch keinen Ausgang scheitern. Wer sie stattdessen über Person oder Motiv angreift, lässt sie unberührt.","prueffrage":"Woran sterben Menschen mit Krebs, die nie eine Chemotherapie bekommen haben?","rueckmeldung":[{"option":1,"text":"Dass ein Heilpraktiker keine ärztliche Zulassung hat, stimmt und darf misstrauisch machen. Es sagt aber nur etwas über die Person, nicht über den Inhalt, und „nichts davon kann stimmen“ folgt daraus nicht."},{"option":2,"text":"Ein möglicher finanzieller Vorteil ist ein berechtigtes Warnsignal. Er zeigt aber nur, warum jemand etwas sagen könnte, und entscheidet nicht, ob es stimmt: Auch eine eigennützige Aussage kann richtig sein."},{"option":3,"text":"Wer durch eine Diagnose verunsichert ist, hört womöglich eher auf einfache Deutungen, und das erklärt, warum der Onkel zuhört. Ob die Deutung stimmt, sagt das aber nicht, denn es betrifft den Zuhörer und nicht die Behauptung."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Cancer Institute: „What Is Cancer?“","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer","abruf":"2026-10-12"},{"typ":"url","kurz":"AG Prävention und Integrative Onkologie (PRiO) in der Deutschen Krebsgesellschaft: Stellungnahme „Germanische Neue Medizin® nach Dr. Hamer“, Stand 30.04.2026","oeffentlich":true,"url":"https://prio-dkg.de/stellungnahmen/germanische-neue-medizin/","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"d58982469a48da46"}},{"id":"qx-f-052","clusterId":"F","werkstueckRef":"F.3.1","stufe":2,"question":"Was ist an dieser Argumentation der entscheidende Fehler?","options":["Das Argument deutet Heilung wie Tod zugunsten der Lehre, sodass kein denkbares Ergebnis sie widerlegen kann und sie sich nicht prüfen lässt.","Das Argument beruft sich darauf, dass die Lehre schon von sehr vielen Kranken befolgt wird, und hält sie deshalb für wahr.","Das Argument beruft sich auf einen berühmten Arzt, der die Lehre vertritt, und hält sie deshalb für belegt, ohne seine Aussagen zu prüfen.","Das Argument spielt auf die Angst der todkranken Verwandten an, und die Lehre wird deshalb nach Gefühl statt nach Belegen beurteilt."],"correctIndex":0,"explanation":"Eine Aussage ist nur dann prüfbar, wenn es ein denkbares Ergebnis gibt, das sie widerlegen würde. Hier wird jeder Ausgang eingebaut: Heilung bestätigt die Lehre, Tod wird dem Patienten („Konflikt nicht gelöst“, „Folgekonflikt“) oder der Schulmedizin („von der Schulmedizin getötet“) angelastet. Ein solches System kann nie scheitern, und gerade deshalb sagt es nichts darüber, ob es stimmt. Im Ernstfall ist das gefährlich, denn bei ernsten Erkrankungen wie Krebs bedeutet der Verzicht auf wirksame Behandlung ein hohes Todesrisiko. Wer prüfen will, fragt: „Welches Ergebnis würde dich überzeugen, dass die Lehre falsch ist?“ Kommt darauf keine Antwort, ist die Lehre keine Erkenntnis, sondern ein Glaubenssystem. Die anderen Erklärungen nennen bekannte Denkfehler, treffen aber nicht, was der Bekannte sagt. Dass viele einer Lehre folgen, sagt nichts über ihre Wahrheit, doch auf Verbreitung beruft er sich gar nicht. Ein berühmter Arzt wird nirgends angeführt. Und mit der Angst der Verwandten argumentiert er nicht, er behauptet, die Lehre irre nie.","coreRule":"⚡ Wenn jeder Ausgang die Lehre bestätigt, ist sie nicht prüfbar, und im Ernstfall gefährlich.","beleg":"Werkstück F.3.1 (Die Konfrontation mit der Realität: Falsifizierbarkeit)","status":"entwurf","scenario":"Ein Bekannter will einer todkranken Verwandten eine „Konflikt-Heillehre“ empfehlen und verteidigt sie so: „Wenn jemand nach der Behandlung gesund wird, beweist das die Lehre. Stirbt jemand, hat er seinen Konflikt nicht gelöst, einen Folgekonflikt erlitten oder wurde von der Schulmedizin getötet. Die Lehre irrt also nie.“","kurz":"Wird jedes Ergebnis zugunsten der Lehre gedeutet, kann nichts sie widerlegen, und dann sagt sie auch nichts über die Wirklichkeit. Der naheliegende Fehler: Dass sie „nie irrt“, wirkt wie Stärke, ist aber ihr Mangel, weil sie sich gar nicht prüfen lässt.","prueffrage":"Wie erklärt die Argumentation die Todesfälle, und wem gibt sie dabei jeweils die Schuld?","rueckmeldung":[{"option":1,"text":"Dass viele einer Lehre folgen, beweist tatsächlich nicht, dass sie stimmt. Der Bekannte nennt aber nirgends, wie viele ihr folgen. Sein Fehler liegt woanders: Er deutet jedes Ergebnis so, dass die Lehre recht behält."},{"option":2,"text":"Ein Verweis auf einen berühmten Arzt wäre in der Tat ein schwacher Beleg, solange man dessen Aussagen nicht prüft. Im Szenario beruft sich der Bekannte aber auf keinen Arzt. Er baut sein Argument allein aus der Deutung von Heilung und Tod."},{"option":3,"text":"Bei einer todkranken Verwandten spielen Gefühle sicher eine große Rolle. Der Bekannte argumentiert aber nicht mit ihrer Angst, sondern behauptet, die Lehre irre nie. Der Fehler steckt in dieser Behauptung selbst, nicht in einem Appell an Gefühle."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (Abschn. 2)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"url","kurz":"AG PRiO in der Deutschen Krebsgesellschaft: Stellungnahme „Germanische Neue Medizin® nach Dr. Hamer“, Stand 30.04.2026","oeffentlich":true,"url":"https://prio-dkg.de/stellungnahmen/germanische-neue-medizin/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b57af25e34d7a781"}},{"id":"qx-f-053","clusterId":"F","werkstueckRef":"F.3.1","stufe":3,"question":"Was sind die Ringe, und was folgt daraus für die Behauptung des Heilers?","options":["Sie sind echte Veränderungen im Gehirn, die keinen Rückschluss auf den Ort des Tumors erlauben, und damit ist die Behauptung widerlegt.","Sie sind echte Veränderungen im Gehirn, deren Deutung unter Fachleuten offen ist, und damit bleibt die Behauptung eine ernst zu nehmende Möglichkeit.","Sie sind Zeichen früherer Entzündungen im Gehirn, die der Heiler fälschlich als Konfliktspuren deutet, und damit ist die Behauptung widerlegt.","Sie sind Artefakte der Aufnahmetechnik, die das CT-Gerät selbst erzeugt, und damit trägt ihr bloßes Sichtbarsein die Behauptung nicht."],"correctIndex":3,"explanation":"Dass etwas auf einem Bild sichtbar ist, heißt noch nicht, dass es eine Eigenschaft des Patienten abbildet. Bildgebende Verfahren können selbst Strukturen erzeugen, die es im Körper gar nicht gibt. Bei diesen Ringen ist das der Fall: Radiologen kennen sie seit Langem als Ringartefakte, die die Computertomographie selbst erzeugt und die keine medizinische Bedeutung haben (so beschreibt es etwa Prang 2014). Wer aus ihnen Konflikttyp und Tumorort ablesen will, schließt aus einem Fehler der Technik auf eine Eigenschaft des Patienten. Die richtige Prüffrage lautet deshalb, ob die Struktur überhaupt eine Eigenschaft des Patienten zeigt oder eine des Messgeräts, und nicht, ob sie echt aussieht. Die anderen Antworten erfinden Befunde im Gehirn (Veränderungen, frühere Entzündungen) oder behaupten eine offene Deutung, während die Ringe von der CT-Technik selbst erzeugt werden und keine medizinische Bedeutung haben.","coreRule":"⚡ Was auf dem Bild wie ein Befund aussieht, kann ein Artefakt der Technik sein.","beleg":"Werkstück F.3.1 (Verletzung der Neurologie); Fn. gl-f-hamerherde (Prang 2014, Kap. „Germanische Neue Medizin“)","status":"entwurf","scenario":"Ein Heiler behauptet, er könne auf Gehirn-CT-Bildern an ringförmigen Strukturen („Herden“) erkennen, welchen seelischen Konflikt ein Patient hatte und wo im Körper sein Tumor sitzt. Als Beleg zeigt er dir mehrere Bilder, auf denen solche Ringe deutlich zu sehen sind. Die Ringe selbst sind unstrittig vorhanden.","kurz":"Dass etwas auf einem Bild sichtbar ist, zeigt noch nicht, dass es zum Patienten gehört. Die Ringe erzeugt die CT-Technik selbst, als Ringartefakte ohne medizinische Bedeutung, daher lässt sich aus ihnen weder Konflikt noch Tumorort ablesen.","prueffrage":"Wofür halten Fachleute, die täglich CT-Bilder auswerten, solche Ringe?","rueckmeldung":[{"option":0,"text":"Dass die Ringe nichts über den Tumorort verraten, ist richtig. Sie sind aber keine Veränderungen im Gehirn, sondern entstehen durch die Aufnahmetechnik. Eine Behauptung ist außerdem nicht schon deshalb widerlegt, weil ihr Beleg nicht trägt."},{"option":1,"text":"Ein deutlich sichtbarer Befund wirkt, als müsse er etwas bedeuten, und eine offene Fachfrage klingt vorsichtig. Hier gibt es aber keine: Die Ringe stammen vom CT-Gerät selbst und gelten unter Radiologen seit Langem als bedeutungslos."},{"option":2,"text":"Die Ringe wirken wie Spuren im Gehirn, weil man Strukturen auf Bildern gern als Befund liest. Sie entstehen aber durch die CT-Technik: Der Heiler deutet sie falsch, doch der Grund liegt im Gerät, nicht in früheren Entzündungen."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dawes, L.; Ismail, M.; Murphy, A. u. a.: „Ring artifact“. Radiopaedia.org (rID 1988)","oeffentlich":true,"url":"https://radiopaedia.org/articles/ring-artifact","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“ (Abschnitt Hamer-Herde)","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prang, M. (2014): Alternativmedizin: Was sie leistet. Wann sie schadet. München: C. H. Beck, Kap. „Germanische Neue Medizin“","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"a089f537c063adb9"}},{"id":"qx-f-054","clusterId":"F","werkstueckRef":"F.3.1","stufe":4,"question":"Ein Anbieter wirbt für die „5 Biologischen Naturgesetze“ und versichert: „Mit der Germanischen Neuen Medizin hat das nichts zu tun.“ Auf Nachfrage zählt er als „Gesetze“ dieselben Behauptungen auf wie die Germanische Neue Medizin: Jede Krankheit gehe auf einen seelischen Schock-Konflikt zurück, Tumore seien „sinnvolle Programme“, Chemotherapie störe die Heilung. Was folgt daraus für die Beurteilung des Angebots?","options":["Die Lehre ist inhaltlich dieselbe geblieben, denn Schock-Konflikt, „sinnvolle Programme“ und gestörte Heilung durch Chemotherapie sind dieselben Behauptungen unter neuem Namen.","Die Abgrenzung des Anbieters ist glaubhaft, denn wer ausdrücklich sagt, mit der Germanischen Neuen Medizin habe das nichts zu tun, hat sich auch inhaltlich von ihr gelöst.","Die Lehre ist belastbarer als ihr Vorgänger, denn als „Gesetze“ aufgezählte Behauptungen sind geprüfte Regeln, auf die man sich verlassen kann.","Die Verbindung zur früheren Lehre ist nicht erwiesen, denn nach der Unschuldsvermutung gilt seine Aussage, es gebe keinen Zusammenhang, bis das Gegenteil bewiesen ist."],"correctIndex":0,"explanation":"Ob eine Behauptung stimmt, hängt von ihrem Inhalt und ihren Belegen ab, nicht von ihrem Etikett. Wer dieselben Kernthesen unter neuem Namen anbietet, bietet dieselbe Lehre an. Hamers Lehre wird seit seinem Tod (2017) unter mehreren Namen weitergeführt, etwa als „5 Biologische Naturgesetze“ oder in der „Meta-Medizin“, die Hamers fünf „Gesetze“ übernimmt. Die Bezeichnung „5 Biologische Naturgesetze“ vermeidet dabei gerade den belasteten Begriff „Germanisch“. Die Lehre wurde also weitergeführt, nicht korrigiert: Die Kernthesen bleiben dieselben, also bleiben auch die Probleme. Der richtige Prüfschritt ist deshalb, die Inhalte mit der bekannten Lehre zu vergleichen und nach unabhängigen Belegen zu fragen, nicht dem Namen zu glauben.","coreRule":"⚡ Prüfe die Lehre, nicht das Etikett: Umbenennen ersetzt keine Belege.","beleg":"Werkstück F.3.1 (Die Autopsie-Akte); Fn. gl-f-14 (Psiram; Apotheken Umschau, abgerufen 23.09.2026)","status":"entwurf","scenario":"Du stößt in einer Messenger-Gruppe auf einen Anbieter, der „5 Biologische Naturgesetze“ als neue Heilmethode bewirbt. Der Name klingt neutral. Auf die Frage nach dem Ursprung sagt er nur, mit der Germanischen Neuen Medizin habe das nichts zu tun.","kurz":"Entscheidend ist, was behauptet wird, nicht wie es heißt: Schock-Konflikt, „sinnvolle Programme“ und gestörte Heilung durch Chemotherapie sind dieselben Kernthesen wie zuvor. Unter neuem Namen angeboten bleibt es dieselbe Lehre.","prueffrage":"Welche Behauptungen stehen hinter dem Namen, und wo hast du sie schon einmal gelesen?","rueckmeldung":[{"option":1,"text":"Eine ausdrückliche Abgrenzung wirkt wie ein Neuanfang. Gesagt ist damit aber nur ein Satz, geändert ist nichts: Der Anbieter zählt selbst dieselben Kernthesen auf, also ist sie inhaltlich nicht gelöst."},{"option":2,"text":"„Gesetze“ klingt nach Verlässlichkeit, ist aber nur ein Etikett, das nichts belegt. Aufgezählte Behauptungen werden nicht dadurch geprüft, dass man sie so nennt; die Lehre wurde weitergeführt, nicht korrigiert."},{"option":3,"text":"Fairness gegenüber dem Anbieter wirkt vernünftig. Die Unschuldsvermutung gilt aber vor Gericht für Personen, nicht für Behauptungen, und die identische Aufzählung zeigt den Zusammenhang ohnehin offen."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“ (Synonyme „fünf biologische Naturgesetze (5bn/5BN)“, „Germanische Heilkunde“)","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Metamedizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Metamedizin","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"0c86eedc4108aeef"}},{"id":"qx-f-055","clusterId":"F","werkstueckRef":"F.4.1","stufe":1,"question":"Eine Freundin erzählt: „Ich glaube an Karma und Reinkarnation, lege aber auch meine Tarotkarten, trage Heilsteine, meditiere zum ‚inneren Kind‘ und glaube an die Kraft der Schwingungen. Eine feste Gemeinschaft oder verbindliche Regeln brauche ich nicht.“ Welche Schlussfolgerung zieht man daraus am sinnvollsten?","options":["Ihre Weltanschauung ist eine selbst zusammengestellte Mischung aus Versatzstücken verschiedener Quellen und Traditionen.","Ihre Weltanschauung ist im Kern hinduistisch oder buddhistisch, weil Karma und Reinkarnation deren zentrale Lehren sind.","Ihre Weltanschauung ist psychologisch fundiert, weil das Konzept des „inneren Kindes“ aus der Psychologie stammt.","Ihre Weltanschauung ist eine bewusste Gegenposition zur Wissenschaft, die deren Ergebnisse ausdrücklich zurückweist."],"correctIndex":0,"explanation":"Karma und Reinkarnation stammen aus indischen Religionen wie Hinduismus und Buddhismus, das „innere Kind“ aus der Psychologie, Kristallheilung (Heilsteine) gehört zu den Pseudowissenschaften. Die Freundin kombiniert solche Versatzstücke nach eigenem Geschmack, ohne feste Dogmen, ohne Gemeinschaft und ohne verbindliche Regeln – ein Baukasten, aus dem man sich wie in einem Supermarkt bedient. Die Elemente werden dabei häufig aus ihrem ursprünglichen Zusammenhang gelöst: Karma etwa gehört in diesen Religionen in einen strengen ethischen Zusammenhang, der hier wegfällt. In solchen selbst zusammengestellten Weltanschauungen gilt oft das eigene Erleben als Maßstab, nicht überprüfbare Evidenz. Dass sich etwas stimmig anfühlt, ist aber kein Test, ob es stimmt.","coreRule":"⚡ Wer sich seine Weltanschauung aus Fertigteilen zusammenbaut, entscheidet nach Gefühl und Geschmack. Dass die Teile zusammenpassen, heißt nicht, dass sie stimmen.","beleg":"Werkstück F.4.1 (Die Anatomie der Lehre: Das Baukasten-Prinzip)","status":"entwurf","scenario":"","kurz":"Sie kombiniert einzelne Elemente aus verschiedenen Quellen nach eigenem Geschmack, ohne Lehre, Gemeinschaft oder feste Regeln. Der naheliegende Fehler ist, vom Ursprung eines Teils auf das Ganze zu schließen, obwohl hier nur Versatzstücke übernommen werden.","prueffrage":"Was sagt die Freundin über Regeln und Gemeinschaft, und was verbindet Tarot, Heilsteine und Karma miteinander?","rueckmeldung":[{"option":1,"text":"Karma und Reinkarnation stammen tatsächlich aus indischen Religionen. Sie übernimmt aber nur einzelne Teile, ohne deren Lehre und den strengen ethischen Zusammenhang, in den Karma dort gehört. Das macht sie nicht zur Anhängerin."},{"option":2,"text":"Das „innere Kind“ kommt wirklich aus der Psychologie. Ein einzelnes Element macht das Ganze aber nicht fundiert, zumal Heilsteine und Schwingungen zu den Pseudowissenschaften gehören."},{"option":3,"text":"Eine Gegenposition zur Wissenschaft liegt nahe, wenn vieles Unbelegte zusammenkommt. Die Freundin sagt aber nichts über Wissenschaft und weist keine Ergebnisse zurück; das wäre eine Unterstellung."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Universität Münster, Exzellenzcluster Religion und Politik (2012): Pressemitteilung „Wenn Familien zweimal Weihnachten feiern – Mehr als ein Fünftel der Deutschen pflegen Patchwork-Religiosität“ (Christel Gärtner)","oeffentlich":true,"url":"https://www.uni-muenster.de/imperia/md/content/religion_und_politik/aktuelles/2012/12_2012/pm_patchwork-religiositaet.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6fe420ee642fe73f"}},{"id":"qx-f-056","clusterId":"F","werkstueckRef":"F.4.1","stufe":2,"question":"Ein Verkäufer entgegnet auf Kritik an seinen Heilsteinen: „Das ist nur deine materialistische Sichtweise, du bist für höhere Wahrheiten nicht offen.“ Was bewirkt diese Antwort für die Prüfbarkeit seiner Behauptung?","scenario":"Du äußerst an einem Stand auf einer Esoterikmesse Zweifel an der Wirkung von Heilsteinen.","options":["Sie macht die Behauptung vorsichtiger, weil der Verkäufer einräumt, dass die Wirkung seiner Heilsteine noch nicht belegt ist.","Sie macht die Behauptung unangreifbar, weil der Verkäufer jeden Zweifel an seinen Heilsteinen als mangelnde Offenheit abtun kann.","Sie macht die Behauptung prüfbarer, weil der Verkäufer eine Messung benennt, an der seine Heilsteine scheitern würden.","Sie stützt die Behauptung, weil der Verkäufer mit den höheren Wahrheiten eine Erklärung für die Wirkung der Heilsteine liefert."],"correctIndex":1,"explanation":"Der Verkäufer behauptet, Heilsteine wirkten. Auf die Kritik antwortet er nicht mit einem Beleg, sondern mit einem Urteil über den Kritiker: Wer zweifelt, sei „nicht offen“. So lässt sich jede wissenschaftliche Kritik abwehren; die Behauptung wird unangreifbar und unfalsifizierbar. Entscheidend ist hier nur der Mechanismus: Kritik wird durch Immunisierung statt durch Belege beantwortet. Die anderen Antworten klingen nach seriösem Vorgehen, passen aber nicht zu seinen Worten: Er räumt mit keinem Wort ein, dass die Wirkung noch unbelegt ist, die Behauptung wird also nicht vorsichtiger. Er benennt auch keine Messung, an der seine Steine scheitern könnten, sondern weist die materialistische Sichtweise zurück, sie wird also nicht prüfbarer. Und die „höheren Wahrheiten“ sind ein Etikett ohne Erklärung oder Beleg, sie stützen die Behauptung nicht.","coreRule":"⚡ Wenn nur das eigene Gefühl zählt, kann kein Gegenbeweis zählen.","beleg":"Werkstück F.4.1 (Die epistemologische Grundlage: Absolute Subjektivität)","status":"entwurf","kurz":"Der Verkäufer bleibt den Beleg schuldig und wertet stattdessen den Zweifler ab: Wer zweifelt, sei „nicht offen“. Damit lässt sich jede Kritik abwehren, die Behauptung wird unangreifbar und kann nie widerlegt werden.","prueffrage":"Worüber spricht der Verkäufer in seiner Antwort: über die Steine oder über die Person, die zweifelt?","rueckmeldung":[{"option":0,"text":"Sicher klingt der Verkäufer nicht, doch ein Eingeständnis, dass die Wirkung unbelegt ist, kommt in seinen Worten nirgends vor. Er weist die Kritik zurück, die Behauptung bleibt so stark wie zuvor."},{"option":2,"text":"Prüfbar wäre die Behauptung, wenn er nennte, woran sie scheitern könnte. Er nennt aber keine Messung und lehnt die materialistische Sichtweise, also die Prüfung selbst, ab. So wird sie schwerer prüfbar, nicht leichter."},{"option":3,"text":"Eine Erklärung würde erläutern, wie die Steine wirken sollen. „Höhere Wahrheiten“ bleiben aber ein Etikett ohne Mechanismus und ohne Beleg. Was sich nicht überprüfen lässt, kann die Behauptung auch nicht stützen."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"12e45688cc516758"}},{"id":"qx-f-057","clusterId":"F","werkstueckRef":"F.4.1","stufe":3,"question":"Eine Bekannte erzählt dir, ihre Schwester habe ihre Krebstherapie abgebrochen und setze nun nur noch auf Energiearbeit und Kristalle. Die Bekannte meint: „Esoterik ist doch eine harmlose Quelle von Trost, jeder darf glauben, was er will.“ Was ist an dieser Einschätzung für den vorliegenden Fall am ehesten falsch?","options":["Sie übersieht, dass der Schaden erst entsteht, wenn das Heilversprechen der Kristalle die wirksame Krebstherapie der Schwester ersetzt, nicht durch den Trost.","Sie übersieht, dass der Glaube der Schwester an Kristalle und Energiearbeit nicht dadurch wahr wird, dass viele ihn teilen und er ihnen hilft.","Sie übersieht, dass jeder, der auf Kristalle und Energiearbeit setzt, deren Wirkung vorher belegen muss, auch wenn sie nur der Beruhigung dienen.","Sie übersieht, dass Kristalle und Energiearbeit aus fremden Kulturen stammen und ihre Übernahme ohne Kenntnis des Ursprungs respektlos ist."],"correctIndex":0,"explanation":"Trost und Inspiration können für viele Menschen harmlos sein. Problematisch wird es dort, wo ein unbelegtes Heilversprechen eine nachweislich wirksame Behandlung verdrängt: Dann steht die Gesundheit auf dem Spiel, und die Berufung auf „jeder darf glauben, was er will“ geht am Kern vorbei. Entscheidend sind die Folgen für konkrete Menschen. Dass viele einen Glauben teilen, sagt zwar nichts über seine Richtigkeit, aber die Bekannte stützt sich gar nicht auf die Zahl der Gläubigen. Wer Kristalle nur zur Beruhigung nutzt, muss dafür keinen Beleg liefern; der Schaden liegt hier in der verdrängten Therapie. Die Herkunft einzelner Praktiken ist ein anderes Thema und ändert nichts an der Gefahr für die Schwester.","coreRule":"⚡ Gefährlich wird eine Weltanschauung nicht durch ihren Trost, sondern dort, wo sie wirksame Behandlung ersetzt oder Mitmenschen aus dem Blick verliert.","beleg":"Werkstück F.4.1 (Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"","kurz":"Trost allein schadet meist niemandem. Zum Problem wird er, wenn ein unbelegtes Heilversprechen die wirksame Krebstherapie verdrängt. „Jeder darf glauben, was er will“ übersieht das, denn es zählen die Folgen für die Schwester.","prueffrage":"Was hat die Schwester konkret aufgegeben, und was kann das bei einer Krebserkrankung bedeuten?","rueckmeldung":[{"option":1,"text":"Dass viele einen Glauben teilen, macht ihn nicht wahr, das stimmt. Die Bekannte stützt sich darauf aber gar nicht, sie nennt Esoterik harmlosen Trost. Der Fehler liegt woanders: im Übersehen der Folgen für die Therapie."},{"option":2,"text":"Wer Kristalle nur zur Beruhigung nutzt, muss deren Wirkung nicht belegen. Ein Beleg wird erst dort wichtig, wo ein Heilversprechen im Spiel ist und eine wirksame Behandlung verdrängt. Als Pflicht für jeden schießt die Forderung über das Ziel hinaus."},{"option":3,"text":"Die Frage der Herkunft wirkt wie ein ernster Einwand, ist aber ein anderes Thema. Selbst wenn man sie klärt, ändert das nichts an der Gefahr, dass die Schwester eine wirksame Krebstherapie abbricht."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Johnson, S. B.; Park, H. S.; Gross, C. P.; Yu, J. B. (2018): „Use of Alternative Medicine for Cancer and Its Impact on Survival“, J Natl Cancer Inst 110(1), S. 121–124 (Abstract öffentlich, PMID 28922780)","oeffentlich":true,"doi":"10.1093/jnci/djx145","abruf":"2026-10-12"},{"typ":"doi","kurz":"Asser, S. M.; Swan, R. (1998): „Child fatalities from religion-motivated medical neglect“, Pediatrics 101(4), S. 625–629 (Abstract öffentlich, PMID 9521945)","oeffentlich":true,"doi":"10.1542/peds.101.4.625","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"0def2c2ecd015eab"}},{"id":"qx-f-058","clusterId":"F","werkstueckRef":"F.4.1","stufe":4,"question":"Ein Freund erklärt: „Ich glaube an Astrologie, Kristallheilung, Reinkarnation und an die Kraft positiven Denkens. Das passt alles zusammen, weil für mich zählt, was sich richtig anfühlt.“ Warum kann ein solches Weltbild praktisch jede unbelegte Behauptung problemlos aufnehmen?","options":["Weil ein Astrologe oder Heiler jede neue Behauptung vorab für ihn prüft und freigibt, sodass er selbst nichts mehr prüfen muss.","Weil seine Gruppe von Gleichgesinnten jeden Zweifel an Astrologie oder Reinkarnation bestraft und Kritiker ausschließt, sodass nur Zustimmung bleibt.","Weil die Angst vor Krankheit und Tod ihn so verletzlich macht, dass er jede Behauptung annimmt, die Hoffnung verspricht, etwa Kristallheilung.","Weil sein Weltbild keine feste Lehre und keinen Maßstab außer dem eigenen Gefühl kennt, sodass Astrologie wie Reinkarnation und alles Weitere hineinpassen."],"correctIndex":3,"explanation":"Ein Weltbild, das sich aus frei gewählten Bausteinen zusammensetzt und als einzigen Maßstab das eigene Gefühl akzeptiert, kennt kein Kriterium, das etwas ausschließen könnte. Wo nichts geprüft wird, kann auch nichts durchfallen: Astrologie, Kristallheilung und Reinkarnation lassen sich daher widerspruchslos nebeneinander einbauen, auch wenn keine davon belegt ist. Hinzu kommt: Kritik lässt sich mit Sätzen wie „Das ist nur deine materialistische Sichtweise“ abwehren, das System ist also nicht widerlegbar (unfalsifizierbar). Ein festes Lehrgebäude hätte dagegen Regeln, die manches ausschließen würden. Die Esoterik ersetzt überprüfbare Evidenz durch subjektive innere Erfahrung und macht sich dadurch immun gegen Kritik. Ein Astrologe, der Behauptungen freigibt, würde das Weltbild an eine Autorität binden, doch der Freund nennt als Maßstab nur sich selbst. Eine Gruppe, die Zweifel bestraft, kommt in seiner Schilderung nicht vor. Angst vor Krankheit mag Menschen empfänglich machen, erklärt aber nicht, warum das Weltbild selbst alles aufnehmen kann.","coreRule":"⚡ Wo nur das eigene Gefühl zählt, kann jedes Modul rein, auch das unbelegte: Ein Weltbild, das nichts ausschließt, belegt nichts.","beleg":"Werkstück F.4.1 (Die Esoterik als Wurzel und Nährboden; Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"Gespräch mit einem Freund über sein persönliches Weltbild.","kurz":"Wo das eigene Gefühl der einzige Maßstab ist, kann nichts durchfallen: Astrologie, Kristallheilung und Reinkarnation passen widerspruchslos zusammen, obwohl keine belegt ist. Kritik lässt sich zudem als „materialistisch“ abwehren.","prueffrage":"Hat der Freund je eine Überzeugung wieder aufgegeben, und was hätte ihn dazu bringen können?","rueckmeldung":[{"option":0,"text":"Eine Instanz, die Behauptungen vorab freigibt, würde sein Weltbild an eine Autorität binden und damit manches ausschließen. Der Freund nennt aber nur sein eigenes Gefühl als Maßstab, und niemand prüft für ihn."},{"option":1,"text":"Gruppendruck kann Weltbilder tatsächlich abschotten. In der Schilderung kommt aber keine Gruppe vor, die Zweifel bestraft. Der Freund beruft sich allein auf sein eigenes Empfinden, und genau dort liegt die Offenheit."},{"option":2,"text":"Angst vor Krankheit und Tod kann Menschen für Hoffnungsversprechen empfänglich machen. Das erklärt aber, warum jemand zugreift, nicht warum das Weltbild selbst alles aufnehmen kann. Im Beispiel ist von Angst auch keine Rede."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3","abruf":"2026-10-12"},{"typ":"url","kurz":"Universität Münster, Exzellenzcluster Religion und Politik (2012): Pressemitteilung zur Patchwork-Religiosität (Christel Gärtner)","oeffentlich":true,"url":"https://www.uni-muenster.de/imperia/md/content/religion_und_politik/aktuelles/2012/12_2012/pm_patchwork-religiositaet.pdf","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b7c5bdf137a62185"}},{"id":"qx-f-059","clusterId":"F","werkstueckRef":"F.4.2","stufe":1,"question":"Auf welche Art von Rechtfertigung stützt sich deine Freundin damit?","options":["Auf Autorität: Die Behauptung gilt als wahr, weil eine Schrift und eine Lehrinstanz sie bestätigen, nicht weil sie geprüft wurde.","Auf Experiment: Die Behauptung wurde unter kontrollierten Bedingungen getestet und hat sich dabei bewährt.","Auf Mehrheit: Die Behauptung gilt als wahr, weil die meisten Menschen auf der Welt sie unabhängig voneinander für richtig halten.","Auf persönliche Erfahrung: Die Behauptung gilt als wahr, weil sie selbst sie erlebt und für sich überprüft hat."],"correctIndex":0,"explanation":"Wer sich auf eine heilige Schrift und eine Lehrinstanz beruft, stützt sich auf Autorität: Die Wahrheit wird in diesem Rahmen nicht durch empirische Experimente entdeckt, sondern durch göttliche Offenbarung empfangen. Über Fragen von Sinn und Ethik hat die Wissenschaft nicht zu entscheiden. Bei überprüfbaren Tatsachenbehauptungen wie dem Alter der Erde betreten Glaubenslehren dagegen das Feld empirischer Prüfung, und Konflikte mit den Befunden sind deshalb angelegt. Dass eine Schrift und eine Gemeinde etwas lehren, ersetzt keine Prüfung.","coreRule":"⚡ Autorität ist keine Prüfung: Eine Aussage gilt nicht schon deshalb als belegt, weil eine Schrift oder Institution sie verkündet.","beleg":"Werkstück F.4.2 (Die epistemologische Grundlage: Offenbarung vs. Realität)","status":"entwurf","scenario":"Du diskutierst mit einer Freundin über die Frage, ob die Erde nur 6.000 Jahre alt ist. Sie entgegnet: „Ich glaube das, weil es in unserer heiligen Schrift steht und unsere Gemeinde es seit Jahrhunderten so lehrt.“","quote":"","quoteLabel":"","kurz":"Die Freundin beruft sich auf Schrift und Gemeindelehre, also auf Autorität. Eine Lehre ersetzt aber keine Prüfung, so alt sie auch ist, besonders bei Tatsachenfragen wie dem Alter der Erde.","prueffrage":"Was hat die Freundin selbst beobachtet oder gemessen, und was hat sie von anderen übernommen?","rueckmeldung":[{"option":1,"text":"Ein Experiment würde etwas Überprüfbares voraussetzen, das irgendwo kontrolliert getestet wurde. Genannt werden aber nur Schrift und Gemeindelehre. Beim Alter der Erde gibt es zwar empirische Befunde, doch auf die stützt sie sich nicht."},{"option":2,"text":"Eine lange Tradition kann nach breiter Zustimmung klingen. Gemeint ist aber nur die eigene Gemeinde, nicht die Mehrheit der Menschen, und deren Lehre wird weitergegeben, nicht von vielen unabhängig gewonnen."},{"option":3,"text":"Ihr Glaube kann sich für sie persönlich echt anfühlen. Als Grund nennt sie aber Schrift und Lehre, kein eigenes Erlebnis oder eine eigene Prüfung. Das Alter der Erde lässt sich ohnehin nicht durch bloßes Erleben überprüfen."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"„Religion and Science“, Stanford Encyclopedia of Philosophy (2017, rev. 2022)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/religion-science/","seite":"Abschnitt 1.3, 2.1, 3.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"09e31fd6f405c16b"}},{"id":"qx-f-060","clusterId":"F","werkstueckRef":"F.4.2","stufe":3,"question":"Worin liegt der entscheidende Unterschied zwischen dem Gespräch, das du als gefährlich einstufen würdest, und den harmlosen?","options":["Gefährlich ist D, weil dort eine überprüfbare Behauptung gegen Belege abgeschirmt und Zweifel als Sünde gebrandmarkt wird.","Gefährlich ist B, weil feste Schriften und eine verbindliche Auslegung durch die Gemeinde das Nachfragen stark erschweren.","Gefährlich ist C, weil große Reichweite und viel Einfluss in einer Stadt eine Gemeinschaft oft zur Bedrohung machen.","Gefährlich ist A, weil Aussagen über Sinn und Lebensführung der Wissenschaft entzogen sind und sich nicht prüfen lassen."],"correctIndex":0,"explanation":"Entscheidend ist, ob eine Aussage prüfbar ist und trotzdem gegen Belege geschützt wird. Ob Gebet eine medizinische Behandlung ersetzt, ist eine überprüfbare Behauptung über die Welt, und ein Irrtum kann hier das Leben des Kindes gefährden. Wird diese Frage zusätzlich mit „Sünde“ belegt, ist Zweifel nicht mehr erlaubt. Sinn, Trost und Gemeinschaft (A) sind keine Tatsachenbehauptungen, über die Belege entscheiden könnten, und feste Schriften (B) oder Einfluss (C) schirmen für sich genommen noch keine prüfbare Behauptung ab. Gefährlich wird es dort, wo prüfbare Behauptungen gegen Belege immunisiert werden, Zweifel als Sünde sanktioniert wird oder Ausgrenzung, Zwang oder Gewalt gerechtfertigt werden.","coreRule":"⚡ Sinn und Moral sind nicht das Problem; prüfbare Behauptungen, die Belege abwehren, sind es.","beleg":"Werkstück F.4.2 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Vier Gespräche über Glauben:\\n\\nA: Eine Frau sagt: „Mein Glaube gibt meinem Leben Sinn und der Gemeinde Halt.“\\nB: Ein Mann sagt: „Meine Religion hat feste Schriften, und unsere Gemeinde legt sie verbindlich aus.“\\nC: Eine Gemeinde unterstützt ihre Mitglieder stark und hat dadurch großen Einfluss in ihrer Stadt.\\nD: Ein Vater sagt: „Unser Sohn braucht keine Antibiotika, Beten heilt ihn. Wer daran zweifelt, versündigt sich.“","kurz":"Entscheidend ist, ob eine prüfbare Behauptung gegen Belege geschützt wird. Ob Beten Antibiotika ersetzt, lässt sich klären; wer Zweifel dazu als Sünde brandmarkt, verbietet die Prüfung. Sinn, Halt und Gemeinschaft stellen gar keine solche Behauptung auf.","prueffrage":"Was stünde in jedem der vier Gespräche auf dem Spiel, wenn sich die Beteiligten irren?","rueckmeldung":[{"option":1,"text":"Feste Schriften und verbindliche Auslegung können Nachfragen erschweren, das ist ein berechtigter Gedanke. Für sich genommen schützen sie aber noch keine prüfbare Behauptung gegen Belege und bestrafen keinen Zweifel; das fehlt in Gespräch B."},{"option":2,"text":"Große Reichweite und viel Einfluss wirken schnell bedrohlich. Sie sagen aber nichts darüber, ob etwas gegen Belege abgeschirmt wird; hier unterstützt die Gemeinde zunächst ihre Mitglieder, und Größe allein ist kein Gefahrenzeichen."},{"option":3,"text":"Dass Sinn und Lebensführung sich nicht wissenschaftlich prüfen lassen, stimmt. Genau deshalb steht dort nichts im Konflikt mit Belegen: Es wird keine Tatsache behauptet, über die Daten entscheiden könnten, also auch nichts gegen Belege geschützt."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Asser, S. M.; Swan, R. (1998): „Child fatalities from religion-motivated medical neglect“, Pediatrics 101(4), S. 625–629 (Abstract öffentlich, PMID 9521945)","oeffentlich":true,"doi":"10.1542/peds.101.4.625","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"bd8d973a94b8ce5e"}},{"id":"qx-f-061","clusterId":"F","werkstueckRef":"F.4.2","stufe":2,"question":"Welche Entgegnung auf diesen Satz ist am stärksten?","options":["Religiöse Menschen handeln im Alltag nachweislich etwas moralischer; trotzdem lässt sich Moral auch säkular begründen.","Nichtreligiöse Menschen handeln im Alltag nachweislich etwas moralischer; trotzdem lässt sich Moral auch säkular begründen.","Moral endet bei jedem Menschen, sobald Geld ins Spiel kommt; trotzdem lässt sich Moral auch säkular begründen.","Moralisches Handeln im Alltag lässt sich schwer erfassen; trotzdem lässt sich Moral auch säkular begründen."],"correctIndex":3,"explanation":"Die Behauptung unterstellt zweierlei: dass es ohne Religion an Moral mangelt und dass es ohne sie keinen verlässlichen Maßstab gibt. Ob religiöse oder nichtreligiöse Menschen im Alltag moralischer handeln, lässt sich nur schwer erfassen, weil Selbstauskünfte ihre Grenzen haben; ein Vorsprung einer der beiden Gruppen ist deshalb nicht belegt (eine große Befragung im Alltag, Hofmann u. a. 2014 in Science, fand keinen Unterschied in den selbst berichteten Handlungen). Begründen lässt sich Moral außerdem auch säkular, etwa über Empathie, Vernunft und den Gesellschaftsvertrag, und selbst die Naturrechtstradition des Thomas von Aquin hält Moralgrundsätze für mit der Vernunft erkennbar. Wer eine Behauptung prüfen will, fragt also: Was würde sie im Alltag vorhersagen, und lässt sich das überhaupt zuverlässig feststellen?","coreRule":"⚡ Wer behauptet, etwas sei die Voraussetzung für Moral, muss zeigen, dass es ohne sie weniger Moral gibt.","beleg":"Werkstück F.4.2 (Ethik und funktionierendes Zusammenleben); Fn. gl-f-hofmann (Hofmann u. a. 2014, Science 345, S. 1340--1343); Fn. gl-f-naturrecht Am 14.10.2026 nach Sturms Urteil umgebaut: Die Studie (Hofmann u. a. 2014) steht nur noch in der Erklärung und in den Quellen, nicht mehr als Voraussetzung einer Option; Option 3 abgeschwächt („schwer erfassen“) und richtig, die frühere richtige Option 2 durch eine unpassende ersetzt.","status":"entwurf","scenario":"Im Gespräch über Werte und Erziehung fällt der Satz: „Ohne Religion gibt es keinen verlässlichen Maßstab für Moral.“ Du willst die Behauptung prüfen, statt sie nur zu glauben oder abzulehnen.","kurz":"Ob religiöse oder nichtreligiöse Menschen im Alltag moralischer handeln, lässt sich schwer erfassen; ein Vorsprung einer Gruppe ist nicht belegt. Und Moral lässt sich auch säkular begründen. Beides spricht gegen den „fehlenden Maßstab“.","prueffrage":"Was müsste man im Alltag religiöser und nichtreligiöser Menschen beobachten, wenn die Behauptung stimmt?","rueckmeldung":[{"option":0,"text":"Der zweite Teil stimmt: Moral lässt sich auch säkular begründen. Ein Vorsprung der Religiösen im Alltag ist aber nicht belegt; eine große Alltagsstudie fand in den selbst berichteten Handlungen beider Gruppen keinen Unterschied."},{"option":1,"text":"Dass sich Moral säkular begründen lässt, stimmt. Ein Vorsprung der Nichtreligiösen ist aber ebenso unbelegt wie die Ausgangsbehauptung, denn die Alltagsdaten zeigen keinen Unterschied zwischen den Gruppen."},{"option":2,"text":"Dass Geld Menschen in Versuchung führen kann, ist eine Beobachtung, aber keine Regel für jeden Menschen. Der Satz sagt nichts darüber, ob Religiöse oder Nichtreligiöse moralischer handeln, und ersetzt weder die Prüfung noch die säkulare Begründung."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Hofmann, W.; Wisneski, D. C.; Brandt, M. J.; Skitka, L. J. (2014): „Morality in everyday life“, Science 345(6202), S. 1340–1343 (Abstract öffentlich, PMID 25214626)","oeffentlich":true,"doi":"10.1126/science.1251560","abruf":"2026-10-12"},{"typ":"url","kurz":"Murphy, M. (2002/2025): „The Natural Law Tradition in Ethics“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/natural-law-ethics/","seite":"Abschnitt 1.2","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"aa1da7f176e81be5"}},{"id":"qx-f-062","clusterId":"F","werkstueckRef":"F.4.2","stufe":4,"question":"In einem Vortrag heißt es: „Im Mittelalter glaubten alle an eine flache Erde, und die Kirche bekämpfte die Wissenschaft von jeher.“ Welche Einschätzung trifft zu?","options":["Die flache Erde ist eine Legende des 19. Jahrhunderts, der „ewige Krieg“ ist übertrieben, echte Einzelkonflikte gab es dennoch.","Beides stimmt im Kern: Die Kirche lehrte die flache Erde und verurteilte deshalb Kopernikus und Galilei als Ketzer.","Beides ist erfunden: Zwischen Kirche und Wissenschaft gab es nie einen nennenswerten Konflikt, auch nicht um Galilei.","Die flache Erde ist belegt, der Konflikt dagegen erfunden: Kirche und Wissenschaft arbeiteten stets harmonisch zusammen."],"correctIndex":0,"explanation":"Gelehrte des Mittelalters wussten, dass die Erde eine Kugel ist. Die Legende von der flachen Erde stammt aus dem 19. Jahrhundert, als Kirchenkritiker sie als Waffe im angeblichen Krieg zwischen Wissenschaft und Religion nutzten. Dass dieser Krieg „ewig“ gewesen sei, ist ebenfalls überzeichnet. Echte Konflikte gab es trotzdem: 1616 kam das Buch des Kopernikus auf den Index (er selbst war schon 1543 gestorben und wurde nie verurteilt), Galilei wurde 1633 verurteilt, und kreationistische Strömungen in manchen Religionsgemeinschaften bestreiten bis heute die Evolutionslehre. Die Streitfälle betrafen also das Weltbild und die Evolution, nicht die Kugelgestalt der Erde.","coreRule":"⚡ Der Konflikt war real, aber nicht ewig und nicht um die Kugelgestalt der Erde.","beleg":"Werkstück F.4.2 (Die epistemologische Grundlage); Fn. gl-f-flacheerde (Garwood 2008; Leisman 2019); Fn. gl-f-konflikt (Numbers 2009, S. 1 und 6)","status":"entwurf","kurz":"Die flache Erde im Mittelalter ist eine Legende des 19. Jahrhunderts, und der „ewige Krieg“ ist überzeichnet. Echte Streitfälle gab es trotzdem, etwa um Kopernikus und Galilei, und solche Zuspitzungen verführen dazu, Pauschalurteile zu übernehmen.","prueffrage":"Was schrieben Gelehrte des Mittelalters selbst über die Gestalt der Erde, und welche Streitfälle zwischen Kirche und Forschung sind mit Anlass und Datum überliefert?","rueckmeldung":[{"option":1,"text":"Die Konflikte sind real: Das Buch des längst toten Kopernikus kam 1616 auf den Index, Galilei wurde 1633 verurteilt. Sie betrafen aber das Weltbild, nicht die Erdform: Gelehrte des Mittelalters wussten, dass die Erde eine Kugel ist."},{"option":2,"text":"Die flache Erde ist tatsächlich eine Legende, und der „ewige Krieg“ ist überzeichnet. Ein „nie“ geht aber zu weit: Die Indizierung des Kopernikus 1616, Galileis Verurteilung 1633 und der Streit um den Kreationismus sind echte Konflikte."},{"option":3,"text":"Dass der angebliche Dauerkrieg übertrieben ist, stimmt. Die flache Erde ist aber gerade nicht belegt, und „stets harmonisch“ blendet echte Konflikte wie den Fall Galilei aus."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Russell, J. B. (1997): „The Myth of the Flat Earth“, Vortrag, American Scientific Affiliation","oeffentlich":true,"url":"https://www.asa3.org/ASA/topics/history/1997Russell.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Miller, D. M. (2005/2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","seite":"Abschnitt 2 und 5","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Numbers, R. L. (Hg.) (2009): Galileo Goes to Jail and Other Myths about Science and Religion. Harvard University Press (Einleitung S. 1, 6; Cormack, Myth 3, S. 28–34)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e44144f5f70db009"}},{"id":"qx-f-063","clusterId":"F","werkstueckRef":"F.4.3","stufe":1,"question":"Welche Frage prüft diese Behauptung am besten?","options":["Welche realen Ängste ihrer Entstehungszeit bündeln Zombiefilme, und was in Geschichte und Erzählung spricht dafür?","Wie viele Menschen sahen Zombiefilme im Kino, und was in den Einspielergebnissen spricht für ihre Beliebtheit?","Mit welchen Maskentechniken werden Zombies im Film dargestellt, und was in Technik und Handwerk spricht für ihren Erfolg?","Aus welcher Tradition stammt das Wort Zombie, und was in der Volksüberlieferung Haitis spricht für seine heutige Bedeutung?"],"correctIndex":0,"explanation":"Die Frage macht die Deutung prüfbar: Welche Ängste und Spannungen ihrer Entstehungszeit bündeln Zombiefilme, und was spricht dafür oder dagegen? Der moderne Zombie lässt sich etwa als Bild für die Angst vor dem Verlust der Individualität lesen, in einer Masse, die nur noch konsumiert oder sich ansteckt. Das ist eine Lesart, kein Nachweis, aber sie nimmt die Zufallsbehauptung ernst und lässt sich an Geschichte und Erzählung überprüfen.","coreRule":"⚡ Zeig mir dein Monster, und ich sage dir, wovor sich deine Zeit fürchtet.","beleg":"Werkstück F.4.3 (Kernidee; Die Autopsie der drei Archetypen; Red Flags)","status":"entwurf","scenario":"Eine Podcast-Hörerin sagt: „Zombiefilme sind doch nur Unterhaltung. Dass sie gerade in Zeiten von Massenkonsum und Pandemien so beliebt sind, ist Zufall.“","kurz":"Die Behauptung wird prüfbar, wenn du fragst, welche Ängste ihrer Zeit die Filme bündeln. Wer nur Zuschauerzahlen, Technik oder Wortherkunft ansieht, erklärt Beliebtheit, Machart oder Namen, nicht aber, ob der Zeitpunkt Zufall ist.","prueffrage":"Gab es auch Jahrzehnte, in denen Zombiefilme beliebt waren, ohne dass Massenkonsum oder Seuchen die Menschen beschäftigten?","rueckmeldung":[{"option":1,"text":"Hohe Besucherzahlen zeigen, dass die Filme ankommen, und das lässt sich gut zählen. Warum sie gerade in bestimmten Zeiten ankommen, sagen die Zahlen aber nicht, und nur dort könnte der Zufall widerlegt werden."},{"option":2,"text":"Maskentechnik erklärt vielleicht, wie die Filme gemacht sind. Handwerk ist aber zu allen Zeiten verfügbar und erklärt deshalb kaum, warum das Motiv gerade in bestimmten Phasen Konjunktur hat."},{"option":3,"text":"Dass das Wort aus der haitianischen Überlieferung stammt, ist für sich interessant und stimmt. Die Herkunft des Namens sagt aber nichts darüber, ob die heutige Beliebtheit des Motivs Zufall ist."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Grupe, D. (2014): „Faszination Zombie“, Schwäbische Zeitung (schwaebische.de), mit Aussagen von Gudrun Rath, Universität Konstanz","oeffentlich":true,"url":"https://www.schwaebische.de/panorama/faszination-zombie-762677","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ackermann, H.-W.; Gauthier, J. (1991): „The Ways and Nature of the Zombi“, Journal of American Folklore 104(414), S. 466–494","oeffentlich":false,"seite":"S. 467, 489"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"0123c18494978780"}},{"id":"qx-f-064","clusterId":"F","werkstueckRef":"F.4.3","stufe":2,"question":"Ein Vortrag sagt: „Die Vampirlegende zeigt die Angst der Bauern vor dem adeligen Ausbeuter, siehe die Fälle von 1725 und 1732.“ Was ist an dieser Begründung fehlerhaft?","options":["Die Fälle von 1725 und 1732 betrafen Adelige, die ihre Untertanen aussaugten; die Deutung ist daher durch sie gedeckt.","Der Vampir stand in jeder Epoche allein für Seuchen und nie für gesellschaftliche Ausbeutung; die Deutung ist daher grundsätzlich falsch.","Die Fälle von 1725 und 1732 betrafen tote Dorfbewohner; der adelige Vampir ist erst eine spätere literarische Erfindung.","Die Fälle von 1725 und 1732 sind erfunden; aus dieser Zeit gibt es keine Berichte über Vampire oder Wiedergänger."],"correctIndex":2,"explanation":"Die Belege tragen die Deutung nicht: Die Fälle von 1725 (Plogojowitz) und 1732 (Paole) sind durch zeitgenössische amtliche Berichte gut belegt, betrafen aber tote Dorfbewohner, die als Wiedergänger galten, keine Adeligen. Den adeligen Verführer erfand John Polidori erst 1819 mit „The Vampyre“, Bram Stoker gab ihm 1897 seine endgültige Gestalt. Die Deutung als Bild für Ausbeutung passt also auf die Literaturfigur, nicht auf die Fälle, die der Vortrag als Beleg anführt. Seuchenangst und tabuisierte Sexualität sind weitere Hintergründe des Vampirmotivs.","coreRule":"⚡ Prüfe, ob der angeführte Beleg die Deutung wirklich trägt: Die Metapher vom adeligen Parasiten passt zum literarischen Vampir, nicht zu den Fällen des 18. Jahrhunderts.","beleg":"Werkstück F.4.3 („Der Vampir (Der adelige Parasit)“); Fn. gl-f-vampir-adel (Flückinger 1732; Bunson 2000; Bane 2010; Bräunlein 2015; Bohn 2008)","status":"entwurf","kurz":"Die angeführten Fälle betrafen tote Dorfbewohner, keine Adeligen; der adelige Vampir kam erst 1819 in der Literatur auf. Wer eine Deutung durch Fälle belegt, muss prüfen, ob diese Fälle überhaupt zur Deutung passen.","prueffrage":"Wer genau waren die Betroffenen in den Fällen von 1725 und 1732, und was berichten die damaligen Akten über sie?","rueckmeldung":[{"option":0,"text":"Solange man die Fälle nicht nachschlägt, wirkt die Deutung gedeckt. In den Fällen von 1725 und 1732 ging es aber um tote Dorfbewohner, nicht um Adelige, die ihre Untertanen aussaugten."},{"option":1,"text":"Seuchenangst ist tatsächlich ein wichtiger Hintergrund des Vampirmotivs, aber nicht der einzige. Die Ausbeutungsdeutung ist nicht grundsätzlich falsch: Sie passt auf die adelige Literaturfigur, nur nicht auf die angeführten Fälle."},{"option":3,"text":"Zweifel an alten Quellen sind oft berechtigt. Über beide Fälle gibt es aber zeitgenössische amtliche Berichte. Der Fehler der Begründung liegt woanders: Die Betroffenen waren tote Dorfbewohner, keine Adeligen."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Bräunlein, P. J. (2015): „Furchterregende Randzonen der Aufklärung: Skandalon Vampirismus“, Zeitschrift für Anomalistik 15, S. 55–87 (Repositorium Univ. Tübingen)","oeffentlich":true,"doi":"10.15496/publikation-39362","seite":"S. 61, 63","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schneider, N. (2024): „Virale Monster: Spuren infektiöser Krankheiten im Vampirismus & die Konstruktion ansteckender Identität“, Thewis 11, S. 92–113","oeffentlich":true,"doi":"10.21248/thewis.11.2024.139","seite":"S. 97, 99","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0f08af5af013157c"}},{"id":"qx-f-065","clusterId":"F","werkstueckRef":"F.4.3","stufe":3,"question":"Eine Schlagzeile behauptet: „Wissenschaftler haben das Rätsel gelöst: Vampire gab es nie, es waren Menschen mit Porphyrie!“ Wie solltest du diese Aussage einordnen?","options":["Als zu starke Behauptung: Eine Krankheit mag zum Mythos beigetragen haben, doch Ähnlichkeit einzelner Symptome beweist nicht, dass Porphyrie ihn vollständig erklärt.","Als Berufung auf die Tradition: Die Schlagzeile hält die Porphyrie-Deutung für richtig, nur weil sie seit langer Zeit so überliefert wird, und überzeugt deshalb nicht.","Als Zirkelschluss: Die Schlagzeile begründet die Porphyrie-Deutung mit dem Rätsel, das sie damit gelöst haben will, und dreht sich im Kreis, sodass sie nichts erklärt.","Als Strohmann: Die Schlagzeile verzerrt die Vampirsage zur Behauptung, Vampire seien wirkliche Wesen gewesen, damit sich die Porphyrie-Deutung leichter durchsetzt."],"correctIndex":0,"explanation":"Die Schlagzeile schließt von einer Ähnlichkeit einzelner Symptome auf eine vollständige Erklärung. Das trägt nicht: Die Porphyrie-These ist in der Fachwelt umstritten. Winkler und Anderson bezeichnen sie als eher Gerücht denn als wissenschaftliche Theorie, ihr Urheber Dolphin habe sie nie veröffentlicht. Für Blutdurst bei Porphyriekranken oder eine Linderung durch Bluttrinken gibt es keinen Beleg. Der Vampir des Volksglaubens ging zudem auch bei Tageslicht um, die Lichtscheu kam erst später durch Filme wie „Nosferatu“ (1922) ins Vampirbild. Dasselbe gilt für die Tollwut-These: Auch dort wird Tollwut nur als einer von mehreren möglichen Beiträgen zu Werwolf- und Vampirlegenden verstanden. Eine medizinische Parallele kann ein Echo sein. Ob sie eine Erklärung ist, zeigt erst ein Beleg dafür, dass die Krankheit die Geschichte tatsächlich hervorgebracht hat. Wer Ähnlichkeit mit Ursache gleichsetzt, ersetzt die Prüfung durch eine passende Geschichte. Eine Berufung auf die Tradition liegt nicht vor, denn die Schlagzeile stellt sich gegen die überlieferte Deutung, statt sich auf sie zu stützen. Ein Zirkelschluss lässt sich ebenfalls nicht erkennen, weil gar keine Begründung genannt wird, die ihre eigene Behauptung voraussetzt. Und ein Strohmann fehlt, denn die Vampirsage wird nicht verzerrt wiedergegeben: Der Volksglaube hielt Vampire tatsächlich für wirklich.","coreRule":"⚡ Eine Ähnlichkeit ist ein Hinweis, kein Beweis: Medizinische Parallelen liefern ein Echo, nicht automatisch die ganze Erklärung.","beleg":"Werkstück F.4.3 (Das medizinische Echo); Fn. gl-f-11 (Gómez-Alonso 1998; Wasik, Murphy 2012); Fn. gl-f-12 (Winkler, Anderson 1990)","status":"entwurf","scenario":"","kurz":"Eine Krankheit mag Züge des Mythos spiegeln, doch ähnliche Symptome beweisen keine vollständige Erklärung. Dafür fehlt der Beleg, dass Porphyrie die Vampirgeschichte hervorgebracht hat, und die These gilt in der Fachwelt als umstritten.","prueffrage":"Welche Merkmale des Vampirs im alten Volksglauben passen zu den Symptomen, und für welche gibt es überhaupt einen Beleg?","rueckmeldung":[{"option":1,"text":"Überlieferte Deutungen werden oft nur wiederholt, deshalb liegt der Verdacht nahe. Hier läuft es aber umgekehrt: Die Schlagzeile stellt sich gegen die überlieferte Vampirdeutung, statt sich auf sie zu stützen. Zu bemängeln ist die Überschärfe, nicht die Tradition."},{"option":2,"text":"Das Wort „gelöst“ klingt, als stehe die Behauptung ohne Begründung da, und das erinnert an einen Kreis. Ein Zirkelschluss bräuchte aber eine Begründung, die ihr Ergebnis schon voraussetzt, und die Schlagzeile nennt gar keine. Ihr Fehler ist, dass sie zu viel behauptet."},{"option":3,"text":"Weil die Schlagzeile die Sage knapp zusammenfasst, wirkt sie vielleicht wie eine Verzerrung. Tatsächlich hielt der Volksglaube Vampire aber für wirklich, es wird also nichts falsch dargestellt. Der Fehler liegt in der eigenen übergroßen Behauptung, nicht in einem unterstellten Gegner."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Cox, A. M. (1995): „Porphyria and vampirism: another myth in the making“, Postgraduate Medical Journal 71(841), S. 643–644 (PMC2398345)","oeffentlich":true,"doi":"10.1136/pgmj.71.841.643-a","seite":"S. 643 f.","abruf":"2026-10-12"},{"typ":"doi","kurz":"Gómez-Alonso, J. (1998): „Rabies: a possible explanation for the vampire legend“, Neurology 51(3), S. 856–859 (Abstract öffentlich)","oeffentlich":true,"doi":"10.1212/wnl.51.3.856"},{"typ":"literatur","kurz":"Winkler, M. G.; Anderson, K. E. (1990): „Vampires, Porphyria, and the Media: Medicalization of a Myth“, Perspectives in Biology and Medicine 33(4), S. 598–611, DOI 10.1353/pbm.1990.0051","oeffentlich":false,"seite":"S. 598, 600, 606"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"34208a2837830192"}},{"id":"qx-f-066","clusterId":"F","werkstueckRef":"F.4.3","stufe":4,"question":"Was ist an dieser Sprache problematisch, und woran erkennst du es?","scenario":"Ein Redner nennt eine Minderheit eine „Seuche“ und „Bestien“, vor denen man das Land schützen müsse.","options":["Es liegt Entmenschlichung vor: Die Minderheit wird als „Seuche“ und „Bestien“ zum Monster erklärt und zur Zielscheibe, gegen die Hass und Gewalt gerechtfertigt erscheinen.","Es liegt ein Euphemismus vor: Der Redner umschreibt harte Tatsachen über die Minderheit mit milden Wörtern, sodass die Zuhörer die Tragweite des Geschehens nicht erkennen.","Es liegt ein Strohmann vor: Der Redner verzerrt die Haltung der Minderheit zur Karikatur, damit sie sich leichter angreifen lässt, ohne dass ihre Position geprüft wird.","Es liegt ein Dammbruchargument vor: Der Redner leitet aus einem ersten Zugeständnis an die Minderheit ohne Beleg eine Kette immer schlimmerer Folgen für das Land ab."],"correctIndex":0,"explanation":"In Geschichten sind Monster Spiegel von Ängsten: Man projiziert die Furcht in eine erfundene Figur, bekämpft sie und erlebt eine symbolische Entlastung. Dabei trifft die Gewalt niemanden. Hier läuft es umgekehrt: Das Monster-Bild wird auf reale Menschen gelegt. Wer als „Bestie“ oder „Seuche“ gilt, wird entmenschlicht, und gegen eine Seuche darf man alles tun. So lenkt Propaganda reale Ängste auf ein Feindbild, und die Geschichte zeigt, dass entmenschlichende Propaganda Gewalt vorbereiten kann. Beschönigt wird hier nichts, die Wörter sind im Gegenteil drastisch, ein Euphemismus ist es also nicht. Einen Strohmann gibt es nicht, weil der Redner gar keine Position der Minderheit wiedergibt, die er verzerren könnte. Und ein Dammbruchargument fehlt, denn von einem Zugeständnis und einer Kette von Folgeschritten ist nirgends die Rede.","coreRule":"⚡ Monster in der Fiktion sind Spiegel; Monster-Sprache über Menschen ist Entmenschlichung.","beleg":"Werkstück F.4.3 (Anwendung & Relevanz: Im Verständnis von Propaganda; Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer als „Seuche“ oder „Bestie“ gilt, ist kein Mensch mehr, und gegen eine Seuche scheint alles erlaubt. Der Denkfehler liegt darin, ein Monster-Bild, das nur Ängste spiegelt, auf reale Menschen zu legen. Das kann Gewalt vorbereiten.","prueffrage":"Was bliebe von der Forderung des Redners übrig, wenn er dieselbe Gruppe in ruhigem Ton und mit Zahlen beschriebe?","rueckmeldung":[{"option":1,"text":"Ein Euphemismus verharmlost, hier ist aber das Gegenteil der Fall: „Seuche“ und „Bestien“ sind drastisch und abwertend. Die Tragweite wird also nicht verschleiert, sondern der Minderheit wird ihr Menschsein abgesprochen."},{"option":2,"text":"Ein Strohmann setzt voraus, dass eine Position der Minderheit verzerrt wiedergegeben wird. Der Redner gibt aber keine Haltung der Minderheit wieder, sondern setzt sie pauschal herab. Es gibt nichts, was er zur Karikatur machen könnte."},{"option":3,"text":"Für ein Dammbruchargument bräuchte es ein erstes Zugeständnis und eine Kette immer schlimmerer Folgen. Beides kommt im Szenario nicht vor. Der Redner schürt Angst vor einer Gefahr für das Land, aber nicht durch eine solche Folgenkette."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"United States Holocaust Memorial Museum: „Nazi Propaganda“, Holocaust Encyclopedia","oeffentlich":true,"url":"https://encyclopedia.ushmm.org/content/en/article/nazi-propaganda","abruf":"2026-10-12"},{"typ":"doi","kurz":"Over, H. (2021): „Seven Challenges for the Dehumanization Hypothesis“, Perspectives on Psychological Science 16(1), S. 3–13 (PMC7809340)","oeffentlich":true,"doi":"10.1177/1745691620902133","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Haslam, N. (2006): „Dehumanization: An Integrative Review“, Personality and Social Psychology Review 10(3), S. 252–264, DOI 10.1207/s15327957pspr1003_4","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"eafbfc7da7b7286c"}}]`);export{t as n,n as t};